                    if _mom_audit: _ta["momentum_successes"]+=1
                    if _slow_audit: _ta["slowdown_successes"]+=1
                    order[i-1],order[i]=order[i],order[i-1]
                    gaps[i]=max(0.07,gaps[i]*0.45)
