def _v320_teishi_cars_from_text(result_text: str) -> list[int]:
    """結果本文の「/停止」を発走前除外車番として抽出。

    着順が「-」の行ブロック内に `/停止` がある車だけを対象にする。
    近傍の完走車（例: 2番）を誤って拾わない。
    """
    found: set[int] = set()
    raw = str(result_text or "")
    normalized = re.sub(r"[\t\u3000]+", " ", raw)
    block = normalized
    if "着順" in block:
        block = block[block.find("着順"):]
    if "グランドノート" in block:
        block = block.split("グランドノート", 1)[0]
    if "払戻金" in block:
        block = block.split("払戻金", 1)[0]
    # 着順「-」始まりのブロック単位で /停止 を探す
    # 例:
    # - 3
    # 亀井　政和
    # ...
    # 0.00 /停止
    for m in re.finditer(
        r"(?:^|\n)\s*[-－]\s*([1-8])\b([\s\S]*?)(?=(?:\n\s*[-－]\s*[1-8]\b)|\Z)",
        block,
        flags=re.MULTILINE,
    ):
        car = int(m.group(1))
        chunk = m.group(2) or ""
        # 次の着順行の手前まで。完走行(数字始まり)を跨がないよう先頭付近だけ見る
        head = "\n".join(chunk.splitlines()[:8])
        if re.search(r"/\s*停止\b", head) or re.search(r"(?:^|\s)停止\s*$", head, re.MULTILINE):
            found.add(car)
    # 横一列「- 3 ... /停止」
    for m in re.finditer(r"(?:^|\n)\s*[-－]\s*([1-8])\b[^\n]{0,120}/\s*停止", block, flags=re.MULTILINE):
        found.add(int(m.group(1)))
    return sorted(found)


def _v320_reclassify_teishi_as_kessha(meta: dict, rows, result_text: str = "") -> tuple[dict, list[int]]:
    """停止車を発走後事故から欠車（発走前除外）へ移す。

    予測時点で停止車は出走表に出ない／除外されるのが自然。
    engine が「- 3 … /停止」を競走中止等扱いにしていたのをここで矯正する。
    """
    meta_out = dict(meta or {})
    teishi = set(_v320_teishi_cars_from_text(result_text))
    # meta 上の事故理由が停止・競走中止等だけで本文に停止がある車も拾う
    inc = meta_out.get("発走後事故車") or {}
    if isinstance(inc, dict):
        for car, reason in list(inc.items()):
            try:
                c = int(car)
            except Exception:
                continue
            rs = str(reason or "")
            if "停止" in rs or (c in teishi):
                teishi.add(c)
    if not teishi:
        return meta_out, []

    # 欠車側へ（None/"None" 等は捨てる）
    kessha = set()
    for x in (meta_out.get("欠車車番") or meta_out.get("事前除外車番") or []):
        try:
            s = str(x).strip()
            if s.isdigit():
                kessha.add(int(s))
        except Exception:
            pass
    kessha |= set(int(c) for c in teishi)
    reasons = dict(meta_out.get("事前除外理由") or {})
    for c in teishi:
        reasons[str(c)] = "停止"
    meta_out["欠車車番"] = sorted(kessha)
    meta_out["事前除外車番"] = sorted(kessha)
    meta_out["比較対象外車番"] = sorted(kessha)
    meta_out["事前除外理由"] = reasons

    # 発走後事故から除去
    if isinstance(inc, dict):
        inc2 = {int(k): v for k, v in inc.items() if int(k) not in teishi}
        if inc2:
            meta_out["発走後事故車"] = dict(sorted(inc2.items()))
            meta_out["発走後事故車番"] = sorted(inc2)
            meta_out["発走後事故理由"] = {str(k): v for k, v in sorted(inc2.items())}
        else:
            for k in (
                "発走後事故車", "発走後事故車番", "発走後事故理由",
                "発走後事故", "事故レース", "事故あり",
                "予測精度評価対象外", "学習対象外", "学習除外",
                "learning_excluded", "learning_exclusion_reason", "学習除外理由",
            ):
                meta_out.pop(k, None)
            meta_out["発走後事故"] = False
            meta_out["事故レース"] = False
            meta_out["事故あり"] = False
            meta_out["学習除外"] = False
            meta_out["learning_excluded"] = False
            meta_out["AI学習対象"] = True
            meta_out["予測精度評価対象"] = True
            meta_out["予測精度評価対象外"] = False
            meta_out["選手履歴学習対象"] = True
            meta_out["展開学習対象"] = True
            meta_out["重み更新対象"] = True
            if str(meta_out.get("レース状態") or "") == "発走後事故":
                meta_out["レース状態"] = "通常"

    # 発走車番から停止を外す（欠車は発走していない）
    started = meta_out.get("発走車番") or []
    try:
        started2 = [int(x) for x in started if int(x) not in teishi]
        meta_out["発走車番"] = started2
    except Exception:
        pass

    # rows の事故欄が停止なら欠車表記へ
    try:
        if isinstance(rows, pd.DataFrame) and not rows.empty and "車番" in rows.columns:
            cars = pd.to_numeric(rows["車番"], errors="coerce")
            for idx, car in cars.items():
                if pd.isna(car) or int(car) not in teishi:
                    continue
                if "事故" in rows.columns:
                    rows.at[idx, "事故"] = "停止"
                if "結果区分" in rows.columns:
                    rows.at[idx, "結果区分"] = "欠車"
    except Exception:
        pass
    return meta_out, sorted(teishi)


def _v224_restore_nonstarter_rows(result_text: str, meta: dict, rows: pd.DataFrame) -> tuple[dict, pd.DataFrame, list[int]]:
    if not isinstance(rows, pd.DataFrame) or rows.empty:
        return meta, rows, []

    raw = str(result_text or "")
    if not raw:
        return meta, rows, []

    # 公式結果では「- 4 選手名 ... /欠車」のように掲載される。
    # 改行・タブ・全角空白の揺れを許容して、事故語の直前にある車番を拾う。
    normalized = re.sub(r"[\t\u3000]+", " ", raw)
    accident_words = r"欠車|発走除外|競走除外|出走取消|出走取り消し|停止"
    detected: list[tuple[int, str]] = []

    # まず事故語を含む周辺ブロックから「着順 - の次にある車番」を優先取得。
    block_pattern = re.compile(
        rf"(?:^|\n)\s*-\s*(?:\n|\s)+([1-8])(?:\s|\n)+(.{{0,160}}?)(?:/\s*)?({accident_words})(?=\s|$)",
        re.MULTILINE | re.DOTALL,
    )
    for m in block_pattern.finditer(normalized):
        car_no = int(m.group(1))
        reason = str(m.group(3))
        _ = detected.append((car_no, reason))

    # 保存テキストの整形によって1行化されている場合の補助。
    if not detected:
        line_pattern = re.compile(rf"-\s*([1-8])\b[^\n]{{0,220}}?({accident_words})")
        for m in line_pattern.finditer(normalized):
            _ = detected.append((int(m.group(1)), str(m.group(2))))

    if not detected:
        return meta, rows, []

    existing = set()
    if "車番" in rows.columns:
        existing = set(pd.to_numeric(rows["車番"], errors="coerce").dropna().astype(int).tolist())

    added: list[int] = []
    out = rows.copy()
    for car_no, reason in detected:
        if car_no in existing:
            # 既に行がある場合も事故欄だけ補完する。
            mask = pd.to_numeric(out["車番"], errors="coerce") == car_no if "車番" in out.columns else None
            if mask is not None:
                for col in ("事故", "異常", "異", "備考", "事故内容"):
                    if col in out.columns:
                        out.loc[mask, col] = "事前除外"
            continue

        row = {col: None for col in out.columns}
        if "車番" in row:
            row["車番"] = car_no
        if "着順" in row:
            row["着順"] = 999
        for col in ("試走T", "競走T", "ST"):
            if col in row:
                row[col] = 0.0
        for col in ("事故", "異常", "異", "備考", "事故内容"):
            if col in row:
                row[col] = "事前除外"
        # 事故欄が元DataFrameにない場合でも、engine側が参照できる共通列を追加する。
        if not any(col in out.columns for col in ("事故", "異常", "異", "備考", "事故内容")):
            out["事故"] = ""
            row["事故"] = "事前除外"
        out = pd.concat([out, pd.DataFrame([row])], ignore_index=True)
        existing.add(car_no)
        _ = added.append(car_no)

    meta_out = dict(meta or {})
    detected_numbers = sorted({int(car_no) for car_no, _reason in detected})
    if detected_numbers:
        meta_out["事前除外車番"] = detected_numbers
        meta_out["欠車車番"] = detected_numbers
        meta_out["比較対象外車番"] = detected_numbers
        meta_out["事前除外理由"] = {str(int(car_no)): str(reason) for car_no, reason in detected}
        meta_out["実出走数"] = int(len(out) - len(detected_numbers))
        meta_out["予測照合用出走数"] = int(len(out))
    return meta_out, out, sorted(set(added))


def _v315_detect_kessha_cars(result_text: str, rows: pd.DataFrame | None = None) -> list[int]:
    """結果本文と解析表から欠車・発走前除外の車番を取る。"""
    found: set[int] = set()
    raw = str(result_text or "")
    normalized = re.sub(r"[\t\u3000]+", " ", raw)
    words = r"欠車|発走除外|競走除外|出走取消|出走取り消し|停止"
    for m in re.finditer(
        rf"(?:^|\n)\s*[-－]\s*([1-8])\b[\s\S]{{0,280}}?(?:/\s*)?({words})",
        normalized,
        flags=re.MULTILINE,
    ):
        found.add(int(m.group(1)))
    for m in re.finditer(rf"\b([1-8])\s*番?[^\n]{{0,80}}(?:/\s*)?({words})", normalized):
        found.add(int(m.group(1)))
    if isinstance(rows, pd.DataFrame) and not rows.empty and "車番" in rows.columns:
        cars = pd.to_numeric(rows["車番"], errors="coerce")
        status_cols = [c for c in ("事故", "異常", "異", "備考", "事故内容", "着順") if c in rows.columns]
        for idx, car in cars.items():
            if pd.isna(car):
                continue
            blob = " ".join(str(rows.at[idx, c]) for c in status_cols)
            if re.search(words, blob):
                found.add(int(car))
            finish = rows.at[idx, "着順"] if "着順" in rows.columns else None
            race_t = rows.at[idx, "競走T"] if "競走T" in rows.columns else None
            try:
                finish_s = str(finish).strip()
            except Exception:
                finish_s = ""
            if finish_s in {"-", "－", "欠車", "None", "nan"}:
                if re.search(words, raw) or (pd.to_numeric(pd.Series([race_t]), errors="coerce").fillna(1).iloc[0] == 0):
                    found.add(int(car))
    return sorted(found)


def _v315_drop_kessha_rows(rows: pd.DataFrame, kessha: list[int]) -> pd.DataFrame:
    if not isinstance(rows, pd.DataFrame) or rows.empty or not kessha or "車番" not in rows.columns:
        return rows
    cars = pd.to_numeric(rows["車番"], errors="coerce")
    return rows.loc[~cars.isin(set(int(x) for x in kessha))].copy()


def _v319_detect_kessha_from_card_text(text: str) -> list[int]:
    """出走表テキストから欠車・出走取消の車番を抽出。"""
    s = str(text or "")
    if not s.strip():
        return []
    found: set[int] = set()
    for m in re.finditer(
        r"(?m)^(?:予想印\s*)?([1-8])\s*[\t\s]+[^\n]{0,80}\n[^\n]*欠車",
        s,
    ):
        found.add(int(m.group(1)))
    for m in re.finditer(r"(?m)^(?:予想印\s*)?([1-8])\s*[\t\s]+[^\n]{0,60}欠車", s):
        found.add(int(m.group(1)))
    for m in re.finditer(r"([1-8])\s*番[^\n]{0,40}欠車", s):
        found.add(int(m.group(1)))
    for m in re.finditer(
        r"(?m)^([1-8])\t[^\n]+\n(?:[^\n]*\n){0,3}[^\n]*欠車",
        s,
    ):
        found.add(int(m.group(1)))
    for m in re.finditer(r"(?m)^([1-8])\s+.*欠車", s):
        found.add(int(m.group(1)))
    return sorted(found)


def _v319_detect_kessha_from_players(players: list) -> list[int]:
    """出走表パース結果から欠車車番を取る。"""
    out = []
    for p in players or []:
        if not isinstance(p, dict):
            continue
        if p.get("kessha") or p.get("欠車"):
            try:
                _ = out.append(int(p.get("car")))
            except Exception:
                pass
    return sorted(set(out))



# Ver227: 発走後の事故・反則は、結果と回収率だけ保存し、予測精度・AI学習から除外する。
def _v227_detect_poststart_incidents(result_text: str, meta: dict) -> tuple[dict, list[dict]]:
    raw = str(result_text or "")
    if not raw:
        return dict(meta or {}), []
    normalized = re.sub(r"[\t\u3000]+", " ", raw)
    # 欠車・出走取消は発走前除外。ここでは発走後事故のみ。
    words = r"反妨|反則妨害|妨害失格|反則失格|落車|他落|落妨|競走中止|周回誤認|周誤|故障"
    # 「失格」単体は払戻説明や脚注に出やすいので、スラッシュ付きのみ採用する
    words_slash = words + r"|失格"
    found: list[dict] = []
    # 公式結果の「- 6 選手名 ... /反妨」形式を優先（スラッシュ必須に近い）
    pat = re.compile(
        rf"(?:^|\n)\s*-\s*([1-8])\b[^\n]{{0,200}}?/\s*({words_slash})(?=\s|$)",
        re.MULTILINE,
    )
    for m in pat.finditer(normalized):
        _ = found.append({"車番": int(m.group(1)), "理由": str(m.group(2))})
    if not found:
        # フォールバック: 着順が "-" の行に事故語がある場合のみ
        line_pat = re.compile(
            rf"(?:^|\n)\s*-\s*([1-8])\b[^\n]{{0,200}}?({words})(?=\s|$)",
            re.MULTILINE,
        )
        for m in line_pat.finditer(normalized):
            _ = found.append({"車番": int(m.group(1)), "理由": str(m.group(2))})
    unique=[]
    seen=set()
    for item in found:
        key=(int(item["車番"]), str(item["理由"]))
        if key not in seen:
            seen.add(key); unique.append(item)
    meta_out=dict(meta or {})
    if unique:
        reasons = {str(int(x["車番"])): str(x["理由"]) for x in unique}
        reason_text = " / ".join(f"{k}番 {v}" for k, v in reasons.items())
        # engineの旧版・新版で参照名が異なっても、学習側へ流れないよう共通ゲートを多重指定する。
        meta_out.update({
            "発走後事故": True,
            "発走後事故車番": sorted({int(x["車番"]) for x in unique}),
            "発走後事故理由": reasons,
            "事故レース": True,
            "事故あり": True,
            "レース状態": "発走後事故",
            "予測精度評価対象": False,
            "予測精度評価対象外": True,
            "AI学習対象": False,
            "学習対象外": True,
            "学習除外": True,
            "選手履歴学習対象": False,
            "展開学習対象": False,
            "追い抜き相性学習対象": False,
            "開催場補正学習対象": False,
            "壁補正学習対象": False,
            "重み更新対象": False,
            "learning_excluded": True,
            "learning_exclusion_reason": reason_text or "発走後事故・反則",
        })
    return meta_out, unique



# Ver279: 発走後事故・反則は予測学習から除外したまま、選手別の事故履歴として別保存する。
# 将来の特徴量候補として集計できるようにするが、現時点では予測値への補正には使用しない。
def _v279_ensure_player_incident_history_table(db_path: str) -> None:
    with sqlite3.connect(db_path) as con:
        con.execute("""
            CREATE TABLE IF NOT EXISTS v279_player_incident_history (
                race_key TEXT NOT NULL,
                car_no INTEGER NOT NULL,
                player_name TEXT,
                incident_type TEXT NOT NULL,
                race_date TEXT,
                venue TEXT,
                race_no TEXT,
                registered_at TEXT NOT NULL,
                PRIMARY KEY (race_key, car_no, incident_type)
            )
        """)
        con.execute("CREATE INDEX IF NOT EXISTS idx_v279_incident_player ON v279_player_incident_history(player_name, race_date)")
        con.execute("CREATE INDEX IF NOT EXISTS idx_v279_incident_type ON v279_player_incident_history(incident_type, race_date)")
        con.commit()


def _v279_save_player_incident_history(
    db_path: str, race_key: str, meta: dict, rows, incidents: list[dict]
) -> int:
    if not race_key or not incidents:
        return 0
    _v279_ensure_player_incident_history_table(db_path)
    name_by_car = {}
    try:
        if isinstance(rows, pd.DataFrame) and not rows.empty:
            car_col = _v238_col(rows, "車番", "car_no")
            name_col = _v238_col(rows, "選手名", "player_name", "選手")
            if car_col and name_col:
                for _, r in rows.iterrows():
                    try:
                        name_by_car[int(float(r[car_col]))] = str(r[name_col] or "").strip()
                    except Exception:
                        pass
    except Exception:
        pass
    # result_entries保存後なら、解析表で名前が取れない場合もDBから補完する。
    try:
        with sqlite3.connect(db_path) as con:
            for car, name in con.execute(
                "SELECT car_no, player_name FROM result_entries WHERE race_key=?", (str(race_key),)
            ).fetchall():
                if name:
                    name_by_car.setdefault(int(car), str(name).strip())
    except Exception:
        pass
    race_date = str((meta or {}).get("開催日") or (meta or {}).get("日付") or "").strip()
    venue = str((meta or {}).get("開催場") or "").strip()
    race_no = str((meta or {}).get("R") or (meta or {}).get("レース") or (meta or {}).get("レース番号") or "").strip()
    now = _v228_now_jst_iso()
    saved = 0
    with sqlite3.connect(db_path) as con:
        for item in incidents:
            try:
                car = int(item.get("車番"))
                kind = str(item.get("理由") or "").strip()
                if not kind:
                    continue
                con.execute("""
                    INSERT INTO v279_player_incident_history
                    (race_key,car_no,player_name,incident_type,race_date,venue,race_no,registered_at)
                    VALUES (?,?,?,?,?,?,?,?)
                    ON CONFLICT(race_key,car_no,incident_type) DO UPDATE SET
                        player_name=COALESCE(NULLIF(excluded.player_name,''),v279_player_incident_history.player_name),
                        race_date=COALESCE(NULLIF(excluded.race_date,''),v279_player_incident_history.race_date),
                        venue=COALESCE(NULLIF(excluded.venue,''),v279_player_incident_history.venue),
                        race_no=COALESCE(NULLIF(excluded.race_no,''),v279_player_incident_history.race_no),
                        registered_at=excluded.registered_at
                """, (str(race_key), car, name_by_car.get(car, ""), kind, race_date, venue, race_no, now))
                saved += 1
            except Exception:
                continue
        con.commit()
    return saved


def _v279_incident_summary(db_path: str, player_name: str = "") -> dict:
    """表示・将来検証用。予測ロジックには接続しない。"""
    _v279_ensure_player_incident_history_table(db_path)
    out = {"total": 0, "by_type": {}}
    try:
        with sqlite3.connect(db_path) as con:
            if player_name:
                rows = con.execute("""
                    SELECT incident_type, COUNT(*) FROM v279_player_incident_history
                    WHERE player_name=? GROUP BY incident_type ORDER BY COUNT(*) DESC
                """, (str(player_name).strip(),)).fetchall()
            else:
                rows = con.execute("""
                    SELECT incident_type, COUNT(*) FROM v279_player_incident_history
                    GROUP BY incident_type ORDER BY COUNT(*) DESC
                """).fetchall()
        out["by_type"] = {str(k): int(n) for k,n in rows}
        out["total"] = sum(out["by_type"].values())
    except Exception:
        pass
    return out



# Ver280: 保存済みの元結果本文から、過去の反妨等を一括抽出して事故履歴へ登録する。
def _v280_backfill_incident_history(db_path: str) -> dict:
    report={"対象":0,"検出レース":0,"保存件数":0,"エラー":0}
    _v279_ensure_player_incident_history_table(db_path)
    try:
        _v238_ensure_raw_result_archive(db_path)
        with sqlite3.connect(db_path) as con:
            raws=con.execute("SELECT race_key,raw_result_text FROM v238_result_raw_archive ORDER BY race_key").fetchall()
        report["対象"]=len(raws)
        for race_key, raw in raws:
            try:
                meta, incidents=_v227_detect_poststart_incidents(str(raw or ""), {})
                if not incidents:
                    continue
                report["検出レース"]+=1
                rows=pd.DataFrame()
                try:
                    with sqlite3.connect(db_path) as con:
                        rows=pd.read_sql_query(
                            "SELECT car_no AS 車番,player_name AS 選手名 FROM result_entries WHERE race_key=?",
                            con,params=(str(race_key),)
                        )
                        rr=con.execute("SELECT race_date,venue,race_no FROM result_races WHERE race_key=?",(str(race_key),)).fetchone()
                    if rr:
                        meta.update({"開催日":rr[0],"開催場":rr[1],"R":rr[2]})
                except Exception:
                    pass
                report["保存件数"] += _v279_save_player_incident_history(db_path,str(race_key),meta,rows,incidents)
            except Exception:
                report["エラー"]+=1
    except Exception as exc:
        report["fatal"]=f"{type(exc).__name__}: {exc}"
    return report


# Ver148: Streamlit fragment互換デコレーター
# st.fragment が利用できる環境では部分再実行、未対応環境では通常関数として動作します。
_v146_fragment = getattr(st, "fragment", lambda func: func)


# Ver217: 予測後の重いDB保存を待たず、オッズ入力を先に表示する。
_v217_db_save_lock = threading.Lock()
# Ver276: 通常予測と詳細DB保存の競合を防ぐ。
