_V319_OP_PLACE = {"川口": "02", "伊勢崎": "03", "浜松": "04", "飯塚": "05", "山陽": "06"}
_V319_AR_PLACE_CODE = {"川口": 2, "伊勢崎": 3, "浜松": 4, "飯塚": 5, "山陽": 6}
_V319_AR_PLACE_SLUG = {"川口": "kawaguchi", "伊勢崎": "isesaki", "浜松": "hamamatsu", "飯塚": "iizuka", "山陽": "sanyou"}
_V319_OP_PLACE_REV = {v: k for k, v in _V319_OP_PLACE.items()}


def _v319_http_get(url: str, timeout: int = 20, retries: int = 4) -> str:
    """HTTP GET with transient retries. Does not hold a DB transaction."""
    headers = {
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
        "Accept-Language": "ja,en;q=0.8",
    }
    delays = (1.0, 3.0, 8.0)
    last_exc: BaseException | None = None
    attempts = max(1, int(retries or 1))
    for attempt in range(attempts):
        try:
            req = urllib.request.Request(url, headers=headers)
            with urllib.request.urlopen(req, timeout=int(timeout or 20)) as resp:
                status = int(getattr(resp, "status", 200) or 200)
                raw = resp.read()
            if status in (408, 425, 429, 500, 502, 503, 504):
                raise urllib.error.HTTPError(url, status, f"HTTP {status}", hdrs=None, fp=None)
            text_body = raw.decode("utf-8", errors="replace")
            if not str(text_body or "").strip():
                raise ValueError("empty HTML")
            return text_body
        except urllib.error.HTTPError as exc:
            last_exc = exc
            if int(getattr(exc, "code", 0) or 0) in (400, 401, 403, 404, 410):
                raise
        except (TimeoutError, urllib.error.URLError, ConnectionResetError, ValueError, OSError) as exc:
            last_exc = exc
        if attempt + 1 < attempts:
            time_module.sleep(delays[min(attempt, len(delays) - 1)])
    if last_exc is not None:
        raise last_exc
    raise RuntimeError(f"HTTP GET failed: {url}")


def _v319_html_to_text(html: str) -> str:
    html = re.sub(r"(?is)<(script|style)[^>]*>.*?</\1>", " ", html)
    html = re.sub(r"(?i)<br\s*/?>", "\n", html)
    html = re.sub(r"(?i)</(p|div|tr|h\d|li|table)>", "\n", html)
    html = re.sub(r"(?i)<td[^>]*>", "\t", html)
    html = re.sub(r"(?i)<[^>]+>", " ", html)
    html = html.replace("&nbsp;", " ").replace("&amp;", "&")
    html = re.sub(r"[ \t]+", " ", html)
    html = re.sub(r" *\n *", "\n", html)
    html = re.sub(r"\n{3,}", "\n\n", html)
    return html


def _v319_list_oddspark_meetings(ymd: str) -> list[dict]:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    if len(ymd) != 8:
        return []
    url = f"https://www.oddspark.com/autorace/KaisaiRaceList.do?raceDy={ymd}"
    html = _v319_http_get(url)
    found = []
    for cd in sorted(set(re.findall(r"placeCd=(\d+)", html))):
        venue = _V319_OP_PLACE_REV.get(cd)
        if venue:
            _ = found.append({"venue": venue, "place_cd": cd, "ymd": ymd})
    return found


def _v319_list_oddspark_races(ymd: str, place_cd: str) -> list[int]:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    place_cd = str(place_cd or "").zfill(2)
    nos = set()
    url = f"https://www.oddspark.com/autorace/RaceList.do?raceDy={ymd}&placeCd={place_cd}"
    try:
        html = _v319_http_get(url, timeout=12)
    except Exception:
        return []
    for dy, cd, n in re.findall(r"raceDy=(\d+)[^\"']{0,120}placeCd=(\d+)[^\"']{0,80}raceNo=(\d+)", html):
        if dy == ymd and str(cd).zfill(2) == place_cd and n.isdigit():
            nos.add(int(n))
    for cd, dy, n in re.findall(r"placeCd=(\d+)[^\"']{0,120}raceDy=(\d+)[^\"']{0,80}raceNo=(\d+)", html):
        if dy == ymd and str(cd).zfill(2) == place_cd and n.isdigit():
            nos.add(int(n))
    return [n for n in sorted(nos) if 1 <= n <= 12]


def _v319_result_page_alive(ymd: str, venue: str, race_no: int) -> bool:
    try:
        html = _v319_http_get(
            "https://www.oddspark.com/autorace/RaceResult.do"
            f"?raceDy={re.sub(r'[^0-9]','',str(ymd))}"
            f"&placeCd={_V319_OP_PLACE.get(str(venue) or '')}"
            f"&raceNo={int(race_no)}",
            timeout=12,
        )
    except Exception:
        return False
    if "該当するレースはありません" in html or "データがありません" in html:
        return False
    return ("払戻" in html or "着" in html) and ("選手" in html or "車" in html)


def _v319_ordered_race_nos(ymd: str, venue: str, max_races: int = 12) -> list[int]:
    """1Rから当日の最大Rまで連番。抜けた1Rは補う。"""
    place = _V319_OP_PLACE.get(str(venue) or "")
    found = []
    if place:
        try:
            found = _v319_list_oddspark_races(ymd, place)
        except Exception:
            found = []
    found = [int(n) for n in found if 1 <= int(n) <= int(max_races or 12)]
    if found:
        return list(range(1, max(found) + 1))
    return list(range(1, min(int(max_races or 12), 9) + 1))


def _v319_html_cells(row_html: str) -> list[str]:
    cells = []
    for cell in re.findall(r"(?is)<t[dh][^>]*>(.*?)</t[dh]>", row_html):
        cell = re.sub(r"(?is)<br\s*/?>", " ", cell)
        cell = re.sub(r"(?is)<[^>]+>", "", cell)
        cell = cell.replace("&nbsp;", " ").replace("&amp;", "&").replace("&#12288;", " ")
        cell = re.sub(r"&#(\d+);", lambda mm: chr(int(mm.group(1))), cell)
        cell = re.sub(r"\s+", " ", cell).strip()
        _ = cells.append(cell)
    return cells


def _v319_normalize_oddspark_result_text(html: str, venue: str, race_no: int, ymd: str) -> str:
    raw = _v319_html_to_text(html)
    # 日付
    date_s = ""
    m = re.search(r"(20\d{2}年\d{1,2}月\d{1,2}日(?:\([^)]+\))?)", raw)
    if m:
        date_s = m.group(1)
    else:
        date_s = f"{ymd[:4]}年{int(ymd[4:6])}月{int(ymd[6:8])}日"
    weather = ""
    wm = re.search(r"天候：\s*(\S+)", raw)
    if wm:
        weather = wm.group(1)
    surface = ""
    sm = re.search(r"走路状況：\s*(\S+)", raw)
    if sm:
        surface = sm.group(1)
    track_temp = ""
    tm = re.search(r"走路温度：\s*([\d.]+)", raw)
    if tm:
        track_temp = tm.group(1)
    air = ""
    am = re.search(r"気温：\s*([\d.]+)", raw)
    if am:
        air = am.group(1)
    hum = ""
    hm = re.search(r"湿度：\s*([\d.]+)", raw)
    if hm:
        hum = hm.group(1)

    lines = [f"{int(race_no)}R", "確定", "締切済", date_s, str(venue or "")]
    if surface:
        extra = f"{surface}"
        if track_temp:
            extra += f" /{track_temp}℃"
        _ = lines.append(extra)
    if weather:
        _ = lines.append(weather)
    if air:
        _ = lines.append(f"気温：{air}℃")
    if hum:
        _ = lines.append(f"湿度：{hum}%")
    _ = lines.append("着順	車番	選手名")
    _ = lines.append("LG/ハンデ/試走T	競走T（人気）")
    _ = lines.append("ST/事故")

    tables = re.findall(r"(?is)<table[^>]*>(.*?)</table>", html)
    finish_rows, lap_rows, pay_rows = [], [], []
    for table in tables:
        rows = re.findall(r"(?is)<tr[^>]*>(.*?)</tr>", table)
        if not rows:
            continue
        head = " ".join(_v319_html_cells(rows[0]))
        body = [_v319_html_cells(r) for r in rows]
        if "着" in head and "車" in head and "選手" in head:
            finish_rows = [_v319_html_cells(r) for r in rows[1:]]
        elif "周回" in head or "1位" in head:
            lap_rows = body
        elif any(k in head for k in ("単勝", "払戻", "2連", "ワイド", "3連")):
            pay_rows.extend(body)

    for cells in finish_rows:
        if len(cells) < 6:
            continue
        # 事故列が空だと 着,車,選手名… になる
        if re.fullmatch(r"\d+", cells[1] or "") and not re.fullmatch(r"\d+", cells[2] or ""):
            pos, acc, car = cells[0], "", cells[1]
            name = re.sub(r"\s+", "", cells[2])
            lg = cells[4] if len(cells) > 4 else venue
            hand = re.sub(r"[^0-9]", "", cells[5] if len(cells) > 5 else "") or "0"
            trial = cells[6] if len(cells) > 6 else "0.00"
            race_t = cells[7] if len(cells) > 7 else "0.000"
            st = cells[8] if len(cells) > 8 else "0.00"
            abn = ""
            pop = cells[9] if len(cells) > 9 else "-"
        else:
            pos, acc, car = cells[0], cells[1], cells[2]
            name = re.sub(r"\s+", "", cells[3] if len(cells) > 3 else "")
            lg = cells[5] if len(cells) > 5 else venue
            hand = re.sub(r"[^0-9]", "", cells[6] if len(cells) > 6 else "") or "0"
            trial = cells[7] if len(cells) > 7 else "0.00"
            race_t = cells[8] if len(cells) > 8 else "0.000"
            st = cells[9] if len(cells) > 9 else "0.00"
            abn = cells[10] if len(cells) > 10 else ""
            pop = cells[11] if len(cells) > 11 else "-"
        # 着順 "-" だけでは欠車にしない（反妨・失格なども "-" になる）
        _is_kessha = (
            acc == "欠車" or "欠車" in str(acc or "") or str(abn or "") == "欠車"
            or (pos in ("-", "欠", "－") and ("欠車" in str(acc or "") or "欠車" in str(abn or "")))
        )
        if _is_kessha:
            _ = lines.append(f"-\t{car}\t{name}")
            # engine._v35_parse_entries は プロフィール行と 競走T行を分ける前提
            _ = lines.append(f"{lg}/{hand}m/{trial}")
            _ = lines.append("0.000(-)")
            _ = lines.append("0.00 /欠車")
            continue
        flag = f" /{abn}" if abn else ""
        # 発走後事故（反妨等）は着順 "-" のまま残す（欠車にしない）
        if str(pos) in ("-", "欠", "－") and abn and "欠車" not in str(abn):
            _ = lines.append(f"-\t{car}\t{name}")
            _ = lines.append(f"{lg}/{hand}m/{trial}")
            _ = lines.append(f"{race_t}({pop})")
            st_s = str(st or "0.00")
            _ = lines.append(f"{st_s} /{abn}")
        else:
            _ = lines.append(f"{pos}\t{car}\t{name}")
            # Ver320: プロフィールと競走Tを別行に（同一行だと競走Tが欠落する）
            _ = lines.append(f"{lg}/{hand}m/{trial}")
            _ = lines.append(f"{race_t}({pop}){flag}")
            _ = lines.append(str(st or "0.00"))

    if lap_rows:
        _ = lines.append("グランドノート")
        _ = lines.append("周回・順位	1	2	3	4	5	6	7	8")
        for cells in lap_rows[1:]:
            if not cells:
                continue
            label = cells[0].replace("通過", "")
            if "ゴール" in label:
                label = "ゴール線"
            cars = "\t".join(c for c in cells[1:] if re.fullmatch(r"\d+", c or ""))
            if cars:
                _ = lines.append(f"{label}\t{cars}")

    _ = lines.append("払戻金")
    kind = ""
    for cells in pay_rows:
        vals = [c for c in cells if c]
        if not vals:
            continue
        if vals[0] in ("単勝", "複勝", "2連複", "2連単", "ワイド", "3連複", "3連単"):
            kind = vals[0]
            rest = vals[1:]
        else:
            rest = vals
        if not kind:
            continue
        yen = next((v for v in rest if "円" in v), "")
        before = []
        for v in rest:
            if "円" in v:
                break
            nums = re.findall(r"\d+", v or "")
            if nums:
                before.extend(nums)
        if kind and yen and before:
            sep = "→" if kind in ("2連単", "3連単") else "-"
            _ = lines.append(f"{kind}\t{sep.join(before)}\t{yen}")
    pay_txt = re.sub(r"\s*-\s*", "-", raw.replace("\t", " "))
    pay_txt = re.sub(r"\s+", " ", pay_txt)
    existing = "\n".join(lines)
    for pk in ["2連複", "2連単", "ワイド", "3連複", "3連単"]:
        for mm in re.finditer(rf"{pk}\s+([0-9\-]+)\s+([\d,]+)円", pay_txt):
            row = f"{pk}\t{mm.group(1)}\t{mm.group(2)}円"
            if row not in existing:
                _ = lines.append(row)
                existing += "\n" + row
    
    # 中止・不成立を正規化テキストに残す（オッズ空時の判定用）
    if re.search(r"レース中止|競走中止", raw) or re.search(r"(?:^|\n)\s*中止\s*(?:\n|$)", raw):
        if "レース中止" not in existing:
            _ = lines.append("レース中止")
            existing += "\nレース中止"
    if "不成立" in raw and "不成立" not in existing:
        _ = lines.append("不成立")
        for bt in ("単勝", "複勝", "2連複", "2連単", "ワイド", "3連複", "3連単"):
            row = f"{bt}\t-\t100円\t不成立"
            if row not in existing:
                _ = lines.append(row)
                existing += "\n" + row
    if "全返還" in raw and "全返還" not in existing:
        _ = lines.append("全返還")
    return "\n".join(lines)


def _v319_fetch_oddspark_result(ymd: str, venue: str, race_no: int) -> str:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    place = _V319_OP_PLACE.get(str(venue))
    if not ymd or not place:
        raise ValueError("開催日または開催場が不正です")
    url = (
        "https://www.oddspark.com/autorace/RaceResult.do"
        f"?raceDy={ymd}&placeCd={place}&raceNo={int(race_no)}"
    )
    html = _v319_http_get(url)
    if "着" not in html and "払戻" not in html:
        raise ValueError("結果ページを取得できませんでした")
    return _v319_normalize_oddspark_result_text(html, venue, int(race_no), ymd)


def _v319_float_odd(val) -> float | None:
    if isinstance(val, dict):
        nums = []
        for k in ("min", "max", "odds"):
            if val.get(k) not in (None, "", "-"):
                try:
                    _ = nums.append(float(str(val.get(k)).replace(",", "")))
                except Exception:
                    pass
        return min(nums) if nums else None
    try:
        s = str(val or "").replace(",", "").strip()
        if not s or s in {"-", "–"}:
            return None
        n = float(s)
        return n if n > 0 else None
    except Exception:
        return None


def _v319_official_odds_to_parsed(body: dict) -> dict:
    parsed = {"3tan": {}, "3fuku": {}, "2tansho": {}, "2fuku": {}, "tansho": {}, "fukusho": {}, "wide": {}}
    tns = body.get("tnsOddsList") or {}
    for a, o in tns.items():
        n = _v319_float_odd(o)
        if n:
            parsed["tansho"][str(a)] = n
    fns = body.get("fnsOddsList") or {}
    for a, o in fns.items():
        n = _v319_float_odd(o)
        if n:
            parsed["fukusho"][str(a)] = n
    rtw = body.get("rtwOddsList") or {}
    for a, inner in rtw.items():
        if not isinstance(inner, dict):
            continue
        for b, o in inner.items():
            n = _v319_float_odd(o)
            if n:
                parsed["2tansho"][f"{a}-{b}"] = n
    rfw = body.get("rfwOddsList") or {}
    for a, inner in rfw.items():
        if not isinstance(inner, dict):
            continue
        for b, o in inner.items():
            n = _v319_float_odd(o)
            if n:
                combo = "-".join(sorted((str(a), str(b)), key=int))
                parsed["2fuku"][combo] = n
    wid = body.get("widOddsList") or {}
    for a, inner in wid.items():
        if not isinstance(inner, dict):
            continue
        for b, o in inner.items():
            n = _v319_float_odd(o)
            if n:
                combo = "-".join(sorted((str(a), str(b)), key=int))
                parsed["wide"][combo] = n
    rt3 = body.get("rt3OddsList") or {}
    for a, mid in rt3.items():
        if not isinstance(mid, dict):
            continue
        for b, inner in mid.items():
            if not isinstance(inner, dict):
                continue
            for c, o in inner.items():
                n = _v319_float_odd(o)
                if n:
                    parsed["3tan"][f"{a}-{b}-{c}"] = n
    rf3 = body.get("rf3OddsList") or {}
    for a, mid in rf3.items():
        if not isinstance(mid, dict):
            continue
        for b, inner in mid.items():
            if not isinstance(inner, dict):
                continue
            for c, o in inner.items():
                n = _v319_float_odd(o)
                if n:
                    combo = "-".join(sorted((str(a), str(b), str(c)), key=int))
                    parsed["3fuku"][combo] = n
    return parsed


def _v319_fetch_official_odds(ymd: str, venue: str, race_no: int) -> dict:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    code = _V319_AR_PLACE_CODE.get(str(venue) or "")
    slug = _V319_AR_PLACE_SLUG.get(str(venue) or "")
    if len(ymd) != 8 or not code or not slug:
        raise ValueError("開催日または開催場が不正です")
    date_s = f"{ymd[:4]}-{ymd[4:6]}-{ymd[6:8]}"
    page_url = f"https://autorace.jp/race_info/Odds/{slug}/{date_s}_{int(race_no)}/pop"
    jar = http.cookiejar.CookieJar()
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))
    page = opener.open(
        urllib.request.Request(page_url, headers={"User-Agent": "Mozilla/5.0"}),
        timeout=20,
    ).read().decode("utf-8", "replace")
    token_m = re.search(r'csrf-token" content="([^"]+)"', page)
    token = token_m.group(1) if token_m else ""
    payload = json.dumps({"placeCode": int(code), "raceDate": date_s, "raceNo": int(race_no)}).encode("utf-8")
    req = urllib.request.Request(
        "https://autorace.jp/race_info/Odds",
        data=payload,
        headers={
            "User-Agent": "Mozilla/5.0",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "X-CSRF-TOKEN": token,
            "X-Requested-With": "XMLHttpRequest",
            "Referer": page_url,
            "Origin": "https://autorace.jp",
        },
        method="POST",
    )
    raw = opener.open(req, timeout=25).read().decode("utf-8", "replace")
    data = json.loads(raw)
    if str(data.get("result") or "") != "Success":
        raise ValueError(str((data.get("errors") or ["オッズ取得失敗"])[0]))
    parsed = _v319_official_odds_to_parsed(data.get("body") or {})
    if sum(len(v) for v in parsed.values()) <= 0:
        raise ValueError("オッズが空です")
    return parsed


def _v319_save_official_odds(db_path: str, race_key: str, parsed: dict) -> int:
    sid = _v221_save_all_odds(db_path, race_key, parsed, source="autorace_official")
    return int(sum(len(v) for v in (parsed or {}).values())) if sid else 0


def _v319_load_latest_prediction_view(db_path: str, race_key: str) -> dict:
    try:
        with sqlite3.connect(str(db_path), timeout=15) as con:
            row = con.execute(
                "SELECT history_id FROM v231_prediction_history WHERE race_key=? ORDER BY history_id DESC LIMIT 1",
                (str(race_key),),
            ).fetchone()
        if not row:
            return {}
        view, *_rest = _v231_load_prediction_history(db_path, int(row[0]))
        return view if isinstance(view, dict) else {}
    except Exception:
        return {}


def _v319_apply_odds_and_plan(
    db_path: str, ymd: str, venue: str, race_no: int, race_key: str,
    view: dict | None = None, *, use_saved_odds: bool = False, refetch_odds: bool = True,
) -> dict:
    """公式オッズを保存し、回収率重視プランを作って結果照合する。

    Ver319 fix: プラン生成（v184/v277）の例外はオッズ保存を失敗扱いにしない。
    Ver325: use_saved_odds=True ならHTTPせず保存済みオッズだけでプラン再生成
            （6周再シミュレーション不要）。
    """
    parsed = {}
    n_odds = 0
    if use_saved_odds or not refetch_odds:
        try:
            parsed, _meta_od = _v221_load_odds_snapshot(db_path, str(race_key))
            if not isinstance(parsed, dict):
                parsed = {}
            n_odds = int(sum(len(v) for v in parsed.values())) if parsed else 0
        except Exception:
            parsed, n_odds = {}, 0
        if n_odds <= 0 and refetch_odds and not use_saved_odds:
            parsed = _v319_fetch_official_odds(ymd, venue, race_no)
            n_odds = _v319_save_official_odds(db_path, race_key, parsed)
        elif n_odds <= 0 and use_saved_odds:
            return {"odds": 0, "plan_hash": "", "plan_error": "保存オッズなし"}
    else:
        parsed = _v319_fetch_official_odds(ymd, venue, race_no)
        n_odds = _v319_save_official_odds(db_path, race_key, parsed)
    view = view if isinstance(view, dict) and view else _v319_load_latest_prediction_view(db_path, race_key)
    bets = (view or {}).get("bets")
    meta = (view or {}).get("meta") or {}
    trials = int((view or {}).get("trials") or 20000)
    plan_hash = ""
    plan_error = ""
    if isinstance(bets, dict) and bets and n_odds:
        try:
            # 実験経路(odds_replan): G1有効 + Ver325として保存。本線は Ver324・G1オフ。
            _exp325 = bool(use_saved_odds)
            _prev_g1 = bool(globals().get("_V325_ENABLE_G1"))
            if _exp325:
                globals()["_V325_ENABLE_G1"] = True
            try:
                result = v184_eight_car_mixed_plan(bets, trials, meta, parsed)
                result = v277_provisional_merge_7types(result, bets, trials, parsed)
            finally:
                globals()["_V325_ENABLE_G1"] = _prev_g1
            if isinstance(result, dict) and result.get("available"):
                _save_ver = str(globals().get("_V325_APP_VERSION") or "Ver325") if _exp325 else str(APP_VERSION)
                _origin325 = "odds_replan" if use_saved_odds else "official_import"
                plan_hash = str(_v187_save_mixed_plan(
                    db_path, str(race_key), result, app_version=_save_ver,
                    plan_origin=_origin325,
                    source_prediction_version=str((view or {}).get("app_version") or APP_VERSION),
                    include_in_live_stats=True,
                ) or "")
                if plan_hash:
                    try:
                        _v321_save_plan_diagnostics(
                            db_path, str(race_key), plan_hash, result, str(_save_ver),
                        )
                    except Exception:
                        pass
                    _v305_supersede_plan_after_odds_refresh(db_path, str(race_key), _save_ver, plan_hash)
                    try:
                        _v212_recalculate_plan_feedback(db_path, str(race_key), plan_hash)
                    except Exception:
                        pass
        except Exception as plan_exc:
            # オッズ本体は保存済み。プランだけスキップして結果登録へ進める。
            plan_error = f"{type(plan_exc).__name__}: {plan_exc}"
    try:
        _v187_sync_mixed_feedback(db_path)
    except Exception:
        pass
    out = {"odds": n_odds, "plan_hash": plan_hash}
    if plan_error:
        out["plan_error"] = plan_error
    return out


def _v319_norm_player_name(name: str) -> str:
    return re.sub(r"[\s　]+", "", str(name or ""))


def _v319_fetch_sprace_html(ymd: str, venue: str, race_no: int) -> str:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    place = _V319_OP_PLACE.get(str(venue) or "")
    if not ymd or not place:
        raise ValueError("開催日または開催場が不正です")
    url = (
        "https://sp.oddspark.com/autorace/SpRaceInfo.do"
        f"?kaisaiBi={ymd}&joCode={place}&joCd={place}&raceNo={int(race_no)}"
    )
    return _v319_http_get(url)


_V319_WX_CACHE: dict[str, dict] = {}
_V319_WX_FETCHES = 0
_V319_WX_FETCH_LIMIT = 15
_V319_HIST_REFRESHED: set[str] = set()
# Ver320: cache_key -> before_d(8桁)。同一開催日取込中は SELECT すら打たない
_V319_HIST_SKIPPED: dict[str, str] = {}


def _v319_hist_skip_cache_ensure(con) -> None:
    con.execute(
        """
        CREATE TABLE IF NOT EXISTS v319_hist_skip_cache (
            player_cd TEXT NOT NULL,
            target_ymd TEXT NOT NULL,
            fetched_at TEXT NOT NULL,
            official_latest TEXT,
            PRIMARY KEY (player_cd, target_ymd)
        )
        """
    )


def _v319_persistent_skip_lookup(db_path: str, player_cd: str, target_ymd: str, con=None) -> dict | None:
    """(player_cd, target_ymd) が既に確認済みならスキップ。

    Ver324: 同日一括取込の2レース目以降・再起動後も HTTP を打たない。
    TTLなし。同じ対象日を再度公式確認する意味がないため。
    """
    pcd = str(player_cd or "").strip()
    ymd = _v319_ymd_digits(target_ymd or "")
    if not pcd or not ymd:
        return None
    own = con is None
    try:
        if own:
            con = sqlite3.connect(str(db_path), timeout=5.0)
        _v319_hist_skip_cache_ensure(con)
        row = con.execute(
            "SELECT fetched_at, official_latest FROM v319_hist_skip_cache "
            "WHERE player_cd=? AND target_ymd=?",
            (pcd, ymd),
        ).fetchone()
        if not row:
            return None
        return {
            "skip": True,
            "reason": f"永続キャッシュ(対象日{ymd})",
            "fetched_at": row[0],
            "official_latest": row[1],
        }
    except Exception:
        return None
    finally:
        if own and con is not None:
            try:
                con.close()
            except Exception:
                pass


def _v319_persistent_skip_mark(
    db_path: str,
    player_cd: str,
    target_ymd: str,
    official_latest: str = "",
    con=None,
) -> None:
    """対象日までの履歴確認済みを永続化。"""
    pcd = str(player_cd or "").strip()
    ymd = _v319_ymd_digits(target_ymd or "")
    if not pcd or not ymd:
        return
    own = con is None
    try:
        if own:
            con = sqlite3.connect(str(db_path), timeout=5.0)
        _v319_hist_skip_cache_ensure(con)
        con.execute(
            """
            INSERT INTO v319_hist_skip_cache(player_cd, target_ymd, fetched_at, official_latest)
            VALUES (?,?,?,?)
            ON CONFLICT(player_cd, target_ymd) DO UPDATE SET
                fetched_at=excluded.fetched_at,
                official_latest=COALESCE(
                    NULLIF(excluded.official_latest,''),
                    v319_hist_skip_cache.official_latest
                )
            """,
            (
                pcd,
                ymd,
                _v228_now_jst_iso(),
                _v319_ymd_digits(official_latest or "") or "",
            ),
        )
        if own:
            con.commit()
    except Exception:
        pass
    finally:
        if own and con is not None:
            try:
                con.close()
            except Exception:
                pass
# 同一 player_cd の公式履歴DFを取込ジョブ内で再利用
_V319_HIST_DF_CACHE: dict[str, object] = {}


def _v319_wx_reset_budget() -> None:
    global _V319_WX_FETCHES, _V319_HIST_REFRESHED, _V319_HIST_SKIPPED, _V319_HIST_DF_CACHE
    _V319_WX_FETCHES = 0
    _V319_HIST_REFRESHED = set()
    _V319_HIST_SKIPPED = {}
    _V319_HIST_DF_CACHE = {}


def _v319_race_weather(ymd: str, venue: str, race_no: int) -> dict:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    try:
        rno = int(race_no)
    except Exception:
        rno = 0
    key = f"{ymd}_{venue}_{rno}"
    if key in _V319_WX_CACHE:
        return _V319_WX_CACHE[key]
    out = {"走": "", "気": "", "湿": ""}
    global _V319_WX_FETCHES
    if ymd and venue and rno and _V319_WX_FETCHES < _V319_WX_FETCH_LIMIT:
        _V319_WX_FETCHES += 1
        try:
            raw = _v319_html_to_text(_v319_fetch_sprace_html(ymd, venue, rno))
            m = re.search(r"(?:良走路|湿走路|斑走路)\s*/\s*(\d+(?:\.\d+)?)\s*℃", raw)
            if m:
                out["走"] = m.group(1)
            m = re.search(r"気温：\s*(\d+(?:\.\d+)?)", raw)
            if m:
                out["気"] = m.group(1)
            m = re.search(r"湿度：\s*(\d+(?:\.\d+)?)", raw)
            if m:
                out["湿"] = m.group(1)
        except Exception:
            pass
    _V319_WX_CACHE[key] = out
    return out


def _v319_parse_sprace_players(html: str) -> list[dict]:
    out = []
    seen = set()
    for m in re.finditer(
        r'param="(\d+)"\s+href="/autorace/SpPlayerDetail\.do\?playerCd=(\d+)[^"]*">\s*<strong>([^<]+)</strong>',
        html,
    ):
        car, pcd, name = int(m.group(1)), m.group(2), m.group(3).strip()
        key = (car, pcd)
        if key in seen:
            continue
        seen.add(key)
        if "　" not in name and len(name) <= 3:
            continue
        _ = out.append({"car": car, "player_cd": pcd, "name": name, "name_key": _v319_norm_player_name(name)})
    return out


def _v319_td_text(td_html: str) -> str:
    t = re.sub(r"(?i)<br\s*/?>", "\n", td_html or "")
    t = re.sub(r"(?is)<[^>]+>", " ", t)
    t = t.replace("&nbsp;", " ").replace("&amp;", "&")
    t = re.sub(r"&#(\d+);", lambda mm: chr(int(mm.group(1))), t)
    t = re.sub(r"[ \t]+", " ", t)
    lines = [ln.strip() for ln in t.splitlines() if ln.strip()]
    return "\n".join(lines)


def _v319_parse_sprace_car_rows(html: str) -> list[dict]:
    rows = []
    seen = set()
    for m in re.finditer(
        r'<td class="stcNameFull[^"]*"[\s\S]*?param="(\d+)"[\s\S]*?playerCd=(\d+)[^>]*>\s*<strong>([^<]+)</strong>\s*\(([^)]+)\)([\s\S]*?)</td>',
        html,
    ):
        car = int(m.group(1))
        if car in seen:
            continue
        seen.add(car)
        name = re.sub(r"^[◎○▲△×注\s]+", "", m.group(3).strip())
        lg = m.group(4).strip()
        name_td = _v319_td_text(m.group(0))
        age = ""
        am = re.search(r"(\d+歳/\d+期)", name_td)
        if am:
            age = am.group(1)
        hand, st = "0", ""
        hm = re.search(r"(\d+)m/ST([\d.]+)", name_td)
        if hm:
            hand, st = hm.group(1), hm.group(2)
        # 同じTR内の後続セル
        tr_end = html.find("</tr>", m.end())
        rest = html[m.end(): tr_end if tr_end > m.end() else m.end() + 4000]
        tds = [_v319_td_text(td) for td in re.findall(r"(?is)<td[^>]*>([\s\S]*?)</td>", rest)]
        trial = dev = rank = avg_r = best_r = finish10 = rate2 = rate3 = car_name = ""
        # 短縮名, 試走T/偏差, ランク, V, 良10走, 近10走, 車名
        if len(tds) >= 2:
            tm = re.search(r"(3\.\d{2})", tds[1])
            dm = re.search(r"(0\.\d{2,3})", tds[1])
            if tm:
                trial = tm.group(1)
            if dm:
                dev = dm.group(1)
        if len(tds) >= 3:
            rm = re.search(r"([ABS]-[0-9]+)", tds[2])
            if rm:
                rank = rm.group(1)
        if len(tds) >= 5:
            am2 = re.search(r"平均競走T\s*([\d.]+)", tds[4])
            bm = re.search(r"最高競走T\s*([\d.]+)", tds[4])
            if am2:
                avg_r = am2.group(1)
            if bm:
                best_r = bm.group(1)
        if len(tds) >= 6:
            fm = re.search(r"着順\s*([0-9\-]+)", tds[5])
            r2 = re.search(r"2連\s*([\d.]+)%", tds[5])
            r3 = re.search(r"3連\s*([\d.]+)%", tds[5])
            if fm:
                finish10 = fm.group(1)
            if r2:
                rate2 = r2.group(1)
            if r3:
                rate3 = r3.group(1)
        if len(tds) >= 7:
            first = tds[6].split("\n")[0].strip()
            if first and not re.fullmatch(r"[\d.]+", first):
                car_name = first
        if not trial:
            tm = re.search(r"試\s*([\d.]+)", name_td + "\n" + "\n".join(tds[:3]))
            if tm:
                trial = tm.group(1)
        # 欠車: SP HTML は span.alert
        blob_k = (name_td or "") + "\n" + (m.group(0) or "")
        is_kessha = bool(
            re.search(r"欠車|出走取消|発走除外|競走除外", blob_k)
            or ("欠車" in (m.group(0) or "") and "alert" in (m.group(0) or "").lower())
        )
        rows.append({
            "car": car, "player_cd": m.group(2), "name": name, "lg": lg, "age": age,
            "hand": hand, "st": st, "trial": trial, "dev": dev, "rank": rank,
            "avg_r": avg_r, "best_r": best_r, "finish10": finish10,
            "rate2": rate2, "rate3": rate3, "car_name": car_name,
            "name_key": _v319_norm_player_name(name),
            "kessha": bool(is_kessha),
        })
    return rows


def _v319_build_prediction_text_from_sprace(html: str, venue: str, race_no: int, ymd: str) -> str:
    raw = _v319_html_to_text(html)
    dm = re.search(r"(20\d{2}年\d{1,2}月\d{1,2}日(?:\([^)]+\))?)", raw)
    date_s = dm.group(1) if dm else f"{ymd[:4]}年{int(ymd[4:6])}月{int(ymd[6:8])}日"
    title_m = re.search(r"(令和[^\n]{4,40})", raw)
    kind_m = re.search(r"(予選|一般戦|選抜|優勝戦|準決|初日|最終日)[^\n]{0,20}3100m", raw)
    sm = re.search(r"(良走路|湿走路|斑走路)", raw)
    tm = re.search(r"/(\d+(?:\.\d+)?)℃", raw)
    am = re.search(r"気温：\s*([\d.]+)", raw)
    hm = re.search(r"湿度：\s*([\d.]+)", raw)
    cars = _v319_parse_sprace_car_rows(html) or _v319_parse_sprace_players(html)
    starters = [c for c in (cars or []) if not c.get("kessha")]
    ncar = max(len(starters) if starters else len(cars or []), 1)
    lines = [
        f"{int(race_no)}R",
        "確定",
        "締切済",
        date_s,
        title_m.group(1).strip() if title_m else "",
        kind_m.group(0).strip() if kind_m else "予選 3100m(6周)",
        f"3100m {ncar}車 6周",
        f"{sm.group(1) if sm else '良走路'}" + (f" /{tm.group(1)}℃" if tm else ""),
    ]
    if am:
        _ = lines.append(f"気温：{am.group(1)}℃")
    if hm:
        _ = lines.append(f"湿度：{hm.group(1)}%")
    _ = lines.append("出走表")
    for p in cars:
        lg = p.get("lg") or venue
        name = p.get("name") or ""
        _ = lines.append(f"{p.get('car')}\t{name}({lg})")
        if p.get("kessha"):
            _ = lines.append("欠車")
        if p.get("age"):
            _ = lines.append(p["age"])
        hand = p.get("hand") or "0"
        st = p.get("st") or ""
        trial = p.get("trial") or ""
        _ = lines.append(f"ハンデ{hand}m/ST{st or '-'}\t{trial}".rstrip())
        if p.get("dev") or p.get("rank"):
            _ = lines.append(f"{p.get('dev') or ''}\t{p.get('rank') or ''}".strip())
        if p.get("avg_r") or p.get("best_r"):
            bit = []
            if p.get("avg_r"):
                _ = bit.append(f"平均競走T {p['avg_r']}")
            if p.get("best_r"):
                _ = bit.append(f"最高競走T {p['best_r']}")
            _ = lines.append(" ".join(bit))
        if p.get("finish10"):
            _ = lines.append(f"着順 {p['finish10']}")
        if p.get("rate2"):
            _ = lines.append(f"2連 {p['rate2']}%")
        if p.get("rate3"):
            _ = lines.append(f"3連 {p['rate3']}%")
        if p.get("car_name"):
            _ = lines.append(p["car_name"])
    return "\n".join([ln for ln in lines if ln is not None])


def _v319_ymd_digits(value) -> str:
    return re.sub(r"[^0-9]", "", str(value or ""))[:8]


_V319_SCHEMA_CACHE: dict = {}

_V319_INDEX_DDL = [
    ("result_races", "idx_result_races_race_key", ["race_key"]),
    ("result_races", "idx_result_races_date_venue", ["race_date", "venue"]),
    ("result_races", "idx_result_races_learning", ["learning_eligible"]),
    ("result_races", "idx_result_races_model", ["model_eligible"]),
    ("result_entries", "idx_result_entries_race_key", ["race_key"]),
    ("result_entries", "idx_result_entries_player", ["player_name"]),
    ("result_entries", "idx_result_entries_race_player", ["race_key", "player_name"]),
    ("result_payouts", "idx_result_payouts_race_key", ["race_key"]),
    ("v15_player_history_imports", "idx_v15_phi_player_name", ["player_name"]),
    ("v15_player_history_imports", "idx_v15_phi_date", ["race_date"]),
]


def _v319_conn_stat_key(db_path: str) -> tuple:
    """DBファイルの (path, mtime, size)。内容が変わればキャッシュ鍵も変わる。"""
    try:
        stt = os.stat(str(db_path))
        return (str(db_path), int(stt.st_mtime_ns), int(stt.st_size))
    except Exception:
        return (str(db_path), 0, 0)


def _v319_invalidate_schema_cache(db_path: str | None = None) -> None:
    """スキーマキャッシュを明示破棄する（テーブル作成直後などに呼ぶ）。"""
    if db_path is None:
        _V319_SCHEMA_CACHE.clear()
    else:
        for k in [k for k in list(_V319_SCHEMA_CACHE.keys()) if k and k[0] == str(db_path)]:
            _V319_SCHEMA_CACHE.pop(k, None)


def _v319_schema_tables(con) -> set:
    """テーブル名集合。接続ごとに1回だけ問い合わせて使い回す。"""
    cache = getattr(con, "_v319_tables_cache", None)
    if cache is not None:
        return cache
    try:
        cache = {str(r[0]) for r in con.execute(
            "SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
    except Exception:
        cache = set()
    try:
        con._v319_tables_cache = cache
    except Exception:
        pass
    return cache


def _v319_table_columns_cached(con, table: str) -> list:
    """列名リスト。(DBファイル, mtime, size) と接続内の二段キャッシュ。"""
    try:
        path = str(con.execute("PRAGMA database_list").fetchone()[2] or "")
    except Exception:
        path = ""
    memo = _V319_SCHEMA_CACHE.setdefault(_v319_conn_stat_key(path), {})
    if table in memo:
        return memo[table]
    percon = getattr(con, "_v319_cols_cache", None)
    if percon is None:
        percon = {}
        try:
            con._v319_cols_cache = percon
        except Exception:
            pass
    if table in percon:
        memo[table] = percon[table]
        return percon[table]
    try:
        cols = [str(r[1]) for r in con.execute(
            'PRAGMA table_info("%s")' % str(table)).fetchall()]
    except Exception:
        cols = []
    memo[table] = cols
    percon[table] = cols
    return cols


def _v319_has_column(con, table: str, column: str) -> bool:
    return str(column) in set(_v319_table_columns_cached(con, table))


def _v319_create_index_if_possible(con, table: str, idx_name: str, columns) -> tuple:
    """列が無い等で作れない場合は静かにスキップする。戻り値 (作成したか, 理由)。"""
    try:
        tcols = {str(r[1]) for r in con.execute(
            'PRAGMA table_info("%s")' % str(table)).fetchall()}
    except Exception:
        return False, "no-table"
    if not tcols:
        return False, "no-table"
    miss = [str(c) for c in columns if str(c) not in tcols]
    if miss:
        return False, "no-column:" + ",".join(miss)
    collist = ",".join('"%s"' % str(c) for c in columns)
    try:
        con.execute('CREATE INDEX IF NOT EXISTS "%s" ON "%s"(%s)' % (idx_name, table, collist))
        return True, "ok"
    except Exception as exc:
        return False, "%s: %s" % (type(exc).__name__, exc)


def _v319_ensure_player_name_key_columns(db_path: str) -> dict:
    """Ver319改善#5: 関数被せWHEREを等値比較へ置き換えるための正規化列。

    重要: result_entries は engine.py が「INSERT INTO result_entries VALUES(9個)」
    の位置指定で書くため、列を追加してはいけない。
    対象は v15_player_history_imports のみ。
    誤って result_entries に追加された player_name_key は起動時に除去する。
    """
    out = {"ok": False, "backfilled": 0, "tables": [], "reason": "", "repairs": []}
    targets = [
        ("v15_player_history_imports", "player_name"),
    ]
    try:
        with sqlite3.connect(str(db_path), timeout=60.0) as con:
            con.execute("PRAGMA busy_timeout=60000")

            # --- Ver319改善#5 リカバリ ---
            # 過去版で誤って result_entries に追加された player_name_key を除去する。
            tabs = {r[0] for r in con.execute(
                "SELECT name FROM sqlite_master WHERE type='table'"
            ).fetchall()}
            if "result_entries" in tabs:
                re_cols = {r[1] for r in con.execute(
                    'PRAGMA table_info("result_entries")'
                ).fetchall()}
                if "player_name_key" in re_cols:
                    try:
                        con.execute('DROP INDEX IF EXISTS idx_result_entries_name_key')
                    except Exception:
                        pass
                    try:
                        con.execute(
                            'ALTER TABLE "result_entries" DROP COLUMN player_name_key'
                        )
                        out["repairs"].append(
                            "result_entries.player_name_key を削除（位置指定INSERT復旧）"
                        )
                    except Exception as _drop_exc:
                        out["reason"] = (
                            "result_entries.player_name_key を削除できません。"
                            f" SQLite 3.35.0 以降が必要です: "
                            f"{type(_drop_exc).__name__}: {_drop_exc}"
                        )
                        return out

            # --- 本体 ---
            for table, src_col in targets:
                tabs = {r[0] for r in con.execute(
                    "SELECT name FROM sqlite_master WHERE type='table'"
                ).fetchall()}
                if table not in tabs:
                    continue
                cols = {r[1] for r in con.execute(
                    f'PRAGMA table_info("{table}")'
                ).fetchall()}
                if src_col not in cols:
                    continue
                if "player_name_key" not in cols:
                    con.execute(
                        f'ALTER TABLE "{table}" ADD COLUMN player_name_key TEXT'
                    )
                cur = con.execute(
                    f'UPDATE "{table}" '
                    f'SET player_name_key = '
                    f"replace(replace(COALESCE(\"{src_col}\",''),' ',''),'\u3000','') "
                    f'WHERE COALESCE(player_name_key,"") = ""'
                )
                out["backfilled"] += int(cur.rowcount or 0)
                con.execute(
                    f'CREATE INDEX IF NOT EXISTS idx_{table}_name_key '
                    f'ON "{table}"(player_name_key) '
                    f'WHERE player_name_key IS NOT NULL'
                )
                out["tables"].append(table)
            con.commit()
        out["ok"] = True
    except Exception as exc:
        out["reason"] = f"{type(exc).__name__}: {exc}"
    return out



def _v319_ensure_perf_indexes(db_path: str) -> dict:
    """Ver319改善#1: 学習・集計のJOINを速くする索引を冪等に整備する。

    取込開始時に呼ぶ。テーブル/列が無い索引は静かにスキップする。
    """
    out = {"ok": False, "created": [], "skipped": [], "reason": ""}
    try:
        with sqlite3.connect(str(db_path), timeout=60.0) as con:
            con.execute("PRAGMA busy_timeout=60000")
            for tname, iname, cols in _V319_INDEX_DDL:
                okc, why = _v319_create_index_if_possible(con, tname, iname, cols)
                if okc:
                    out["created"].append(iname)
                else:
                    out["skipped"].append(iname + "(" + why + ")")
            con.commit()
        out["ok"] = True
        _v319_invalidate_schema_cache(db_path)
    except Exception as exc:
        out["reason"] = "%s: %s" % (type(exc).__name__, exc)
    return out

# Ver319改善#5: player_name_key 列を冪等に整備（結果は変えない）
if not st.session_state.get("_v319_startup_name_key_done"):
    try:
        _V319_STARTUP_NAME_KEYS = _v319_ensure_player_name_key_columns(engine.DB_PATH)
    except Exception as _v319_nk_exc:
        _V319_STARTUP_NAME_KEYS = {"ok": False, "reason": f"{type(_v319_nk_exc).__name__}: {_v319_nk_exc}"}
    st.session_state["_v319_startup_name_key_done"] = True


# Ver319改善#1: 起動時に冪等に索引整備（予測結果は変えない）
if not st.session_state.get("_v319_startup_index_done"):
    try:
        _V319_STARTUP_INDEXES = _v319_ensure_perf_indexes(engine.DB_PATH)
    except Exception as _v319_idx_exc:
        _V319_STARTUP_INDEXES = {"ok": False, "reason": f"{type(_v319_idx_exc).__name__}: {_v319_idx_exc}"}
    st.session_state["_v319_startup_index_done"] = True


def _v319_open_conn(db_path: str):
    """Ver319改善#2: 取込1レース分を使い回す接続。"""
    cn = sqlite3.connect(str(db_path), timeout=60.0)
    cn.execute("PRAGMA busy_timeout=60000")
    try:
        cn.execute("PRAGMA journal_mode=WAL")
    except Exception:
        pass
    return cn


def _v319_name_where(con, table: str, alias: str = "") -> str:
    """選手名の照合式。

    player_name_key 列がある場合も、NULL/空キーは player_name 正規化で照合する。
    （engine 保存直後は key が埋まっていないことがある）
    """
    pre = (str(alias) + ".") if alias else ""
    expr_name = "replace(replace(COALESCE(%splayer_name,''),' ',''),'　','')" % pre
    try:
        if "player_name_key" in set(_v319_table_columns_cached(con, table)):
            # COALESCE(key, 正規化名)=? で NULL key 行も拾う
            return (
                "COALESCE(NULLIF(%splayer_name_key,''), %s)=?"
                % (pre, expr_name)
            )
    except Exception:
        pass
    return "%s=?" % expr_name


def _v319_player_history_state(db_path: str, player_name: str, con=None) -> dict:
    key = _v319_norm_player_name(player_name)
    out = {"count": 0, "latest": "", "keys": set()}
    if not key:
        return out
    _own = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        try:
            if "v15_player_history_imports" not in _v319_schema_tables(con):
                return out
            names = _v319_table_columns_cached(con, "v15_player_history_imports")
            colset = set(names)
            date_c = "race_date" if "race_date" in colset else ("開催日" if "開催日" in colset else None)
            ven_c = "venue" if "venue" in colset else ("開催場" if "開催場" in colset else None)
            rno_c = "race_no" if "race_no" in colset else ("レース" if "レース" in colset else None)
            where_sql = _v319_name_where(con, "v15_player_history_imports")
            if date_c and ven_c and rno_c:
                # 必要な3列だけ読む（全列SELECTをやめる）
                rows = con.execute(
                    'SELECT "%s","%s","%s" FROM v15_player_history_imports WHERE %s' % (
                        date_c, ven_c, rno_c, where_sql),
                    (key,),
                ).fetchall()
                out["count"] = len(rows)
                for ds_raw, vn_raw, rn_raw in rows:
                    ds = _v319_ymd_digits(ds_raw)
                    if ds and ds > out["latest"]:
                        out["latest"] = ds
                    vn = str(vn_raw or "").replace("\u3000", "").strip()
                    try:
                        rn = int(rn_raw or 0)
                    except Exception:
                        rn = 0
                    if ds:
                        out["keys"].add((ds, vn, rn))
            else:
                rows = con.execute(
                    "SELECT * FROM v15_player_history_imports WHERE " + where_sql,
                    (key,),
                ).fetchall()
                out["count"] = len(rows)
                for row in rows:
                    rec = dict(zip(names, row))
                    ds = _v319_ymd_digits(rec.get(date_c) if date_c else rec.get("race_date"))
                    if ds and ds > out["latest"]:
                        out["latest"] = ds
                    vn = str(rec.get(ven_c) or rec.get("venue") or "").replace("\u3000", "").strip()
                    try:
                        rn = int(rec.get(rno_c) or rec.get("race_no") or 0)
                    except Exception:
                        rn = 0
                    if ds:
                        out["keys"].add((ds, vn, rn))
        except Exception:
            # 呼び出し側は dict 前提。失敗時は空状態（握りつぶしではなく既定値）
            return {"count": 0, "latest": "", "keys": set()}
    finally:
        if _own:
            try:
                con.close()
            except Exception:
                pass
    return out


def _v319_probe_official_latest_ymd(player_cd: str, max_ymd: str = "") -> str:
    """公式の最新履歴日を軽く取る（全件パースしない）。

    max_ymd がある場合は、それより後（未来／対象レースより先）の日付は判定に使わない。
    戻り値: yyyymmdd（対象日以前の公式最新）
    """
    pcd = str(player_cd or "").strip()
    if not pcd:
        return ""
    cap = _v319_ymd_digits(max_ymd) if max_ymd else ""
    urls = (
        f"https://www.oddspark.com/autorace/PlayerDetail.do?playerCd={pcd}&historyDispType=d",
        f"https://sp.oddspark.com/autorace/SpPlayerDetail.do?playerCd={pcd}&historyDispType=d",
    )

    def _norm_ymd(y, mo, d) -> str:
        try:
            yi, mi, di = int(y), int(mo), int(d)
        except Exception:
            return ""
        if yi < 100:
            yi = 2000 + yi if yi < 80 else 1900 + yi
        if not (2000 <= yi <= 2100 and 1 <= mi <= 12 and 1 <= di <= 31):
            return ""
        return f"{yi:04d}{mi:02d}{di:02d}"

    for url in urls:
        try:
            html = _v319_http_get(url, timeout=12, retries=1)
        except Exception:
            continue
        if not html:
            continue
        found: list[str] = []
        for m in re.finditer(r"(20\d{2})[年/.\-](\d{1,2})[月/.\-](\d{1,2})", html):
            ds = _norm_ymd(m.group(1), m.group(2), m.group(3))
            if ds:
                _ = found.append(ds)
        for m in re.finditer(r"(?<!\d)(\d{2})/(\d{2})/(\d{2})(?!\d)", html):
            ds = _norm_ymd(m.group(1), m.group(2), m.group(3))
            if ds:
                _ = found.append(ds)
        if not found:
            continue
        # 対象レース日より先は捨てる
        if cap:
            found = [d for d in found if d <= cap]
        if not found:
            # ページ上は全部未来扱い → 対象以前の公式データなし
            return ""
        return max(found)
    return ""



def _v319_player_history_latest_fast(db_path: str, player_name: str, con=None) -> tuple[int, str]:
    """件数と最新開催日だけを取る（全行SELECTしない）。戻り値: (count, yyyymmdd)。"""
    key = _v319_norm_player_name(player_name)
    if not key:
        return 0, ""
    _own = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        if "v15_player_history_imports" not in _v319_schema_tables(con):
            return 0, ""
        cols = set(_v319_table_columns_cached(con, "v15_player_history_imports"))
        date_c = "race_date" if "race_date" in cols else ("開催日" if "開催日" in cols else None)
        if not date_c:
            return 0, ""
        row = con.execute(
            "SELECT COUNT(*), MAX(replace(replace(replace(COALESCE(\"%s\",''),'-',''),'/',''),'.',''))"
            " FROM v15_player_history_imports WHERE %s" % (date_c, _v319_name_where(con, "v15_player_history_imports")),
            (key,),
        ).fetchone()
        if not row:
            return 0, ""
        cnt = int(row[0] or 0)
        latest = re.sub(r"[^0-9]", "", str(row[1] or ""))
        latest = latest[:8] if len(latest) >= 8 else ""
        return cnt, latest
    except Exception:
        # 呼び出し側は (int, str) 前提
        return 0, ""
    finally:
        if _own:
            try:
                con.close()
            except Exception:
                pass


def _v319_player_history_count(db_path: str, player_name: str, con=None) -> int:
    key = _v319_norm_player_name(player_name)
    if not key:
        return 0
    _own = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        if "v15_player_history_imports" not in _v319_schema_tables(con):
            return 0
        row = con.execute(
            "SELECT COUNT(*) FROM v15_player_history_imports WHERE "
            + _v319_name_where(con, "v15_player_history_imports"),
            (key,),
        ).fetchone()
        return int((row or [0])[0] or 0)
    except Exception:
        # 呼び出し側は int 前提
        return 0
    finally:
        if _own:
            try:
                con.close()
            except Exception:
                pass


def _v319_player_history_counts_batch(db_path: str, player_names: list, con=None) -> dict:
    """複数選手の履歴件数を1クエリで取得。戻り値: {表示名: count}。

    照合キーは _v319_norm_player_name と同じ規則。
    失敗時は全員0（個別countと同じ「失敗=0件」方針）。
    """
    names = [str(n or "").strip() for n in (player_names or []) if str(n or "").strip()]
    out = {n: 0 for n in names}
    if not names:
        return out
    key_to_names: dict = {}
    for n in names:
        k = _v319_norm_player_name(n)
        if not k:
            continue
        key_to_names.setdefault(k, []).append(n)
    keys = list(key_to_names.keys())
    if not keys:
        return out
    _own = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        if "v15_player_history_imports" not in _v319_schema_tables(con):
            return out
        cols = set(_v319_table_columns_cached(con, "v15_player_history_imports"))
        ph = ",".join("?" * len(keys))
        # Ver324: key列があっても NULL/空は player_name 正規化で拾う
        # （engine 保存直後の行は key 未設定のため）
        expr = (
            "COALESCE(NULLIF(player_name_key,''),"
            "replace(replace(COALESCE(player_name,''),' ',''),'　',''))"
            if "player_name_key" in cols
            else "replace(replace(COALESCE(player_name,''),' ',''),'　','')"
        )
        rows = con.execute(
            f"""
            SELECT {expr}, COUNT(*)
            FROM v15_player_history_imports
            WHERE {expr} IN ({ph})
            GROUP BY 1
            """,
            tuple(keys),
        ).fetchall()
        for k, cnt in rows:
            kk = str(k or "")
            for nm in key_to_names.get(kk, []):
                out[nm] = int(cnt or 0)
        return out
    except Exception:
        return out
    finally:
        if _own:
            try:
                con.close()
            except Exception:
                pass

def _v319_parse_pc_player_history_html(html: str, player_name: str) -> list[dict]:
    """PC版 PlayerDetail HTML → 履歴行（R列あり）。"""
    tables = re.findall(r"(?is)<table[^>]*>(.*?)</table>", html or "")
    hist = []
    for table in tables:
        rows = re.findall(r"(?is)<tr[^>]*>(.*?)</tr>", table)
        if not rows:
            continue
        head = _v319_html_cells(rows[0])
        headj = "".join(head)
        if "着順" not in headj or ("試走" not in headj and "年月日" not in headj):
            continue

        def _col(names):
            for n in names:
                for i, h in enumerate(head):
                    if n in h:
                        return i
            return None

        i_d = _col(["年月日", "日付"])
        i_v = _col(["開催場"])
        i_nm = _col(["レース名"])
        i_r = _col(["R"])
        i_h = _col(["H", "ハンデ"])
        i_k = _col(["種別"])
        i_w = _col(["走路", "天候"])
        i_f = _col(["着順"])
        i_t = _col(["試走"])
        i_rt = _col(["競走"])
        i_st = _col(["ST"])
        for row in rows[1:]:
            cells = _v319_html_cells(row)
            if i_d is None or i_d >= len(cells) or i_f is None or i_f >= len(cells):
                continue

            def _at(i, default=""):
                return cells[i] if i is not None and i < len(cells) else default

            d, ven, rname = _at(i_d), _at(i_v), _at(i_nm)
            rno, hand, kind, weather = _at(i_r), _at(i_h), _at(i_k), _at(i_w)
            finish, trial, race_t, st = _at(i_f), _at(i_t), _at(i_rt), _at(i_st)
            acc = _at(_col(["異", "事故"]))
            if "映像" in (rname or ""):
                rname = re.sub(r"\s*\d*\s*レース映像", "", rname).strip()
            dm = re.match(r"(\d{2})/(\d{2})/(\d{2})", str(d or "").replace("-", "/"))
            if not dm:
                continue
            yy = int(dm.group(1))
            year = 2000 + yy if yy < 80 else 1900 + yy
            date_s = f"{year}-{dm.group(2)}-{dm.group(3)}"
            surf, sky = weather, ""
            wm = re.match(r"([^(]+)(?:\(([^)]+)\))?", weather or "")
            if wm:
                surf = (wm.group(1) or "").strip()
                sky = (wm.group(2) or "").strip()
            if surf in ("良", "湿", "斑"):
                surf = surf + "走路"
            fin = None
            if re.fullmatch(r"\d+", str(finish or "")):
                fin = int(finish)
            hnum = 0
            if re.search(r"\d+", str(hand or "")):
                hnum = int(re.search(r"\d+", str(hand)).group())
            hist.append({
                "選手名": player_name,
                "開催日": date_s,
                "開催場": ven,
                "レース": int(rno) if re.fullmatch(r"\d+", str(rno or "")) else 0,
                "レース名": rname,
                "レース種別": kind,
                "着順": fin,
                "走路": surf,
                "天候": sky,
                "ハンデ": hnum,
                "車番": 0,
                "試走T": trial,
                "競走T": race_t,
                "ST": st,
                "事故": acc,
                "走": "",
                "気": "",
                "湿": "",
            })
    return hist


def _v319_parse_sp_player_history_rows(html: str, player_name: str) -> list[dict]:
    """SP版から履歴行を構築（車番・天候あり。Rは0のことが多い）。"""
    text_body = _v319_html_to_text(html or "")
    out = []
    pat = re.compile(
        r"(?P<fin>\d+|欠車|欠責|他落|失格|落車)\s+"
        r"(?P<y>\d{4})年(?P<m>\d{1,2})月(?P<d>\d{1,2})日\s+"
        r"(?P<ven>川口|伊勢崎|浜松|飯塚|山陽)\s+"
        r"(?P<body>.{5,160}?)(?=(?:\d+|欠車|欠責|他落|失格|落車)\s+\d{4}年|$)",
        re.S,
    )
    for m in pat.finditer(text_body):
        body = re.sub(r"\s+", " ", m.group("body")).strip()
        car, hand = 0, 0
        cm = re.search(r"(\d+)番(\d+)m", body)
        if cm:
            car, hand = int(cm.group(1)), int(cm.group(2))
        else:
            cm2 = re.search(r"(\d+)番-m", body)
            if cm2:
                car = int(cm2.group(1))
        sky = ""
        for w in ("小雨", "雨", "雪", "曇", "晴"):
            if w in body:
                sky = w
                break
        surf = ""
        for s in ("斑", "湿", "良"):
            if re.search(rf"(?<![走気湿]){s}(?![走気湿度0-9.])", body) or f"{s}走路" in body:
                surf = s + "走路"
                break
        wx_track = wx_air = wx_hum = ""
        tm = re.search(r"走([\d.]+)", body)
        if tm:
            wx_track = tm.group(1)
        am = re.search(r"気([\d.]+)", body)
        if am:
            wx_air = am.group(1)
        hm = re.search(r"湿([\d.]+)", body)
        if hm:
            wx_hum = hm.group(1)
        race_t = trial = st = ""
        # 末尾の 競走T 試T ST
        times = re.findall(r"(?<![走気湿番\d])(\d\.\d{2,3})", body)
        # 人気の数字を除外しにくいので「3.xxx」を競走、試を優先
        tm2 = re.search(r"試\s*([\d.]+)", body)
        if tm2:
            trial = tm2.group(1)
        stm = re.search(r"ST\s*([\d.]+)", body, re.I)
        if stm:
            st = stm.group(1)
        # 競走タイム: 試の前にある 3.xxx を優先
        rt_m = re.search(r"(?<![走気湿\d])(3\.\d{3}|4\.\d{3}|0\.000)(?!\d)", body)
        if rt_m:
            race_t = rt_m.group(1)
        # レース名: 場の直後〜天候の前
        rname = body
        for cut in ("小雨", "雨", "雪", "曇", "晴", "走", "気", "湿", "番"):
            idx = rname.find(cut)
            if idx > 0:
                rname = rname[:idx].strip()
                break
        rname = re.sub(r"\d+人気.*$", "", rname).strip()
        # Ver324: SP本文から R を拾う（従来は常に0でDBに空レースが残った）
        rn = 0
        for blob in (body, rname):
            m_rn = re.search(r"(?<!\d)([1-9]|1[0-2])\s*R\b", str(blob or ""), flags=re.I)
            if not m_rn:
                m_rn = re.search(r"第\s*([1-9]|1[0-2])\s*レース", str(blob or ""))
            if m_rn:
                rn = int(m_rn.group(1))
                break
        date_s = f"{m.group('y')}-{int(m.group('m')):02d}-{int(m.group('d')):02d}"
        fin_s = m.group("fin")
        fin = int(fin_s) if re.fullmatch(r"\d+", fin_s) else None
        acc = "" if fin is not None else fin_s
        out.append({
            "選手名": player_name,
            "開催日": date_s,
            "開催場": m.group("ven"),
            "レース": rn,
            "レース名": rname,
            "レース種別": "",
            "着順": fin,
            "走路": surf,
            "天候": sky,
            "ハンデ": hand,
            "車番": car,
            "試走T": trial,
            "競走T": race_t,
            "ST": st,
            "事故": acc,
            "走": wx_track,
            "気": wx_air,
            "湿": wx_hum,
        })
    return out


def _v319_fetch_player_history_df(player_cd: str, player_name: str, timeout: int = 10, retries: int = 1):
    """PC版を優先。有効HTMLが取れたら PC2/SP は打たない（空履歴でも）。

    Ver324速度:
      - timeout 10 / retries 1（旧15/2）。失敗は errors で再試行可能
      - 同一 player_cd はジョブ内メモ化
      - 全リクエスト例外で空になった場合はキャッシュしない（次レースで再試行）
    """
    global _V319_HIST_DF_CACHE
    pcd = str(player_cd or "").strip()
    name = str(player_name or "").strip()
    if pcd and pcd in _V319_HIST_DF_CACHE:
        cached = _V319_HIST_DF_CACHE[pcd]
        try:
            return cached.copy() if hasattr(cached, "copy") else cached
        except Exception:
            return cached

    hist: list[dict] = []
    pc_err = ""
    pc_ok = False
    # 1) PC版（historyDispType=d を優先、空ページでも有効HTMLなら打ち切り）
    if pcd:
        for url in (
            f"https://www.oddspark.com/autorace/PlayerDetail.do?playerCd={pcd}&historyDispType=d",
            f"https://www.oddspark.com/autorace/PlayerDetail.do?playerCd={pcd}",
        ):
            try:
                html = _v319_http_get(url, timeout=int(timeout or 10), retries=int(retries if retries is not None else 1))
                if html and len(html) > 500:
                    pc_ok = True
                hist = _v319_parse_pc_player_history_html(html, name)
                if hist:
                    break
                if pc_ok:
                    # 有効HTMLだが履歴0 → PC2/SPを打たない
                    break
            except Exception as exc:
                pc_err = f"{type(exc).__name__}:{exc}"
                hist = []
    # 2) SP版: PCが完全失敗したときだけ
    sp_rows: list[dict] = []
    if pcd and not pc_ok:
        try:
            sp_url = (
                "https://sp.oddspark.com/autorace/SpPlayerDetail.do"
                f"?playerCd={pcd}&historyDispType=d"
            )
            sp_html = _v319_http_get(sp_url, timeout=int(timeout or 10), retries=int(retries if retries is not None else 1))
            sp_rows = _v319_parse_sp_player_history_rows(sp_html, name)
        except Exception:
            sp_rows = []
    if not hist and sp_rows:
        hist = sp_rows
        out = pd.DataFrame(hist) if hist else pd.DataFrame()
    elif hist and sp_rows:
        df = pd.DataFrame(hist)
        out = _v319_merge_sp_enrich(df, sp_rows)
    elif hist:
        out = pd.DataFrame(hist)
    else:
        out = pd.DataFrame()
    # Ver324: 有効HTMLを1回も得られていない（全リクエスト失敗）→ None
    # 呼び出し側は errors 扱いし、スキップキャッシュに書かない。
    # 本当に履歴0件（pc_ok=True, hist=[]）は空DFのまま返す。
    _all_failed = (not pc_ok) and (not hist) and (not sp_rows)
    if _all_failed:
        return None
    if pcd:
        try:
            _V319_HIST_DF_CACHE[pcd] = out.copy() if hasattr(out, "copy") else out
        except Exception:
            _V319_HIST_DF_CACHE[pcd] = out
    return out


def _v319_fetch_sp_player_history_enrich(player_cd: str) -> list[dict]:
    """互換: SP版行を enrich 形式で返す。"""
    try:
        sp_url = (
            "https://sp.oddspark.com/autorace/SpPlayerDetail.do"
            f"?playerCd={player_cd}&historyDispType=d"
        )
        sp_html = _v319_http_get(sp_url, timeout=18, retries=2)
        rows = _v319_parse_sp_player_history_rows(sp_html, "")
        return rows
    except Exception:
        return []


def _v319_merge_sp_enrich(df: pd.DataFrame, enrich: list[dict]) -> pd.DataFrame:
    """PC版履歴（R付き）に SP版の車番・天候を日付+場(+着順)で補完。"""
    if df is None or df.empty or not enrich:
        return df
    df = df.copy()
    if "車番" not in df.columns:
        df["車番"] = 0
    for col in ("走", "気", "湿"):
        if col not in df.columns:
            df[col] = ""
    buckets: dict[tuple, list] = {}
    for e in enrich:
        key = (_v319_ymd_digits(e.get("開催日")), str(e.get("開催場") or "").strip())
        buckets.setdefault(key, []).append(e)
    for i, r in df.iterrows():
        key = (_v319_ymd_digits(r.get("開催日")), str(r.get("開催場") or "").strip())
        cands = buckets.get(key) or []
        if not cands:
            continue
        pick = None
        try:
            fin = int(r.get("着順")) if pd.notna(r.get("着順")) else None
        except Exception:
            fin = None
        if fin is not None:
            for e in cands:
                try:
                    if e.get("着順") == fin:
                        pick = e
                        break
                except Exception:
                    pass
        if pick is None:
            pick = cands[0]
        if int(df.at[i, "車番"] or 0) <= 0 and int(pick.get("車番") or 0) > 0:
            df.at[i, "車番"] = int(pick["車番"])
        if not str(df.at[i, "天候"] or "").strip() and pick.get("天候"):
            df.at[i, "天候"] = pick["天候"]
        if not str(df.at[i, "走路"] or "").strip() and pick.get("走路"):
            df.at[i, "走路"] = pick["走路"]
        for col in ("走", "気", "湿"):
            if not str(df.at[i, col] or "").strip() and pick.get(col):
                df.at[i, col] = pick[col]
        try:
            if int(df.at[i, "ハンデ"] or 0) <= 0 and int(pick.get("ハンデ") or 0) > 0:
                df.at[i, "ハンデ"] = int(pick["ハンデ"])
        except Exception:
            pass
        # 競走Tなどが空ならSPから
        for col in ("試走T", "競走T", "ST", "レース名"):
            if col in df.columns and not str(df.at[i, col] or "").strip() and pick.get(col):
                df.at[i, col] = pick[col]
    return df



def _v319_history_from_results(
    db_path: str, player_name: str, before_ymd: str, before_venue: str, before_race: int,
    con=None,
) -> pd.DataFrame:
    """result_races/result_entries から履歴行を作る。

    Ver319: con を渡すとその接続を共有し、閉じない（呼び出し側が管理する）。
    """
    key = _v319_norm_player_name(player_name)
    if not key:
        return pd.DataFrame()
    _own = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        try:
            tables = _v319_schema_tables(con)
            if "result_races" not in tables or "result_entries" not in tables:
                return pd.DataFrame()
            re_cols = set(_v319_table_columns_cached(con, "result_entries"))
            car_expr = "re.car_no" if "car_no" in re_cols else "NULL"
            trial_expr = "re.trial_time" if "trial_time" in re_cols else ("re.trial" if "trial" in re_cols else "NULL")
            rows = con.execute(
                f"""
                SELECT rr.race_date, rr.venue, rr.race_no,
                       re.finish, re.handicap, re.race_time, re.start_time,
                       re.player_name, {car_expr}, {trial_expr}
                FROM result_entries re
                JOIN result_races rr ON rr.race_key=re.race_key
                WHERE {_v319_name_where(con, "result_entries", "re")}
                """,
                (key,),
            ).fetchall()
        except Exception:
            return pd.DataFrame()
    finally:
        if _own:
            try:
                con.close()
            except Exception:
                pass
    out = []
    for race_date, venue, race_no, finish, hand, race_t, st, pname, car_no, trial in rows:
        try:
            car_i = int(car_no) if car_no is not None and str(car_no).strip() not in {"", "None"} else 0
        except Exception:
            car_i = 0
        rec = {
            "選手名": pname or player_name,
            "開催日": str(race_date or "")[:10],
            "開催場": venue,
            "レース": race_no,
            "レース名": "",
            "レース種別": "",
            "着順": finish,
            "走路": "",
            "天候": "",
            "ハンデ": hand or 0,
            "車番": car_i,
            "試走T": trial or "",
            "競走T": race_t,
            "ST": st,
            "事故": "",
        }
        if before_ymd and not _v319_hist_row_before(rec, before_ymd, before_venue, before_race):
            continue
        _ = out.append(rec)
    return pd.DataFrame(out)


def _v319_hist_row_before(row, ymd: str, venue: str, race_no: int) -> bool:
    ds = _v319_ymd_digits(row.get("開催日") if hasattr(row, "get") else "")
    cur = _v319_ymd_digits(ymd)
    if not ds or not cur:
        return False
    if ds < cur:
        return True
    if ds > cur:
        return False
    vn = str((row.get("開催場") if hasattr(row, "get") else "") or "").replace("　", "").strip()
    cur_v = str(venue or "").replace("　", "").strip()
    try:
        rn = int(row.get("レース") or 0)
    except Exception:
        rn = 0
    if vn and cur_v and vn != cur_v:
        return True
    try:
        cap = int(race_no or 0)
    except Exception:
        cap = 0
    return cap > 0 and rn > 0 and rn < cap


def _v319_hist_row_key(row) -> tuple:
    """一意キー (開催日, 場, R)。R不明時は着順・車番から仮Rを作って同日複数を残す。"""
    ds = _v319_ymd_digits(row.get("開催日") if hasattr(row, "get") else "")
    vn = str((row.get("開催場") if hasattr(row, "get") else "") or "").replace("　", "").strip()
    try:
        rn = int(row.get("レース") or 0)
    except Exception:
        rn = 0
    if rn > 0:
        return (ds, vn, rn)
    try:
        fin = int(row.get("着順")) if row.get("着順") is not None and str(row.get("着順")).replace(".0","").strip().isdigit() else 0
    except Exception:
        fin = 0
    try:
        car = int(row.get("車番") or 0)
    except Exception:
        car = 0
    # 仮R: 900+着順 または 800+車番（DBの実R 1-12 と衝突しない）
    fake = 900 + max(fin, 0) if fin else (800 + max(car, 0) if car else 700)
    return (ds, vn, int(fake))



def _v319_fill_missing_race_nos(df: pd.DataFrame, db_path: str = "", player_name: str = "") -> pd.DataFrame:
    """レース番号が空/0の行を補完する。

    優先順:
      1) レース名・種別内の「N R」表記
      2) result_entries（日付+場+選手名）

    Ver324: 「一般戦」「予選」など非数値がレース列に入っている場合はレース名へ退避してから補完。
    """
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return df
    df = df.copy()
    if "レース" not in df.columns:
        df["レース"] = 0
    # 0) 非数値レース値をレース名へ退避
    for i, row in df.iterrows():
        raw = row.get("レース")
        try:
            cur = int(pd.to_numeric(raw, errors="coerce") or 0)
        except Exception:
            cur = 0
        if 1 <= cur <= 12:
            df.at[i, "レース"] = cur
            continue
        s = str(raw or "").strip()
        if s and not re.fullmatch(r"\d+(\.0+)?", s):
            # 一般戦/予選 等がレース列に混入
            if "レース名" in df.columns and not str(row.get("レース名") or "").strip():
                df.at[i, "レース名"] = s
            df.at[i, "レース"] = 0
    # 1) テキストから
    for i, row in df.iterrows():
        try:
            cur = int(pd.to_numeric(row.get("レース"), errors="coerce") or 0)
        except Exception:
            cur = 0
        if 1 <= cur <= 12:
            df.at[i, "レース"] = cur
            continue
        blob = " ".join(
            str(row.get(c) or "")
            for c in ("レース名", "レース種別", "レース")
        )
        m = re.search(r"(?<!\d)([1-9]|1[0-2])\s*R\b", blob, flags=re.I)
        if not m:
            m = re.search(r"第\s*([1-9]|1[0-2])\s*レース", blob)
        if m:
            df.at[i, "レース"] = int(m.group(1))
    # 2) 結果DBから
    if not db_path:
        return df
    need_idx = []
    for i, row in df.iterrows():
        try:
            cur = int(pd.to_numeric(row.get("レース"), errors="coerce") or 0)
        except Exception:
            cur = 0
        if cur <= 0:
            _ = need_idx.append(i)
    if not need_idx:
        return df
    try:
        with sqlite3.connect(str(db_path)) as con:
            con.row_factory = sqlite3.Row
            tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if "result_entries" not in tables or "result_races" not in tables:
                return df
            for i in need_idx:
                row = df.loc[i]
                ds = _v319_ymd_digits(row.get("開催日"))
                if len(ds) == 8:
                    date_s = f"{ds[:4]}-{ds[4:6]}-{ds[6:8]}"
                else:
                    date_s = str(row.get("開催日") or "")[:10]
                vn = str(row.get("開催場") or "").replace("　", "").strip()
                pname = str(row.get("選手名") or player_name or "").replace("　", "").replace(" ", "").strip()
                if not date_s or not vn or not pname:
                    continue
                q = """
                    SELECT rr.race_no, re.finish_order, re.car_no
                    FROM result_entries re
                    JOIN result_races rr ON rr.race_key = re.race_key
                    WHERE rr.race_date = ?
                      AND replace(replace(COALESCE(rr.venue,''),' ',''),'　','') = ?
                      AND replace(replace(COALESCE(re.player_name,''),' ',''),'　','') = ?
                """
                cands = con.execute(
                    q,
                    (date_s, vn.replace(" ", ""), pname),
                ).fetchall()
                if not cands:
                    # 日付ゆれ
                    cands = con.execute(
                        """
                        SELECT rr.race_no, re.finish_order, re.car_no
                        FROM result_entries re
                        JOIN result_races rr ON rr.race_key = re.race_key
                        WHERE replace(replace(COALESCE(rr.race_date,''),'-',''),'/','') = ?
                          AND replace(replace(COALESCE(rr.venue,''),' ',''),'　','') = ?
                          AND replace(replace(COALESCE(re.player_name,''),' ',''),'　','') = ?
                        """,
                        (ds, vn.replace(" ", ""), pname),
                    ).fetchall()
                if not cands:
                    continue
                pick = None
                try:
                    fin = int(pd.to_numeric(row.get("着順"), errors="coerce"))
                except Exception:
                    fin = None
                try:
                    car = int(pd.to_numeric(row.get("車番"), errors="coerce") or 0)
                except Exception:
                    car = 0
                if fin is not None:
                    for c in cands:
                        try:
                            if int(c["finish_order"] or 0) == fin:
                                pick = c
                                break
                        except Exception:
                            pass
                if pick is None and car > 0:
                    for c in cands:
                        try:
                            if int(c["car_no"] or 0) == car:
                                pick = c
                                break
                        except Exception:
                            pass
                if pick is None and len(cands) == 1:
                    pick = cands[0]
                if pick is not None:
                    try:
                        rn = int(re.sub(r"[^0-9]", "", str(pick["race_no"] or "")) or 0)
                        if 1 <= rn <= 12:
                            df.at[i, "レース"] = rn
                    except Exception:
                        pass
    except Exception:
        return df
    return df


def _v319_build_player_history_lines(
    player_name: str, df: pd.DataFrame, *, fetch_weather: bool = False
) -> list[str]:
    """履歴テキスト生成。同名レース識別のため R番号を必ず入れる。

    fetch_weather=False（既定）: 自動取込中のHTTP連打を避ける。
    """
    lines = [str(player_name)]
    for n, (_, r) in enumerate(df.iterrows()):
        if n == 0:
            _ = lines.append("前走")
        elif n == 1:
            _ = lines.append("前々走")
        else:
            _ = lines.append(f"{n + 1}走前")
        acc = str(r.get("事故") or "")
        fin = r.get("着順")
        if "欠責" in acc:
            _ = lines.append("欠責")
        elif "欠車" in acc:
            _ = lines.append("欠車")
        elif pd.notna(fin) and str(fin).strip() and str(fin).replace(".0", "", 1).isdigit():
            _ = lines.append(str(int(float(fin))))
        else:
            _ = lines.append(str(fin or "欠車"))
        ds = str(r.get("開催日") or "")
        dm = re.match(r"(\d{4})-(\d{2})-(\d{2})", ds)
        _ = lines.append(f"{dm.group(1)}年{int(dm.group(2))}月{int(dm.group(3))}日" if dm else ds)
        venue = str(r.get("開催場") or "").strip()
        try:
            rn = int(pd.to_numeric(r.get("レース"), errors="coerce") or 0)
        except Exception:
            rn = 0
        if rn <= 0:
            blob = " ".join(str(r.get(c) or "") for c in ("レース名", "レース種別"))
            m_rn = re.search(r"(?<!\d)([1-9]|1[0-2])\s*R\b", blob, flags=re.I)
            if not m_rn:
                m_rn = re.search(r"第\s*([1-9]|1[0-2])\s*レース", blob)
            if m_rn:
                rn = int(m_rn.group(1))
        # 公式貼付形式: 開催場と R を別行（結合するとパーサがRを落とす）
        if venue:
            _ = lines.append(venue)
        if 1 <= rn <= 12:
            _ = lines.append(f"{rn}R")
        rname = str(r.get("レース名") or "").strip()
        rname = re.sub(r"\s*\d*\s*レース映像", "", rname).strip()
        if not rname and r.get("レース種別"):
            rname = str(r.get("レース種別") or "").strip()
        if rname:
            short = re.sub(r"^令和[^\s　]*[市営]*\s*", "", rname)
            short = re.sub(r"\s*\d+\s*/\s*\d+[～~]?", "", short)
            short = short.strip() or rname
            if len(short) > 40:
                short = short[-40:]
            _ = lines.append(short)
        elif r.get("レース種別"):
            _ = lines.append(str(r.get("レース種別")))
        sky = str(r.get("天候") or "").replace("走路", "")
        if sky:
            _ = lines.append(sky)
        surf = str(r.get("走路") or "良").replace("走路", "")
        _ = lines.append(surf or "良")
        # SP補完の走/気/湿があれば使う（HTTPしない）
        for col, prefix in (("走", "走"), ("気", "気"), ("湿", "湿")):
            val = str(r.get(col) or "").strip()
            if val:
                _ = lines.append(f"{prefix}{val}")
        if fetch_weather and not any(str(r.get(c) or "").strip() for c in ("走", "気", "湿")):
            ymd_wx = re.sub(r"[^0-9]", "", ds)
            try:
                wx = _v319_race_weather(ymd_wx, venue, rn or 0)
            except Exception:
                wx = {}
            if wx.get("走"):
                _ = lines.append(f"走{wx['走']}")
            if wx.get("気"):
                _ = lines.append(f"気{wx['気']}")
            if wx.get("湿"):
                _ = lines.append(f"湿{wx['湿']}")
        try:
            hnum = int(r.get("ハンデ") or 0)
        except Exception:
            hnum = 0
        try:
            car = int(r.get("車番") or 0)
        except Exception:
            car = 0
        if car > 0:
            _ = lines.append(f"{car}番{hnum}m" if hnum else f"{car}番-m")
        elif hnum:
            _ = lines.append(f"ハンデ{hnum}m")
        else:
            _ = lines.append("ハンデ-m")
        _ = lines.append("3100m(6周)")
        race_t = str(r.get("競走T") or "0.000").replace("試", "")
        trial = str(r.get("試走T") or "-")
        stv = str(r.get("ST") or "0.00")
        _ = lines.append(race_t if race_t else "0.000")
        _ = lines.append(f"試{trial}" if not str(trial).startswith("試") else str(trial))
        _ = lines.append(f"ST{stv}" if not str(stv).upper().startswith("ST") else str(stv))
        if "F" in acc or acc in {"F", "フライング"}:
            _ = lines.append("F")
        elif acc and acc not in {"欠責", "欠車", "-", ""}:
            _ = lines.append(acc)
    return lines



def _v319_fill_player_histories(
    db_path: str,
    players: list[dict],
    min_rows: int = 30,
    before_ymd: str = "",
    before_venue: str = "",
    before_race: int = 0,
    con=None,
    _exclusive: bool = False,
    cancel_cb=None,
) -> dict:
    """選手履歴を公式PC版 PlayerDetail から取得して保存。

    Ver319改:
      - 新規（DB min_rows未満）: 従来どおり min_rows 件を取得
      - 既存（min_rows以上）: DB最新日〜対象日の「穴」を全部埋める
        （公式最新≦DB最新でもキー包含チェックを行い、missing があれば取り込む）

    Ver319改善#2: 1レース分は接続を1本だけ開いて使い回す（毎回connectしない）。
    con を渡された場合はその接続を共有し、閉じない（呼び出し側が管理する）。
    con=None のときだけ接続を開き、終了時に close する。
    _exclusive=True かつ自分で開いた接続のときは BEGIN IMMEDIATE でまとめて書く。

    - R番号は公式テーブルの R 列から取得（SP版にはRが無い）
    - 件数不足・R欠落・公式欠けがあれば再取込（選手ごとに1プロセス1回まで）
    - 天候HTTPは自動取込では叩かない（途中停止の主因だった）
    """
    global _V319_HIST_REFRESHED, _V319_HIST_SKIPPED
    added = 0
    skipped = 0
    errors = 0
    details = []
    min_rows = int(min_rows or 30)
    # con を自分で開いたときだけ閉じる（_exclusive と独立）。
    # 以前は _own_con2 = (con is None and _exclusive) のため、
    # 通常呼び出し（con=None, _exclusive=False）で接続がリークしていた。
    _own_con = con is None
    if con is None:
        con = _v319_open_conn(db_path)
    try:
        if _exclusive and _own_con:
            try:
                con.execute("BEGIN IMMEDIATE")
            except Exception:
                pass

        before_d_job = _v319_ymd_digits(before_ymd)  # ループ共通（ジョブ内キャッシュキー）

        # Ver324速度: 公式HTTPが必要な選手だけ先に並列取得（結果は _V319_HIST_DF_CACHE へ）
        try:
            _prefetch = []
            for _pp in players:
                _nm = str(_pp.get("name") or "").strip()
                _pcd = str(_pp.get("player_cd") or "").strip()
                if not _pcd:
                    continue
                _ck = _pcd or _v319_norm_player_name(_nm)
                _ask = str(_V319_HIST_SKIPPED.get(_ck) or "")
                if _ask and before_d_job and _ask == before_d_job:
                    continue
                if _pcd in _V319_HIST_DF_CACHE:
                    continue
                if before_d_job:
                    try:
                        _ps = _v319_persistent_skip_lookup(db_path, _pcd, before_d_job, con=con)
                        if _ps and _ps.get("skip"):
                            continue
                    except Exception:
                        pass
                try:
                    _hv, _lt = _v319_player_history_latest_fast(db_path, _nm, con=con)
                    _lt = _v319_ymd_digits(_lt)
                    if int(_hv or 0) >= min_rows and _lt and before_d_job and _lt >= before_d_job:
                        continue
                except Exception:
                    pass
                _prefetch.append((_pcd, _nm))
            if len(_prefetch) >= 2:
                _n_workers = min(4, len(_prefetch))
                with ThreadPoolExecutor(max_workers=_n_workers) as _ex:
                    _futs = [
                        _ex.submit(_v319_fetch_player_history_df, _pcd, _nm)
                        for _pcd, _nm in _prefetch
                    ]
                    for _fu in as_completed(_futs):
                        if callable(cancel_cb):
                            try:
                                if bool(cancel_cb()):
                                    break
                            except Exception:
                                pass
                        try:
                            _ = _fu.result()
                        except Exception:
                            pass
        except Exception:
            pass

        for p in players:
            # 中止要求: 選手単位で即抜ける（長いHTTP中も次選手前に止まる）
            if callable(cancel_cb):
                try:
                    if bool(cancel_cb()):
                        details.append("中止要求により選手履歴取込を中断")
                        return {
                            "added": added, "skipped": skipped, "errors": errors,
                            "details": details, "cancelled": True,
                        }
                except Exception:
                    pass
            name = p.get("name") or ""
            pcd = str(p.get("player_cd") or "").strip()
            cache_key = pcd or _v319_norm_player_name(name)
            already_refreshed = cache_key in _V319_HIST_REFRESHED
            # Ver320: dict[cache_key] = before_d。同一開催日なら前レースで充足確認済み
            already_skipped_d = str(_V319_HIST_SKIPPED.get(cache_key) or "")
            try:
                # === 最速パス：同一取込ジョブ内・同じ開催日は DB SELECT すら打たない ===
                if already_skipped_d and before_d_job and already_skipped_d == before_d_job:
                    skipped += 1
                    _ = details.append(f"{name}:ジョブ内キャッシュ即スキップ")
                    continue
                # before_d 無しでも「充足確認済み」マークがあれば即スキップ
                if already_skipped_d and not before_d_job:
                    skipped += 1
                    _ = details.append(f"{name}:ジョブ内キャッシュ即スキップ")
                    continue

                # Ver324: DB永続スキップ（再起動後も同対象日は HTTP しない）
                if pcd and before_d_job:
                    _persist = _v319_persistent_skip_lookup(
                        db_path, pcd, before_d_job, con=con
                    )
                    if _persist and _persist.get("skip"):
                        skipped += 1
                        _V319_HIST_SKIPPED[cache_key] = before_d_job
                        _ = details.append(f"{name}:{_persist.get('reason')}")
                        continue

                if not pcd:
                    errors += 1
                    _ = details.append(f"{name}:playerCdなし")
                    continue
                before_d = before_d_job

                # ========== 1) DB状態（軽量） ==========
                # 履歴ヘルパは失敗時も 0/(0,"")/空dict を返す（Noneは返さない）。
                have, latest_d = _v319_player_history_latest_fast(db_path, name, con=con)
                latest_d = _v319_ymd_digits(latest_d)
                is_existing = (have >= min_rows and bool(latest_d))

                # Ver320/321: 1度十分に登録済みなら、公式再取得・keys照合をしない。
                if is_existing and ((not before_d) or (latest_d >= before_d)):
                    skipped += 1
                    _V319_HIST_SKIPPED[cache_key] = before_d or latest_d or "1"
                    _ = details.append(
                        f"{name}:充足スキップ(既存{have}件/最新{latest_d}"
                        f"{'/対象'+before_d if before_d else ''})"
                    )
                    continue

                # ここから先だけ keys 照合・公式HTTPが必要（件数不足 or 対象日より古い）
                state = _v319_player_history_state(db_path, name, con=con) or {}
                have_keys = set(state.get("keys") or set())
                # Ver320: R欠落だけでは再取得しない。
                # 日付・場が揃っていれば予測特徴量は使える。Rは識別補助のみ。
                # 真の dirty は「日付または場が無い」行だけ。
                dirty_keys = set()
                for k in have_keys:
                    ds = str(k[0] or "").strip()
                    vn = str(k[1] or "").strip()
                    if not ds or not vn:
                        dirty_keys.add(k)

                # ========== 2) 公式履歴を取得 ==========
                details.append(
                    f"{name}:取得開始(DB{have}件/最新{latest_d or 'なし'}/対象{before_d or '-'})"
                )
                df = _v319_fetch_player_history_df(pcd, name)
                # 取得失敗（None）は常に errors。スキップ・永続キャッシュに書かない。
                if df is None:
                    errors += 1
                    _ = details.append(f"{name}:取得失敗(再試行対象/cd={pcd or '-'})")
                    continue
                if df.empty:
                    if have <= 0:
                        errors += 1
                        _ = details.append(f"{name}:履歴0件(cd={pcd or '-'})")
                    else:
                        skipped += 1
                        _ = details.append(f"{name}:公式0件/既存{have}")
                    # 公式0件の成功応答は「対象日まで確認済み」としてキャッシュ可
                    if before_d and pcd and have > 0:
                        _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                        _v319_persistent_skip_mark(db_path, pcd, before_d, latest_d, con=con)
                    continue

                if "車番" not in df.columns:
                    df["車番"] = 0

                def _rn(v):
                    try:
                        if v is None or (isinstance(v, float) and pd.isna(v)):
                            return 0
                        s = str(v).strip()
                        if re.fullmatch(r"\d+", s):
                            return int(s)
                    except Exception:
                        pass
                    return 0

                df = df.copy()
                if "レース" in df.columns:
                    df["レース"] = df["レース"].map(_rn)
                else:
                    df["レース"] = 0

                # 対象日以前に限定
                if before_ymd:
                    _rows = [
                        r for _, r in df.iterrows()
                        if _v319_hist_row_before(r, before_ymd, before_venue, before_race)
                    ]
                    df = pd.DataFrame(_rows)
                    if df.empty:
                        if have <= 0:
                            errors += 1
                            _ = details.append(f"{name}:当該R以前の履歴0件")
                        else:
                            skipped += 1
                            _ = details.append(f"{name}:当該R以前は追加なし")
                        continue

                # result_entries からの補完
                extra = _v319_history_from_results(
                    db_path, name, before_ymd or latest_d, before_venue, before_race,
                    con=con,
                )
                if extra is not None and not extra.empty:
                    if "車番" not in extra.columns:
                        extra["車番"] = 0
                    extra = extra.copy()
                    if "レース" in extra.columns:
                        extra["レース"] = extra["レース"].map(_rn)
                    else:
                        extra["レース"] = 0
                    df = pd.concat([df, extra], ignore_index=True)

                # 公式側の全キー
                official_keys = set()
                for _, r in df.iterrows():
                    k = _v319_hist_row_key(r)
                    if k[0] and k[2] > 0:
                        official_keys.add(k)

                missing_official = official_keys - have_keys

                # ========== 3) 取り込む対象を決定 ==========
                if not is_existing:
                    # 新規 or min_rows未満: min_rows 件を確保
                    need_refresh = (not already_refreshed) and (
                        bool(dirty_keys) or len(missing_official) >= 1 or have < 15
                    )
                    target_count = max(min_rows, min(len(df), min_rows))
                    if dirty_keys:
                        # R欠落行の再構築を優先（多めに取り直す）
                        target_count = max(target_count, min(len(df), max(min_rows, 35)))
                else:
                    # 既存: 穴を全部埋める。missing_official が空かつ dirty なしなら更新不要。
                    if not missing_official and not dirty_keys:
                        skipped += 1
                        _ = details.append(f"{name}:穴なしスキップ(既存{have}件/最新{latest_d})")
                        # 対象日より前に穴なし＝公式確認済み。latest < 対象日でもキャッシュする
                        # （当日レース前は latest が対象日以上にならないため）
                        if before_d:
                            _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                            if pcd:
                                _v319_persistent_skip_mark(
                                    db_path, pcd, before_d, latest_d or before_d, con=con
                                )
                        continue
                    # 穴埋め対象: missing_official を全部 + R欠落行の再構築
                    need_refresh = True
                    target_count = len(df)

                # ========== 4) 取り込み行を構築 ==========
                keep = []
                seen = set()
                if is_existing:
                    # 穴埋めモード: missing_official と dirty_keys に含まれるキーだけを厳密に追加
                    for _, r in df.iterrows():
                        k = _v319_hist_row_key(r)
                        if not k[0] or k in seen:
                            continue
                        if before_ymd and not _v319_hist_row_before(
                            r, before_ymd, before_venue, before_race
                        ):
                            continue
                        # 既存キーでも R欠落で再構築対象のものは通す
                        if k in have_keys and k not in dirty_keys:
                            continue
                        seen.add(k)
                        _ = keep.append(r)
                else:
                    # 新規/再取込モード: DB最新日以降〜対象日までを広く追加。
                    # 既存キーはスキップ（重複追加防止）。
                    for _, r in df.iterrows():
                        k = _v319_hist_row_key(r)
                        if not k[0] or k in seen:
                            continue
                        if before_ymd and not _v319_hist_row_before(
                            r, before_ymd, before_venue, before_race
                        ):
                            continue
                        seen.add(k)
                        if k in have_keys and k not in dirty_keys:
                            continue
                        _ = keep.append(r)
                    # min_rows を満たすよう先頭から切る（新規のみ）
                    if len(keep) > target_count:
                        keep = keep[:target_count]

                if not keep:
                    skipped += 1
                    _ = details.append(f"{name}:追加対象なし(既存{have}/公式{len(official_keys)})")
                    # 一度公式を見て追加不要 → 同対象日は再HTTPしない（永続も）
                    if before_d and (is_existing or have >= min_rows):
                        _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                        if pcd:
                            _v319_persistent_skip_mark(
                                db_path, pcd, before_d, latest_d or before_d, con=con
                            )
                    elif is_existing or have >= min_rows:
                        _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                    continue

                work = pd.DataFrame(keep)
                if "車番" in work.columns:
                    work["_car"] = pd.to_numeric(work["車番"], errors="coerce").fillna(0).astype(int)
                else:
                    work["_car"] = 0
                work["レース"] = work["レース"].map(_rn)
                work = work.sort_values(["_car"], ascending=False, kind="mergesort")
                work["_key"] = work.apply(lambda r: _v319_hist_row_key(r), axis=1)
                work = work.drop_duplicates(subset=["_key"], keep="first")
                work = work.drop(columns=["_car", "_key"], errors="ignore")
                work["_ymd"] = work["開催日"].map(_v319_ymd_digits)
                work = work.sort_values("_ymd", ascending=False, kind="mergesort").drop(columns=["_ymd"])

                # ========== 5) 解析・保存 ==========
                try:
                    work = _v319_fill_missing_race_nos(work, db_path=db_path, player_name=name)
                except Exception:
                    pass

                lines = _v319_build_player_history_lines(name, work, fetch_weather=False)
                parsed = None
                try:
                    parsed = engine.v15_parse_player_history(
                        "\n".join(lines), player_name=str(name).strip()
                    )
                except Exception:
                    parsed = None
                if not isinstance(parsed, pd.DataFrame) or parsed.empty:
                    parsed = work.copy()
                elif len(parsed) < max(8, int(len(work) * 0.5)) and len(work) >= 8:
                    parsed = work.copy()
                else:
                    # 解析でRが落ちたら元dfから戻す
                    try:
                        src = work.copy()
                        src["_ds"] = src["開催日"].map(_v319_ymd_digits)
                        src["_vn"] = src["開催場"].map(
                            lambda x: str(x or "").replace("　", "").strip()
                        )
                        rmap = {}
                        for _, sr in src.iterrows():
                            try:
                                rv = int(sr.get("レース") or 0)
                            except Exception:
                                rv = 0
                            if rv > 0:
                                rmap[(sr["_ds"], sr["_vn"])] = rv
                        if "レース" not in parsed.columns:
                            parsed = parsed.copy()
                            parsed["レース"] = 0
                        for i, pr in parsed.iterrows():
                            try:
                                cur = int(pd.to_numeric(pr.get("レース"), errors="coerce") or 0)
                            except Exception:
                                cur = 0
                            if cur <= 0:
                                k = (
                                    _v319_ymd_digits(pr.get("開催日")),
                                    str(pr.get("開催場") or "").replace("　", "").strip(),
                                )
                                if k in rmap:
                                    parsed.at[i, "レース"] = rmap[k]
                    except Exception:
                        pass

                parsed = parsed.copy()
                if "選手名" not in parsed.columns:
                    parsed["選手名"] = name
                else:
                    parsed["選手名"] = parsed["選手名"].fillna(name)
                    parsed.loc[
                        parsed["選手名"].astype(str).str.strip().isin(["", "nan", "None"]),
                        "選手名",
                    ] = name
                try:
                    parsed = _v319_fill_missing_race_nos(
                        parsed, db_path=db_path, player_name=name
                    )
                except Exception:
                    pass

                # ソース df から R を再注入（パーサが落とした場合）
                try:
                    if isinstance(work, pd.DataFrame) and not work.empty and "レース" in parsed.columns:
                        src_map = {}
                        for _, sr in work.iterrows():
                            try:
                                rv = int(pd.to_numeric(sr.get("レース"), errors="coerce") or 0)
                            except Exception:
                                rv = 0
                            if rv <= 0:
                                continue
                            k = (
                                _v319_ymd_digits(sr.get("開催日")),
                                str(sr.get("開催場") or "").replace("　", "").strip(),
                            )
                            src_map[k] = rv
                        for i, pr in parsed.iterrows():
                            try:
                                cur = int(pd.to_numeric(pr.get("レース"), errors="coerce") or 0)
                            except Exception:
                                cur = 0
                            if cur > 0:
                                continue
                            k = (
                                _v319_ymd_digits(pr.get("開催日")),
                                str(pr.get("開催場") or "").replace("　", "").strip(),
                            )
                            if k in src_map:
                                parsed.at[i, "レース"] = int(src_map[k])
                except Exception:
                    pass

                report = engine.v47_save_player_history(parsed, db_path=db_path) or {}
                changed = int(report.get("changed") or report.get("saved") or 0)
                pending_df = report.get("pending")
                pending_left = int(report.get("pending_count") or 0)

                # Ver320 post-fix: パーサが R を拾えなかった行を結果DBから補完
                try:
                    _rno_fix = _v320_backfill_race_no_for_player(db_path, name)
                    if int(_rno_fix.get("race_history") or 0) > 0 or int(_rno_fix.get("v15") or 0) > 0:
                        _ = details.append(
                            f"{name}:race_no補完(rh={_rno_fix.get('race_history', 0)}/v15={_rno_fix.get('v15', 0)})"
                        )
                except Exception as _rno_exc:
                    _ = details.append(f"{name}:race_no補完失敗:{type(_rno_exc).__name__}")

                if isinstance(pending_df, pd.DataFrame) and not pending_df.empty:
                    repaired = pending_df.copy()
                    if "重複処理" not in repaired.columns:
                        repaired["重複処理"] = "入力したRで新規登録"
                    else:
                        need = repaired["重複処理"].fillna("選択してください").astype(str).isin(
                            ["", "選択してください", "nan", "None"]
                        )
                        repaired.loc[need, "重複処理"] = "入力したRで新規登録"
                    repaired["_v58_duplicate_confirmed"] = True
                    try:
                        report2 = engine.v131_save_pending_player_history(
                            repaired, db_path=db_path
                        ) or {}
                        changed += int(
                            report2.get("verified")
                            or report2.get("changed")
                            or report2.get("saved")
                            or 0
                        )
                        pending_left = int(report2.get("pending_count") or 0)
                    except Exception as _pend_exc:
                        _ = details.append(f"{name}:pending失敗:{type(_pend_exc).__name__}")

                if changed <= 0 and len(parsed) >= 5:
                    try:
                        work2 = parsed.copy()
                        work2["重複処理"] = "入力したRで新規登録"
                        work2["_v58_duplicate_confirmed"] = True
                        report3 = engine.v131_save_pending_player_history(
                            work2, db_path=db_path
                        ) or {}
                        changed += int(
                            report3.get("verified")
                            or report3.get("changed")
                            or report3.get("saved")
                            or 0
                        )
                        pending_left = int(report3.get("pending_count") or pending_left or 0)
                    except Exception:
                        pass

                # Ver324: engine 保存直後は player_name_key が NULL のままなので埋めてから件数確認
                if changed > 0:
                    try:
                        _nk = _v319_norm_player_name(name)
                        if _nk and "v15_player_history_imports" in _v319_schema_tables(con):
                            _cols_nk = set(_v319_table_columns_cached(con, "v15_player_history_imports"))
                            if "player_name_key" in _cols_nk:
                                con.execute(
                                    "UPDATE v15_player_history_imports SET player_name_key="
                                    "replace(replace(COALESCE(player_name,''),' ',''),'　','') "
                                    "WHERE COALESCE(player_name_key,'')='' "
                                    "AND replace(replace(COALESCE(player_name,''),' ',''),'　','')=?",
                                    (_nk,),
                                )
                    except Exception:
                        pass
                after = int(_v319_player_history_count(db_path, name, con=con) or 0)
                delta = max(changed, max(0, after - have))
                added += delta
                if need_refresh:
                    _V319_HIST_REFRESHED.add(cache_key)
                # 選手ごとに commit → 取込中でも他画面の読み取りが通りやすい
                try:
                    con.commit()
                except Exception:
                    pass

                # 穴なし確認: 対象日までの最新が埋まり、missing_official が解消された時だけ
                # キャッシュスキップ登録する（次回の無駄な再取得を防ぐ）。
                try:
                    after_state = _v319_player_history_state(db_path, name, con=con) or {}
                    after_keys = set(after_state.get("keys") or set())
                    after_latest = _v319_ymd_digits(str(after_state.get("latest") or ""))
                    _remaining_missing = official_keys - after_keys
                    # 公式穴が解消されていれば対象日キャッシュ（当日でも latest < 対象日でOK）
                    if before_d and not _remaining_missing and after >= min_rows:
                        _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                        if pcd:
                            _v319_persistent_skip_mark(
                                db_path, pcd, before_d, after_latest or before_d, con=con
                            )
                    elif not before_d and after >= min_rows and not _remaining_missing:
                        _V319_HIST_SKIPPED[cache_key] = before_d or "1"
                except Exception:
                    pass

                tag = "穴埋め" if is_existing else ("再取込" if need_refresh else "追加")
                try:
                    r_ok = int(
                        (
                            pd.to_numeric(parsed["レース"], errors="coerce").fillna(0) > 0
                        ).sum()
                    ) if "レース" in parsed.columns else 0
                except Exception:
                    r_ok = 0
                pend_s = f"/未確定{pending_left}" if pending_left else ""
                details.append(
                    f"{name}:{have}→{after}({tag}{len(parsed)}件/R付{r_ok}/保存{changed}{pend_s})"
                )
                time_module.sleep(0.03)
            except Exception as exc:
                errors += 1
                _ = details.append(f"{name}:{type(exc).__name__}:{exc}")
        return {"added": added, "skipped": skipped, "errors": errors, "details": details}
    finally:
        if _own_con:
            try:
                con.commit()
            except Exception:
                pass
            try:
                con.close()
            except Exception:
                pass



def _v319_race_key_candidates(ymd: str, venue: str, race_no: int) -> list[str]:
    ymd = _v319_ymd_digits(ymd)
    ymd_d = f"{ymd[:4]}-{ymd[4:6]}-{ymd[6:]}" if len(ymd) == 8 else ymd
    n = int(race_no)
    return [
        f"{ymd}_{venue}_{n}R",
        f"{ymd_d}_{venue}_{n}R",
        f"{ymd}_{venue}_{n}",
        f"{ymd_d}_{venue}_{n}",
    ]


def _v319_result_exists(db_path: str, ymd: str, venue: str, race_no: int) -> bool:
    keys = _v319_race_key_candidates(ymd, venue, race_no)
    try:
        with sqlite3.connect(str(db_path), timeout=10) as con:
            ph = ",".join("?" * len(keys))
            n = con.execute(
                f"SELECT COUNT(*) FROM result_races WHERE race_key IN ({ph}) "
                "OR (replace(replace(COALESCE(race_date,''),'-',''),'/','')=? AND venue=? AND CAST(race_no AS INTEGER)=?)",
                (*keys, _v319_ymd_digits(ymd), venue, int(race_no)),
            ).fetchone()
            return bool(n and int(n[0] or 0) > 0)
    except Exception:
        return False


def _v319_prediction_exists(db_path: str, race_key: str) -> bool:
    """保存済み予測一覧に出る履歴があるときだけ予測済みとみなす。"""
    try:
        with sqlite3.connect(str(db_path), timeout=10) as con:
            tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            if "v231_prediction_history" in tables:
                keys = [str(race_key)]
                m = re.match(r"(\d{4})-?(\d{2})-?(\d{2})_(.+)_(\d+)R?", str(race_key))
                if m:
                    ymd = f"{m.group(1)}{m.group(2)}{m.group(3)}"
                    keys = _v319_race_key_candidates(ymd, m.group(4), m.group(5))
                ph = ",".join("?" * len(keys))
                n = con.execute(
                    f"SELECT COUNT(*) FROM v231_prediction_history WHERE race_key IN ({ph})",
                    tuple(keys),
                ).fetchone()
                if n and int(n[0] or 0) > 0:
                    return True
            return False
    except Exception:
        return False


def _v319_prediction_entry_count(db_path: str, race_key: str) -> int:
    """保存済み予測の出走台数。不明なら0。"""
    try:
        with sqlite3.connect(str(db_path), timeout=10) as con:
            tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            if "v231_prediction_history" not in tables:
                return 0
            keys = [str(race_key)]
            m = re.match(r"(\d{4})-?(\d{2})-?(\d{2})_(.+)_(\d+)R?", str(race_key))
            if m:
                ymd = f"{m.group(1)}{m.group(2)}{m.group(3)}"
                keys = _v319_race_key_candidates(ymd, m.group(4), m.group(5))
            ph = ",".join("?" * len(keys))
            # 1) snapshot tables
            for snap in (
                "v231_prediction_entry_snapshots",
                "v231_prediction_snapshots",
                "v231_prediction_entry",
            ):
                if snap not in tables:
                    continue
                try:
                    scols = {r[1] for r in con.execute(f"PRAGMA table_info({snap})").fetchall()}
                    car_c = "car_no" if "car_no" in scols else ("車番" if "車番" in scols else None)
                    if not car_c:
                        continue
                    n = con.execute(
                        f"""
                        SELECT COUNT(DISTINCT s.{car_c}) FROM {snap} s
                        JOIN v231_prediction_history h ON h.history_id=s.history_id
                        WHERE h.race_key IN ({ph})
                        """,
                        tuple(keys),
                    ).fetchone()
                    if n and int(n[0] or 0) > 0:
                        return int(n[0])
                except Exception:
                    pass
            cols = {r[1] for r in con.execute("PRAGMA table_info(v231_prediction_history)").fetchall()}
            # 2) blob / json columns
            for col in ("view_blob", "view_json", "payload_json", "payload", "meta_json", "result_blob"):
                if col not in cols:
                    continue
                row = con.execute(
                    f"SELECT {col} FROM v231_prediction_history WHERE race_key IN ({ph}) ORDER BY history_id DESC LIMIT 1",
                    tuple(keys),
                ).fetchone()
                if not row or row[0] is None:
                    continue
                raw = row[0]
                obj = None
                if isinstance(raw, (bytes, bytearray)):
                    for loader in (
                        lambda b: pickle.loads(b),
                        lambda b: json.loads(zlib.decompress(b).decode("utf-8", "replace")),
                        lambda b: json.loads(b.decode("utf-8", "replace")),
                    ):
                        try:
                            obj = loader(raw)
                            break
                        except Exception:
                            continue
                elif isinstance(raw, str):
                    try:
                        obj = json.loads(raw)
                    except Exception:
                        obj = None
                if not isinstance(obj, dict):
                    continue
                for k in ("entries", "df", "finish_prob"):
                    v = obj.get(k)
                    if isinstance(v, pd.DataFrame) and not v.empty:
                        return int(len(v))
                    if isinstance(v, list) and v:
                        return int(len(v))
                    if isinstance(v, dict) and v:
                        return int(len(v))
                meta = obj.get("meta") if isinstance(obj.get("meta"), dict) else obj
                for mk in ("出走数", "実出走数", "予測照合用出走数", "n_cars", "entry_count"):
                    if meta.get(mk) is not None:
                        try:
                            n = int(meta[mk])
                            if n > 0:
                                return n
                        except Exception:
                            pass
                # raw_text から「N車」
                for tk in ("raw_text", "prediction_text", "text"):
                    t = str(obj.get(tk) or "")
                    mm = re.search(r"(\d+)\s*車", t)
                    if mm:
                        return int(mm.group(1))
            # 3) raw_text column on history
            for col in ("raw_text", "prediction_text", "input_text"):
                if col not in cols:
                    continue
                row = con.execute(
                    f"SELECT {col} FROM v231_prediction_history WHERE race_key IN ({ph}) ORDER BY history_id DESC LIMIT 1",
                    tuple(keys),
                ).fetchone()
                if row and row[0]:
                    mm = re.search(r"(\d+)\s*車", str(row[0]))
                    if mm:
                        return int(mm.group(1))
                    # 車番行の最大
                    cars = re.findall(r"(?m)^([1-8])\t", str(row[0]))
                    if cars:
                        return max(int(c) for c in cars)
    except Exception:
        return 0
    return 0


def _v319_clear_prediction(db_path: str, race_key: str) -> None:
    """古い誤予測を消して再予測できるようにする。

    engine の prediction_snapshots も消す。
    v117 の出走数照合は prediction_snapshots を見るため、v231 だけ消すと
    台数不一致が解消されず再登録に失敗する。
    """
    try:
        keys = [str(race_key)]
        m = re.match(r"(\d{4})-?(\d{2})-?(\d{2})_(.+)_(\d+)R?", str(race_key))
        if m:
            ymd = f"{m.group(1)}{m.group(2)}{m.group(3)}"
            keys = _v319_race_key_candidates(ymd, m.group(4), m.group(5))
        with sqlite3.connect(str(db_path), timeout=15) as con:
            tables = {r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            ph = ",".join("?" * len(keys))
            # engine 側（出走数照合の本体）
            for snap in (
                "prediction_snapshots",
                "prediction_feature_snapshots",
                "v40_prediction_feature_snapshots",
                "prediction_races",
            ):
                if snap in tables:
                    try:
                        con.execute(f"DELETE FROM {snap} WHERE race_key IN ({ph})", tuple(keys))
                    except Exception:
                        pass
            # app 側履歴
            if "v231_prediction_history" in tables:
                ids = [r[0] for r in con.execute(
                    f"SELECT history_id FROM v231_prediction_history WHERE race_key IN ({ph})",
                    tuple(keys),
                ).fetchall()]
                for snap in (
                    "v231_prediction_entry_snapshots",
                    "v231_prediction_snapshots",
                    "v231_prediction_entry",
                ):
                    if snap in tables and ids:
                        try:
                            q = ",".join("?" * len(ids))
                            con.execute(f"DELETE FROM {snap} WHERE history_id IN ({q})", tuple(ids))
                        except Exception:
                            pass
                con.execute(
                    f"DELETE FROM v231_prediction_history WHERE race_key IN ({ph})",
                    tuple(keys),
                )
            con.commit()
    except Exception:
        pass



def _v319_run_prerace_prediction(db_path: str, race_key: str, venue: str, trials: int = 20000, seed: int = 20260719, raw_text: str = "", manual_excluded: list | None = None) -> dict:
    """出走表（SP）があればそれを使い、なければ結果のレース前項目だけで予測する。"""
    text = str(raw_text or "").strip()
    audit = {"source": "sprace"} if text else {}
    if not text:
        text, audit = _v304_build_safe_prediction_text_from_result(db_path, race_key)
    if not text:
        return {"ok": False, "reason": str((audit or {}).get("reason") or "再構成失敗")}
    prediction_text = f"開催場: {venue}\n" + text if venue else text
    seed = int(seed if seed is not None else 20260719)
    try:
        if bool(globals().get("use_champion_model", True)):
            engine.v311_set_champion_model_state()
        else:
            engine.v305_clear_model_state_override()
    except Exception:
        pass
    excl = sorted(set(int(x) for x in (manual_excluded or []) if str(x).strip().isdigit() or isinstance(x, int)))
    auto_k = _v319_detect_kessha_from_card_text(prediction_text)
    excl = sorted(set(excl) | set(auto_k))
    df, bets, output, entries, meta = engine.ver16_run_prediction(
        prediction_text, int(trials), int(seed), manual_excluded=excl
    )
    if excl:
        meta = dict(meta or {})
        meta["欠車車番"] = excl
        meta["事前除外車番"] = excl
    entries = _v276_mark_retrial_from_prediction_text(entries, prediction_text)
    df = _v276_copy_retrial_to_prediction_df(df, entries)
    meta = dict(meta or {})
    df, bets, wall_audit = _v230_six_lap_simulation(df, bets, entries, meta, int(trials), int(seed))
    meta["壁補正監査"] = wall_audit
    meta["6周展開シミュレーション"] = wall_audit
    try:
        if isinstance(df, pd.DataFrame) and isinstance(entries, pd.DataFrame) and not entries.empty:
            car_col = "車" if isinstance(df, pd.DataFrame) and "車" in df.columns else "車番"
            have = set()
            if car_col in df.columns:
                have = set(pd.to_numeric(df[car_col], errors="coerce").dropna().astype(int).tolist())
            miss = []
            for _, r in entries.iterrows():
                try:
                    c = int(float(r.get("車番")))
                except Exception:
                    continue
                if c not in have:
                    row = {col: None for col in df.columns}
                    if car_col in row:
                        row[car_col] = c
                    if "車番" in row:
                        row["車番"] = c
                    if "選手名" in row:
                        row["選手名"] = r.get("選手名")
                    _ = miss.append(row)
                    have.add(c)
            if miss:
                df = pd.concat([df, pd.DataFrame(miss)], ignore_index=True)
    except Exception:
        pass
    try:
        engine.v305_clear_model_state_override()
    except Exception:
        pass
    finish_prob = engine.v30_finish_probabilities(df, bets, int(trials))
    df = _v284_apply_simulation_joint_ranks(df, wall_audit)
    km = re.match(r"(\d{8})_(.+)_(\d+)R$", str(race_key or ""))
    if km:
        meta["開催日"] = meta.get("開催日") or f"{km.group(1)[:4]}-{km.group(1)[4:6]}-{km.group(1)[6:8]}"
        meta["開催場"] = meta.get("開催場") or km.group(2)
        meta["レース"] = meta.get("レース") or int(km.group(3))
    if venue:
        meta["開催場"] = meta.get("開催場") or venue
    saved_key = ""
    try:
        saved_key = str(engine.v34_save_prediction_snapshot(meta, df, finish_prob, db_path) or "")
    except Exception:
        saved_key = ""
    key = str(race_key or "").strip() or saved_key
    view = {
        "df": df, "bets": bets, "output": output, "entries": entries, "meta": meta,
        "finish_prob": finish_prob, "race_key": key,
        "trials": int(trials), "excluded": [], "app_version": _V231_APP_VERSION,
        "simulation_mode": _V231_SIMULATION_MODE,
        "prediction_time": _v228_now_jst_iso(), "seed": int(seed),
        "settings_hash": _v231_settings_hash(int(trials), int(seed), []),
    }
    history_id = 0
    save_err = ""
    try:
        history_id = int(_v231_save_prediction_history(db_path, key, text, venue, view, int(trials), int(seed)) or 0)
        _v222_save_prediction_restore(db_path, key, text, venue, view)
    except Exception as exc:
        save_err = f"{type(exc).__name__}: {exc}"
        try:
            slim = {
                "meta": meta, "race_key": key, "trials": int(trials), "seed": int(seed),
                "app_version": _V231_APP_VERSION, "prediction_time": view["prediction_time"],
                "df": df, "bets": bets, "entries": entries, "finish_prob": finish_prob,
            }
            history_id = int(_v231_save_prediction_history(db_path, key, text, venue, slim, int(trials), int(seed)) or 0)
            save_err = ""
        except Exception as exc2:
            save_err = f"{type(exc2).__name__}: {exc2}"
    try:
        _v217_deferred_prediction_db_save(meta, bets, int(trials), df)
    except Exception:
        pass
    if not history_id:
        return {"ok": False, "reason": save_err or "予測履歴の保存に失敗", "race_key": key}
    return {"ok": True, "race_key": key, "trials": int(trials), "history_id": history_id}



def _v319_is_void_or_cancelled_result(text: str) -> dict:
    """レース中止・不成立・全返還を判定。"""
    s = str(text or "")
    flags = {
        "void": False,
        "cancelled": False,
        "no_contest": False,
        "full_refund": False,
        "reason": "",
    }
    if not s.strip():
        return flags
    if re.search(r"レース中止|競走中止|(?:^|\n)\s*中止\s*(?:\n|$)", s):
        flags["cancelled"] = True
        flags["void"] = True
        flags["reason"] = "レース中止"
    if re.search(r"不成立|レース不成立", s):
        flags["no_contest"] = True
        flags["void"] = True
        if not flags["reason"]:
            flags["reason"] = "不成立"
    if re.search(r"全返還", s) or (
        re.search(r"単勝[^\n]{0,30}不成立", s)
        and re.search(r"3連単[^\n]{0,30}不成立", s)
    ):
        flags["full_refund"] = True
        flags["void"] = True
        if not flags["reason"]:
            flags["reason"] = "全返還"
    if re.search(r"着順[^\n]{0,40}\n\s*レース中止", s) or re.search(r"ST/事故\s*\n\s*レース中止", s):
        flags["cancelled"] = True
        flags["void"] = True
        flags["reason"] = flags["reason"] or "レース中止"
    return flags


def _v319_register_void_result(
    db_path: str, raw_text: str, venue: str, ymd: str, race_no: int, reason: str = "レース中止"
) -> dict:
    """中止・不成立・全返還を結果登録（学習対象外）。"""
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    key = f"{ymd}_{venue}_{int(race_no)}R"
    date_s = f"{ymd[:4]}-{ymd[4:6]}-{ymd[6:8]}" if len(ymd) == 8 else str(ymd)
    meta = {
        "開催日": date_s,
        "開催場": venue,
        "レース": int(race_no),
        "レース状態": reason or "レース中止",
        "不成立": True,
        "レース中止": True,
        "全返還": True,
        "学習対象外": True,
        "learning_excluded": True,
        "learning_exclusion_reason": reason or "レース中止・全返還",
        "予測精度評価対象": False,
        "AI学習対象": False,
        "実出走数": 0,
    }
    rows = pd.DataFrame(columns=["着順", "車番", "選手名", "競走T", "ST"])
    laps = pd.DataFrame()
    payout_rows = [
        {"券種": bt, "組み合わせ": "全返還", "払戻金": 100}
        for bt in ("単勝", "複勝", "2連複", "2連単", "ワイド", "3連複", "3連単")
    ]
    payouts = pd.DataFrame(payout_rows)
    try:
        key2, *_rest = engine.v41_register_result(meta, rows, laps, payouts, db_path)
        key = str(key2 or key)
    except Exception:
        try:
            key2, *_rest = engine.v70_replace_registered_result(meta, rows, laps, payouts, db_path)
            key = str(key2 or key)
        except Exception as exc:
            try:
                _v238_save_exact_raw_result(db_path, key, raw_text, source="oddspark_void")
            except Exception:
                pass
            return {"key": key, "ok": False, "error": f"{type(exc).__name__}: {exc}", "void": True}
    try:
        _v238_save_exact_raw_result(db_path, key, raw_text, source="oddspark_void")
    except Exception:
        pass
    return {"key": key, "ok": True, "void": True, "reason": reason}




def _v320_backfill_race_no_for_player(db_path: str, player_name: str = "") -> dict:
    """race_history / v15_player_history_imports の空 race_no を result_races から補完。

    Ver320: engine.v15_parse_player_history が "1R" 単独行を拾えないケースがあるため、
    result_races.race_no を正本として事後 UPDATE する。

    マッチ優先順位（ユニーク時のみ採用、曖昧なら触らない）:
      1) 日付+場+選手+試走T+競走T
      2) 日付+場+選手+試走T
      3) 日付+場+選手（候補が1件だけ）
    """
    out = {"race_history": 0, "v15": 0, "skipped_ambiguous": 0, "errors": []}

    def _norm_name(n: str) -> str:
        return re.sub(r"[\s\u3000]+", "", str(n or ""))

    def _norm_venue(v: str) -> str:
        return str(v or "").strip().replace(" ", "").replace("\u3000", "")

    def _date_digits(d) -> str:
        return re.sub(r"[^0-9]", "", str(d or ""))[:8]

    def _num(v):
        try:
            f = float(v)
            if f != f:  # NaN
                return None
            return f
        except Exception:
            return None

    def _pick_rn(raw) -> str:
        m = re.search(r"(\d{1,2})", str(raw or ""))
        if not m:
            return ""
        n = int(m.group(1))
        return str(n) if 1 <= n <= 12 else ""

    def _lookup_rn(con, rd8: str, venue: str, pname: str, trial_time=None, race_time=None):
        if not rd8 or len(rd8) < 8:
            return ""
        vn = _norm_venue(venue)
        pn = _norm_name(pname)
        if not vn or not pn:
            return ""
        _tt = _num(trial_time)
        _rt = _num(race_time)

        def _query(extra_sql: str, extra_params: tuple):
            sql = (
                "SELECT DISTINCT rr.race_no FROM result_races rr "
                "JOIN result_entries re ON re.race_key = rr.race_key "
                "WHERE replace(replace(replace(COALESCE(rr.race_date,''),'-',''),'/',''),'.','') LIKE ? "
                "  AND replace(replace(COALESCE(rr.venue,''),' ',''),'\u3000','') = ? "
                "  AND replace(replace(COALESCE(re.player_name,''),' ',''),'\u3000','') = ? "
                "  AND rr.race_no IS NOT NULL "
                "  AND TRIM(CAST(rr.race_no AS TEXT)) <> '' "
                + extra_sql
            )
            try:
                rows = con.execute(sql, (rd8 + "%", vn, pn) + tuple(extra_params)).fetchall()
            except Exception:
                return []
            out_set = set()
            for r in rows:
                rn = _pick_rn(r[0] if r else "")
                if rn:
                    out_set.add(rn)
            return sorted(out_set)

        if _tt is not None and _rt is not None:
            c = _query(
                " AND re.trial_time IS NOT NULL AND re.race_time IS NOT NULL"
                " AND ABS(CAST(re.trial_time AS REAL) - ?) < 0.005"
                " AND ABS(CAST(re.race_time AS REAL) - ?) < 0.005",
                (_tt, _rt),
            )
            if len(c) == 1:
                return c[0]
        if _tt is not None:
            c = _query(
                " AND re.trial_time IS NOT NULL"
                " AND ABS(CAST(re.trial_time AS REAL) - ?) < 0.005",
                (_tt,),
            )
            if len(c) == 1:
                return c[0]
        c = _query("", ())
        if len(c) == 1:
            return c[0]
        return ""  # 曖昧 or 不一致 → 触らない

    try:
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            where = "(h.race_no IS NULL OR TRIM(CAST(h.race_no AS TEXT)) = '')"
            params: list = []
            if player_name:
                where += (
                    " AND replace(replace(COALESCE(p.player_name,''),' ',''),'\u3000','') = ?"
                )
                params.append(_norm_name(player_name))
            rows = con.execute(
                f"""
                SELECT h.history_id, h.race_date, h.venue, p.player_name,
                       h.trial_time, h.race_time
                  FROM race_history h
                  JOIN players p ON p.player_id = h.player_id
                 WHERE {where}
                """,
                params,
            ).fetchall()
            for hid, rd, venue, pname, tt, rt in rows:
                rn = _lookup_rn(con, _date_digits(rd), venue, pname, tt, rt)
                if rn:
                    con.execute(
                        "UPDATE race_history SET race_no=? WHERE history_id=?",
                        (rn, int(hid)),
                    )
                    out["race_history"] += 1
                else:
                    out["skipped_ambiguous"] += 1

            try:
                v15_cols = {
                    str(c[1])
                    for c in con.execute(
                        'PRAGMA table_info("v15_player_history_imports")'
                    ).fetchall()
                }
                if "race_no" in v15_cols:
                    key_col = (
                        "history_key"
                        if "history_key" in v15_cols
                        else ("id" if "id" in v15_cols else None)
                    )
                    date_col = (
                        "race_date"
                        if "race_date" in v15_cols
                        else ("開催日" if "開催日" in v15_cols else None)
                    )
                    ven_col = (
                        "venue"
                        if "venue" in v15_cols
                        else ("開催場" if "開催場" in v15_cols else None)
                    )
                    name_col = (
                        "player_name"
                        if "player_name" in v15_cols
                        else ("選手名" if "選手名" in v15_cols else None)
                    )
                    trial_col = (
                        "trial_time"
                        if "trial_time" in v15_cols
                        else ("試走T" if "試走T" in v15_cols else None)
                    )
                    race_col = (
                        "race_time"
                        if "race_time" in v15_cols
                        else ("競走T" if "競走T" in v15_cols else None)
                    )
                    if key_col and date_col and ven_col and name_col:
                        where15 = "COALESCE(CAST(race_no AS TEXT), '') = ''"
                        params15: list = []
                        if player_name:
                            where15 += (
                                f" AND replace(replace(COALESCE({name_col},''),' ',''),'\u3000','') = ?"
                            )
                            params15.append(_norm_name(player_name))
                        sel_tt = trial_col if trial_col else "NULL"
                        sel_rt = race_col if race_col else "NULL"
                        rows15 = con.execute(
                            f"""
                            SELECT {key_col}, {date_col}, {ven_col}, {name_col},
                                   {sel_tt}, {sel_rt}
                              FROM v15_player_history_imports
                             WHERE {where15}
                            """,
                            params15,
                        ).fetchall()
                        for hk, rd, venue, pname, tt, rt in rows15:
                            rn = _lookup_rn(con, _date_digits(rd), venue, pname, tt, rt)
                            if rn:
                                con.execute(
                                    f"UPDATE v15_player_history_imports SET race_no=? WHERE {key_col}=?",
                                    (rn, hk),
                                )
                                out["v15"] += 1
                            else:
                                out["skipped_ambiguous"] += 1
            except Exception as exc15:
                out["errors"].append(f"v15: {type(exc15).__name__}: {exc15}")
            con.commit()
    except Exception as exc:
        out["errors"].append(f"race_history: {type(exc).__name__}: {exc}")
    return out


def _v320_extract_race_no_from_result_text(text: str):
    """結果本文からレース番号を抽出する安全網。

    優先順位:
      1. 先頭付近の 'NR' / '第NR'
      2. 'レース番号: N' など
    取れなければ None。
    """
    s = str(text or "")
    if not s.strip():
        return None
    head = s[:800]
    for m in re.finditer(
        r"(?:^|\n)\s*(?:第\s*)?(\d{1,2})\s*[RrＲ]\s*(?=\n|$|\s|確定|締切)",
        head,
    ):
        try:
            n = int(m.group(1))
        except Exception:
            continue
        if 1 <= n <= 12:
            return n
    m = re.search(r"レース(?:番号)?\s*[:：]?\s*(\d{1,2})", head)
    if m:
        try:
            n = int(m.group(1))
        except Exception:
            n = 0
        if 1 <= n <= 12:
            return n
    return None


def _v320_fill_race_no_in_meta(meta, raw_text: str = "", race_no_hint=None):
    """meta['レース'] が空/不正なら hint または本文から補完する。"""
    meta_out = dict(meta or {})
    try:
        rn = int(meta_out.get("レース") or 0)
    except Exception:
        rn = 0
    if 1 <= rn <= 12:
        return meta_out
    fill = None
    try:
        if race_no_hint is not None and str(race_no_hint).strip():
            fill = int(re.sub(r"[^0-9]", "", str(race_no_hint)) or 0)
    except Exception:
        fill = None
    if not fill or not (1 <= int(fill) <= 12):
        fill = _v320_extract_race_no_from_result_text(raw_text)
    if fill and 1 <= int(fill) <= 12:
        meta_out["レース"] = int(fill)
    return meta_out


def _v319_register_fetched_result(
    db_path: str,
    raw_text: str,
    venue: str,
    replace: bool = False,
    race_no_hint=None,
) -> dict:
    meta_r, rows_r, laps_r, payouts_r = engine.v35_parse_result_text(raw_text, venue, "")
    # Ver320: parser がレース番号を落としても hint/本文から補完
    meta_r = _v320_fill_race_no_in_meta(meta_r, raw_text, race_no_hint=race_no_hint)
    meta_r, rows_r, nonstarter_numbers = _v224_restore_nonstarter_rows(raw_text, meta_r, rows_r)
    # 「/停止」は発走前除外。engine が発走後事故にしていたのをここで矯正。
    meta_r, teishi_cars = _v320_reclassify_teishi_as_kessha(meta_r, rows_r, raw_text)
    extra = _v315_detect_kessha_cars(raw_text, rows_r)
    kessha = sorted(
        set(int(x) for x in (nonstarter_numbers or []))
        | set(extra)
        | set(teishi_cars or [])
    )
    meta_r = dict(meta_r or {})
    if kessha:
        meta_r["欠車車番"] = kessha
        meta_r["事前除外車番"] = kessha
        meta_r["比較対象外車番"] = kessha
        reasons = dict(meta_r.get("事前除外理由") or {})
        for c in (teishi_cars or []):
            reasons.setdefault(str(int(c)), "停止")
        meta_r["事前除外理由"] = reasons
    meta_r, _inc = _v227_detect_poststart_incidents(raw_text, meta_r)
    # 停止だけの「事故」検出は捨てる
    if _inc:
        _inc = [x for x in _inc if "停止" not in str(x.get("理由") or "")]
    # 具体的な発走後事故車が取れないのに engine 側だけが事故フラグを立てている場合は外す
    # （通常レースが「発走後事故」扱いになり学習・履歴更新が止まる誤検知対策）
    if not _inc:
        _cars = meta_r.get("発走後事故車") or meta_r.get("発走後事故車番") or {}
        _has_car = bool(_cars) if isinstance(_cars, dict) else bool(_cars)
        if not _has_car:
            for k in (
                "発走後事故", "事故レース", "事故あり", "レース状態",
                "予測精度評価対象外", "AI学習対象", "学習対象外", "学習除外",
                "選手履歴学習対象", "展開学習対象", "追い抜き相性学習対象",
                "開催場補正学習対象", "壁補正学習対象", "重み更新対象",
                "learning_excluded", "learning_exclusion_reason", "学習除外理由",
                "発走後事故車", "発走後事故車番", "発走後事故理由",
            ):
                if k in meta_r:
                    if k in ("AI学習対象", "選手履歴学習対象", "展開学習対象",
                             "追い抜き相性学習対象", "開催場補正学習対象",
                             "壁補正学習対象", "重み更新対象", "予測精度評価対象"):
                        meta_r[k] = True
                    elif k == "予測精度評価対象外":
                        meta_r[k] = False
                    elif k in ("発走後事故", "事故レース", "事故あり", "学習対象外",
                               "学習除外", "learning_excluded"):
                        meta_r[k] = False
                    elif k == "レース状態":
                        if str(meta_r.get(k) or "") == "発走後事故":
                            meta_r[k] = "通常"
                    else:
                        meta_r.pop(k, None)
    # 反妨等: 結果に必ず残し、着順は数値にする（engineが "-" 行を落とすため）
    try:
        inc_cars = []
        for item in (_inc or []):
            try:
                _ = inc_cars.append((int(item.get("車番")), str(item.get("理由") or "反妨")))
            except Exception:
                pass
        # raw からも再検出（パース漏れ対策）
        for m in re.finditer(
            r"(?:^|\n)\s*-?\s*([1-8])\b[^\n]{0,200}?/(?:\s*)?(反妨|反則|失格|落車|他落|周誤)",
            str(raw_text or ""),
            flags=re.MULTILINE,
        ):
            c = int(m.group(1))
            if c not in {x[0] for x in inc_cars}:
                _ = inc_cars.append((c, m.group(2)))
        if not isinstance(rows_r, pd.DataFrame):
            rows_r = pd.DataFrame(columns=["着順", "車番", "選手名", "競走T", "ST", "事故"])
        for col in ("着順", "車番", "選手名", "競走T", "ST", "事故"):
            if col not in rows_r.columns:
                rows_r[col] = None
        have_cars = set(
            int(x) for x in pd.to_numeric(rows_r["車番"], errors="coerce").dropna().astype(int).tolist()
        )
        # 既存の正常着順の最大
        fin_nums = pd.to_numeric(rows_r["着順"], errors="coerce").dropna()
        next_fin = int(fin_nums.max()) + 1 if len(fin_nums) else 1
        add_rows = []
        for c, reason in inc_cars:
            if c in have_cars:
                mask = pd.to_numeric(rows_r["車番"], errors="coerce") == c
                rows_r.loc[mask, "事故"] = reason
                # 着順が非数なら数値化（照合用）
                cur = rows_r.loc[mask, "着順"]
                for idx in rows_r.loc[mask].index:
                    v = rows_r.at[idx, "着順"]
                    try:
                        if v is None or str(v).strip() in {"", "-", "－", "欠", "nan", "None"}:
                            rows_r.at[idx, "着順"] = int(next_fin)
                            next_fin += 1
                    except Exception:
                        rows_r.at[idx, "着順"] = int(next_fin)
                        next_fin += 1
            else:
                add_rows.append({
                    "着順": int(next_fin),
                    "車番": int(c),
                    "選手名": "",
                    "競走T": 0.0,
                    "ST": 0.0,
                    "事故": reason,
                })
                next_fin += 1
                have_cars.add(c)
        if add_rows:
            rows_r = pd.concat([rows_r, pd.DataFrame(add_rows)], ignore_index=True)
        if inc_cars:
            meta_r["発走後事故"] = True
            meta_r["発走後事故車番"] = sorted({c for c, _ in inc_cars})
            meta_r["学習対象外"] = True
            meta_r["learning_excluded"] = True
            meta_r["learning_exclusion_reason"] = " / ".join(f"{c}番{r}" for c, r in inc_cars)
            meta_r["予測照合用出走数"] = int(len(have_cars))
            meta_r["実出走数"] = int(len(have_cars))
    except Exception:
        pass
    # 反妨車は欠車扱いで落とさない
    rows_for_engine = _v315_drop_kessha_rows(rows_r, kessha)
    if kessha:
        meta_r["実出走数"] = int(len(rows_for_engine))
    if replace:
        key, *_rest = engine.v70_replace_registered_result(
            meta_r, rows_for_engine, laps_r, payouts_r, db_path
        )
    else:
        key, *_rest = engine.v41_register_result(
            meta_r, rows_for_engine, laps_r, payouts_r, db_path
        )
    try:
        _v238_save_exact_raw_result(db_path, str(key), raw_text, source="oddspark_auto")
    except Exception:
        pass
    try:
        _v279_save_player_incident_history(db_path, str(key), meta_r, rows_r, _inc)
    except Exception:
        pass
    try:
        engine.v67_analyze_ticket_result(meta_r, rows_r, db_path)
    except Exception:
        pass
    try:
        _v319_upsert_payouts_from_text(db_path, str(key), raw_text)
    except Exception:
        pass
    try:
        _v187_sync_mixed_feedback(db_path)
    except Exception:
        pass
    # Ver324: 結果登録で生成された選手履歴へ race_no を補完
    # engine 側が race_history.race_no を空で書く経路があるため、
    # 登録直後に result_races を正本として埋める（対象選手のみ）。
    try:
        _names_fix = []
        if isinstance(rows_r, pd.DataFrame) and "選手名" in rows_r.columns:
            _names_fix = [
                str(x).strip()
                for x in rows_r["選手名"].dropna().tolist()
                if str(x).strip() and str(x).strip().lower() != "none"
            ]
        if _names_fix:
            for _pn in dict.fromkeys(_names_fix):  # 順序保持のユニーク
                _v320_backfill_race_no_for_player(db_path, _pn)
        else:
            _v320_backfill_race_no_for_player(db_path, "")
    except Exception:
        pass
    return {"key": str(key), "cars": int(len(rows_for_engine)), "laps": int(len(laps_r) if laps_r is not None else 0)}


def _v319_upsert_payouts_from_text(db_path: str, race_key: str, raw_text: str) -> int:
    if not race_key:
        return 0
    body = str(raw_text or "")
    idx = body.find("払戻金")
    if idx >= 0:
        body = body[idx:]
    rows = []
    kind = ""
    for raw in body.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = re.match(r"^(単勝|複勝|2連複|2連単|ワイド|3連複|3連単)\s+(\S+)\s+([\d,]+)円", line)
        if m:
            kind = m.group(1)
            combo = m.group(2).replace("→", "-").replace(" ", "")
            yen = int(m.group(3).replace(",", ""))
            _ = rows.append((kind, combo, yen))
            continue
        m2 = re.match(r"^(\S+)\s+([\d,]+)円", line)
        if m2 and kind in ("複勝", "ワイド"):
            combo = m2.group(1).replace("→", "-").replace(" ", "")
            yen = int(m2.group(2).replace(",", ""))
            _ = rows.append((kind, combo, yen))
    if not rows:
        return 0
    with sqlite3.connect(str(db_path), timeout=20) as con:
        con.execute("""
            CREATE TABLE IF NOT EXISTS result_payouts (
                race_key TEXT NOT NULL,
                bet_type TEXT NOT NULL,
                combination TEXT NOT NULL,
                payout_yen INTEGER NOT NULL,
                PRIMARY KEY (race_key, bet_type, combination)
            )
        """)
        for kind, combo, yen in rows:
            bt = _v212_norm_bet_type(kind)
            comb = _v187_norm_combo(bt, combo)
            if not comb or yen <= 0:
                continue
            con.execute(
                "INSERT OR REPLACE INTO result_payouts(race_key,bet_type,combination,payout_yen) VALUES (?,?,?,?)",
                (str(race_key), bt, comb, int(yen)),
            )
        con.commit()
    return len(rows)


def _v319_import_official_results(
    db_path: str,
    ymd: str,
    venue: str,
    skip_existing: bool = True,
    replace: bool = False,
    max_races: int = 12,
    predict_if_missing: bool = True,
    trials: int = 20000,
    seed: int = 20260719,
    race_nos: list | None = None,
    fetch_odds: bool = True,
    register_result: bool = True,
) -> dict:
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    place = _V319_OP_PLACE.get(str(venue))
    report = {"ok": 0, "skip": 0, "error": 0, "details": []}
    if not ymd or not place:
        report["error"] = 1
        report["details"].append({"status": "error", "message": "開催日または開催場が不正です"})
        return report
    try:
        _v319_ensure_perf_indexes(db_path)
    except Exception:
        pass
    if race_nos:
        races = [int(x) for x in race_nos if 1 <= int(x) <= 12]
    else:
        races = _v319_ordered_race_nos(ymd, venue, max_races)
    for n in races:
        item = {"venue": venue, "R": n, "status": "", "message": ""}
        try:
            one = _v319_import_one_race(
                db_path, ymd, venue, n,
                skip_existing=skip_existing, replace=replace,
                predict_if_missing=predict_if_missing,
                trials=int(trials), seed=int(seed),
                fetch_odds=bool(fetch_odds),
                register_result=bool(register_result),
            )
            item["status"] = one.get("status") or "ok"
            item["message"] = one.get("message") or ""
            if item["status"] == "skip":
                report["skip"] += 1
            elif item["status"] == "error":
                report["error"] += 1
            else:
                report["ok"] += 1
        except Exception as exc:
            item["status"] = "error"
            item["message"] = f"{type(exc).__name__}: {exc}"
            report["error"] += 1
        report["details"].append(item)
        time_module.sleep(0.35)
    # Ver319改善#3: 全体補正(Ver287)は開催場ごとに実行しない。
    #   呼び出し側が全開催場の取込終了後に1回だけ実行する（二重計算の回避）。
    return report


def _v319_import_player_history_one_race(
    db_path: str, ymd: str, venue: str, race_no: int,
    min_rows: int = 30, on_step=None,
) -> dict:
    """1レース分の「選手履歴だけ」公式取込。

    出走表(SpRaceInfo)から選手名/選手CDを取得し、選手履歴の保存だけを実行する。
    予測・オッズ取得・結果登録は一切行わない。
    """
    def _step(msg: str) -> None:
        if on_step:
            try:
                on_step(str(msg))
            except Exception:
                pass

    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    venue = str(venue or "").strip()
    race_no = int(race_no)
    key_guess = f"{ymd}_{venue}_{race_no}R"

    # --- 1) 出走表から選手を取得（選手履歴には選手名と選手CDが必要） ---
    players = []
    _step("出走表")
    try:
        sp_html = _v319_fetch_sprace_html(ymd, venue, race_no)
        if not str(sp_html or "").strip():
            return {
                "status": "error",
                "phase": "fetch_card",
                "message": f"{venue} {race_no}R：出走表が空です。選手履歴は登録していません。",
                "key": key_guess,
                "next_action": "retry",
            }
        players = _v319_parse_sprace_car_rows(sp_html) or _v319_parse_sprace_players(sp_html)
        if not players:
            return {
                "status": "error",
                "phase": "fetch_card",
                "message": f"{venue} {race_no}R：出走表から選手を取得できませんでした。選手履歴は登録していません。",
                "key": key_guess,
                "next_action": "retry",
            }
    except Exception as exc:
        return {
            "status": "error",
            "phase": "fetch_card",
            "message": (
                f"{venue} {race_no}R：出走表取得に失敗しました。"
                f" 選手履歴は登録していません。"
                f" ({type(exc).__name__}: {exc})"
            ),
            "key": key_guess,
            "next_action": "retry",
        }

    # --- 2) 選手履歴のみ保存（公式PC版/SP版 PlayerDetail → DB） ---
    _step("選手履歴")
    try:
        filled = _v319_fill_player_histories(
            db_path, players, min_rows=int(min_rows or 30),
            before_ymd=ymd, before_venue=venue, before_race=race_no,
        )
    except Exception as exc:
        return {
            "status": "error",
            "phase": "save_player_history",
            "message": (
                f"{venue} {race_no}R：選手履歴登録に失敗しました。"
                f" ({type(exc).__name__}: {exc})"
            ),
            "key": key_guess,
            "player_history_saved": False,
            "added": 0,
            "next_action": "retry",
        }

    added = int(filled.get("added") or 0)
    skipped = int(filled.get("skipped") or 0)
    errors = int(filled.get("errors") or 0)
    detail = " / ".join(str(x) for x in (filled.get("details") or [])[:8])
    hist_msg = f"履歴+{added} / 変化なし{skipped} / エラー{errors}"

    # 履歴が0件の選手が残っていれば error、全員そろえば ok
    missing = []
    _names_chk = [str(p.get("name") or "").strip() for p in players if str(p.get("name") or "").strip()]
    _cnt_map = _v319_player_history_counts_batch(db_path, _names_chk)
    for nm in _names_chk:
        if int(_cnt_map.get(nm) or 0) <= 0:
            _ = missing.append(nm)
    # Ver325: 履歴0件の選手がいるときだけ中止。errors のみは警告付き続行。
    if missing:
        who = ", ".join(missing[:5])
        return {
            "status": "error",
            "phase": "save_player_history",
            "message": (
                f"{venue} {race_no}R：選手履歴が不足しています。不足選手：{who}。"
                f" {hist_msg}" + (f"｜{detail}" if detail else "")
            ),
            "key": key_guess,
            "player_history_saved": bool(added > 0),
            "added": added,
            "next_action": "retry",
            "notify": True,
            "notify_message": f"【履歴失敗】{venue}{race_no}R：{who}の履歴が不足。",
        }

    warn = ""
    if errors > 0:
        warn = f" ⚠取得失敗{errors}件（既存履歴で続行）"
    return {
        "status": "ok",
        "phase": "save_player_history",
        "message": (
            f"{venue} {race_no}R：選手履歴のみ保存しました（{len(players)}人）。"
            f" {hist_msg}{warn}" + (f"｜{detail}" if detail else "")
        ),
        "key": key_guess,
        "player_history_saved": True,
        "added": added,
        "errors": errors,
        "next_action": "done",
        "notify": bool(errors > 0),
        "notify_message": (
            f"【履歴警告】{venue}{race_no}R：取得失敗{errors}件。既存履歴で続行。"
            if errors > 0 else ""
        ),
    }


def _v319_import_player_history_only(
    db_path: str, ymd: str, venue: str, max_races: int = 12,
    min_rows: int = 30, on_step=None,
) -> dict:
    """開催場1つ分、全レースの選手履歴だけを順に登録する。"""
    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    place = _V319_OP_PLACE.get(str(venue))
    report = {"ok": 0, "skip": 0, "error": 0, "added": 0, "details": []}
    if not ymd or not place:
        report["error"] = 1
        report["details"].append({"status": "error", "message": "開催日または開催場が不正です"})
        return report
    try:
        _v319_ensure_perf_indexes(db_path)
    except Exception:
        pass
    races = _v319_ordered_race_nos(ymd, venue, max_races)
    for n in races:
        item = {"venue": venue, "R": n, "status": "", "message": "", "added": 0}
        try:
            one = _v319_import_player_history_one_race(
                db_path, ymd, venue, n, min_rows=int(min_rows or 30), on_step=on_step,
            )
            item["status"] = one.get("status") or "ok"
            item["message"] = one.get("message") or ""
            item["phase"] = one.get("phase") or ""
            item["added"] = int(one.get("added") or 0)
            if one.get("notify_message"):
                item["notify_message"] = one.get("notify_message")
            report["added"] += int(one.get("added") or 0)
            if item["status"] == "skip":
                report["skip"] += 1
            elif item["status"] == "error":
                report["error"] += 1
            else:
                report["ok"] += 1
        except Exception as exc:
            item["status"] = "error"
            item["message"] = f"{type(exc).__name__}: {exc}"
            report["error"] += 1
        report["details"].append(item)
        time_module.sleep(0.35)
    return report


def _v319_bg_history_any_active(db_path: str) -> bool:
    """選手履歴のみ取込が稼働中か。"""
    try:
        _v278_bg_ensure_table(db_path)
        with sqlite3.connect(str(db_path), timeout=30.0) as con:
            con.execute("PRAGMA busy_timeout=30000")
            row = con.execute("""
                SELECT COUNT(*) FROM v278_background_jobs
                WHERE job_type = 'player_history_import'
                  AND status IN ('queued','running','pause_requested','paused','cancel_requested')
            """).fetchone()
        return bool(int(row[0] or 0))
    except Exception:
        return False


def _v319_import_one_race(
    db_path: str, ymd: str, venue: str, race_no: int,
    skip_existing: bool, replace: bool, predict_if_missing: bool, trials: int, seed: int,
    on_step=None,
    fetch_odds: bool = True,
    register_result: bool = True,
    cancel_cb=None,
) -> dict:
    """1レース単位の自動取得。

    順序固定:
      出走表 → 選手履歴 → 予測(+検証) → (任意)オッズ → (任意)結果登録
    履歴失敗時は予測・結果を実行せず failed で返す。
    register_result=True のとき、オッズ未完了なら結果登録しない。
    fetch_odds / register_result で予測のみ・オッズのみも可能。
    """
    def _step(msg: str) -> None:
        if on_step:
            try:
                on_step(str(msg))
            except Exception:
                pass

    def _cancelled() -> bool:
        if not callable(cancel_cb):
            return False
        try:
            return bool(cancel_cb())
        except Exception:
            return False

    ymd = re.sub(r"[^0-9]", "", str(ymd or ""))
    venue = str(venue or "").strip()
    race_no = int(race_no)
    key_guess = f"{ymd}_{venue}_{race_no}R"
    kessha_cars: list[int] = []
    exists = _v319_result_exists(db_path, ymd, venue, race_no)
    card_text = ""
    hist_msg = ""
    pred_msg = ""
    odds_msg = ""
    players = []
    sp_html = ""

    # --- 1) 出走表 ---
    try:
        _step("出走表")
        sp_html = _v319_fetch_sprace_html(ymd, venue, race_no)
        if not str(sp_html or "").strip():
            return {
                "status": "error",
                "phase": "fetch_card",
                "message": f"{venue} {race_no}R：出走表が空です。予測と結果登録は実行していません。",
                "key": key_guess,
                "next_action": "retry",
            }
        players = _v319_parse_sprace_car_rows(sp_html) or _v319_parse_sprace_players(sp_html)
        card_text = _v319_build_prediction_text_from_sprace(sp_html, venue, race_no, ymd)
        kessha_cars = sorted(set(
            _v319_detect_kessha_from_players(players)
            + _v319_detect_kessha_from_card_text(card_text)
        ))
        if not players:
            return {
                "status": "error",
                "phase": "fetch_card",
                "message": f"{venue} {race_no}R：出走表から選手を取得できませんでした。予測と結果登録は実行していません。",
                "key": key_guess,
                "next_action": "retry",
            }
    except Exception as exc:
        return {
            "status": "error",
            "phase": "fetch_card",
            "message": (
                f"{venue} {race_no}R：出走表取得に失敗しました。"
                f" 予測と結果登録は実行していません。"
                f" ({type(exc).__name__}: {exc})"
            ),
            "key": key_guess,
            "next_action": "retry",
        }

    # --- 2) 選手履歴（失敗時は予測しない） ---
    try:
        _step("選手履歴")
        if _cancelled():
            return {
                "status": "cancelled",
                "phase": "save_player_history",
                "message": f"{venue} {race_no}R：中止要求により中断しました。",
                "key": key_guess,
                "next_action": "cancelled",
            }
        filled = _v319_fill_player_histories(
            db_path, players, min_rows=30,
            before_ymd=ymd, before_venue=venue, before_race=race_no,
            cancel_cb=cancel_cb,
        )
        if filled.get("cancelled"):
            return {
                "status": "cancelled",
                "phase": "save_player_history",
                "message": f"{venue} {race_no}R：中止要求により選手履歴取込を中断しました。",
                "key": key_guess,
                "next_action": "cancelled",
            }
        hist_msg = f" / 履歴+{int(filled.get('added') or 0)}"
        err_n = int(filled.get("errors") or 0)
        # Ver325: 履歴0件の選手がいるときだけ予測中止。errors のみは警告付きで続行。
        missing = []
        _names_chk = [str(p.get("name") or "").strip() for p in players if str(p.get("name") or "").strip()]
        _cnt_map = _v319_player_history_counts_batch(db_path, _names_chk)
        for nm in _names_chk:
            if int(_cnt_map.get(nm) or 0) <= 0:
                _ = missing.append(nm)
        if missing:
            detail = " / ".join(str(x) for x in (filled.get("details") or [])[:8])
            who = ", ".join(missing[:5])
            return {
                "status": "error",
                "phase": "save_player_history",
                "message": (
                    f"{venue} {race_no}R：選手履歴が不完全なため予測・結果登録を中止しました。"
                    f" 不足選手：{who}。"
                    f" 失敗段階：選手履歴保存"
                    f"{hist_msg}"
                    + (f"｜{detail}" if detail else "")
                ),
                "key": key_guess,
                "player_history_saved": False,
                "next_action": "retry",
                "notify": True,
                "notify_message": (
                    f"【履歴失敗】{venue}{race_no}R：{who}の履歴が不足。"
                    f" 予測は実行していません。"
                ),
            }
        # errors のみ: メッセージに残し、予測は続行
        if err_n > 0:
            hist_msg += f" ⚠取得失敗{err_n}件（既存履歴で予測続行）"
    except Exception as exc:
        return {
            "status": "error",
            "phase": "save_player_history",
            "message": (
                f"{venue} {race_no}R：選手履歴登録に失敗しました。"
                f" 予測と結果登録は実行していません。"
                f" ({type(exc).__name__}: {exc})"
            ),
            "key": key_guess,
            "player_history_saved": False,
            "next_action": "retry",
        }

    # --- 3) 予測（未保存時）＋出走数不一致なら再予測 ---
    pred_ok = _v319_prediction_exists(db_path, key_guess)
    card_n = len(players or [])
    if not card_n and card_text:
        mm = re.search(r"(\d+)\s*車", str(card_text))
        if mm:
            card_n = int(mm.group(1))
    if pred_ok and card_n > 0:
        pred_n = _v319_prediction_entry_count(db_path, key_guess)
        # 台数が取れた不一致、または台数不明でも出走表の最大車番と食い違う可能性に備えて
        # 「車」表記と players 件数で判定
        if pred_n > 0 and pred_n != card_n:
            try:
                _v319_clear_prediction(db_path, key_guess)
            except Exception:
                pass
            pred_ok = False
            pred_msg = f" / 予測台数不一致{pred_n}→{card_n}で再予測"
        elif pred_n <= 0:
            # 台数不明の古い予測は信用せず、カードがあるなら再予測
            try:
                _v319_clear_prediction(db_path, key_guess)
            except Exception:
                pass
            pred_ok = False
            pred_msg = f" / 予測台数不明のため再予測({card_n}車)"
    if predict_if_missing and not pred_ok:
        _step("予測中")
        try:
            if not str(card_text or "").strip():
                card_text = _v319_build_prediction_text_from_sprace(sp_html, venue, race_no, ymd)
            pred = _v319_run_prerace_prediction(db_path, key_guess, venue, trials=int(trials), seed=int(seed), raw_text=card_text, manual_excluded=kessha_cars)
            if not pred.get("ok"):
                return {
                    "status": "error",
                    "phase": "run_prediction",
                    "message": (
                        f"{venue} {race_no}R：予測に失敗しました。"
                        f" オッズ入力と結果登録は実行していません。"
                        f" ({pred.get('reason') or '不明'})"
                        f"{hist_msg}"
                    ),
                    "key": key_guess,
                    "player_history_saved": True,
                    "next_action": "retry",
                }
            if not _v319_prediction_exists(db_path, key_guess):
                return {
                    "status": "error",
                    "phase": "verify_prediction",
                    "message": (
                        f"{venue} {race_no}R：予測履歴が保存後に確認できません。"
                        f" オッズ入力と結果登録は実行していません。"
                        f"{hist_msg}"
                    ),
                    "key": key_guess,
                    "player_history_saved": True,
                    "next_action": "retry",
                }
            pred_ok = True
            pred_msg = f" / 予測OK 履歴{pred.get('history_id') or ''}"
        except Exception as exc:
            return {
                "status": "error",
                "phase": "run_prediction",
                "message": (
                    f"{venue} {race_no}R：予測に失敗しました。"
                    f" オッズ入力と結果登録は実行していません。"
                    f" ({type(exc).__name__}: {exc})"
                    f"{hist_msg}"
                ),
                "key": key_guess,
                "player_history_saved": True,
                "next_action": "retry",
            }
    elif pred_ok:
        pred_msg = " / 予測済"

    if not _v319_prediction_exists(db_path, key_guess):
        return {
            "status": "error",
            "phase": "verify_prediction",
            "message": (
                f"{venue} {race_no}R：予測未登録のため結果登録を禁止します。"
                f"{hist_msg}{pred_msg}"
            ),
            "key": key_guess,
            "player_history_saved": True,
            "next_action": "retry",
        }

    # --- 予測のみで終了 ---
    if not fetch_odds and not register_result:
        return {
            "status": "ok",
            "phase": "completed_prediction_only",
            "message": key_guess + hist_msg + pred_msg + " / 予測のみ（オッズ・結果は未実行）",
            "key": key_guess,
            "player_history_saved": True,
        }

    # --- 4) オッズ（任意。結果登録時は必須） ---
    if not fetch_odds:
        odds_msg = " / オッズ取得スキップ"
        if register_result:
            # 既存オッズがあれば続行可能か確認
            try:
                _exist_odds, _ = _v221_load_odds_snapshot(db_path, key_guess)
                _n_ex = sum(len(v) for v in (_exist_odds or {}).values()) if isinstance(_exist_odds, dict) else 0
            except Exception:
                _n_ex = 0
            if _n_ex <= 0:
                return {
                    "status": "error",
                    "phase": "save_odds",
                    "message": (
                        f"{venue} {race_no}R：結果登録にはオッズが必要です（取得スキップかつ未保存）。"
                        f"{hist_msg}{pred_msg}"
                    ),
                    "key": key_guess,
                    "player_history_saved": True,
                    "next_action": "retry",
                }
            odds_msg += f"（既存{_n_ex}件）"
        else:
            return {
                "status": "ok",
                "phase": "completed_no_odds",
                "message": key_guess + hist_msg + pred_msg + odds_msg,
                "key": key_guess,
                "player_history_saved": True,
            }
    else:
        _step("オッズ")
    void_peek_raw = ""
    if fetch_odds:
        try:
            applied = _v319_apply_odds_and_plan(db_path, ymd, venue, race_no, key_guess)
            odds_n = int(applied.get("odds") or 0)
            odds_msg = f" / オッズ{odds_n}件"
            if applied.get("plan_hash"):
                odds_msg += " / 回収率プラン保存"
            elif applied.get("plan_error"):
                odds_msg += f" / プラン生成スキップ({applied.get('plan_error')})"
            void_peek_raw = ""
            if odds_n <= 0:
                try:
                    void_peek_raw = _v319_fetch_oddspark_result(ymd, venue, race_no)
                except Exception:
                    void_peek_raw = ""
                void_info = _v319_is_void_or_cancelled_result(void_peek_raw)
                if void_info.get("void"):
                    odds_msg += f" / オッズなし({void_info.get('reason') or '中止'})"
                else:
                    return {
                        "status": "error",
                        "phase": "save_odds",
                        "message": (
                            f"{venue} {race_no}R：オッズ未登録のため結果登録を禁止します。"
                            f"{hist_msg}{pred_msg}{odds_msg}"
                        ),
                        "key": key_guess,
                        "player_history_saved": True,
                        "next_action": "retry",
                    }
        except Exception as exc:
            try:
                void_peek_raw = _v319_fetch_oddspark_result(ymd, venue, race_no)
            except Exception:
                void_peek_raw = ""
            void_info = _v319_is_void_or_cancelled_result(void_peek_raw)
            if not void_info.get("void"):
                try:
                    place = _V319_OP_PLACE.get(str(venue))
                    ymd8 = re.sub(r"[^0-9]", "", str(ymd or ""))
                    url = (
                        "https://www.oddspark.com/autorace/RaceResult.do"
                        f"?raceDy={ymd8}&placeCd={place}&raceNo={int(race_no)}"
                    )
                    html_raw = _v319_http_get(url)
                    void_info = _v319_is_void_or_cancelled_result(html_raw)
                    if void_info.get("void") and not void_peek_raw:
                        void_peek_raw = f"{int(race_no)}R\n{void_info.get('reason') or '不成立'}\n不成立\n払戻金\n"
                except Exception:
                    pass
            if void_info.get("void"):
                odds_msg = f" / オッズ取得失敗→{void_info.get('reason') or '中止'}"
            else:
                return {
                    "status": "error",
                    "phase": "save_odds",
                    "message": (
                        f"{venue} {race_no}R：オッズ取得に失敗しました。"
                        f" 結果登録は実行していません。"
                        f" ({type(exc).__name__}: {exc})"
                        f"{hist_msg}{pred_msg}"
                    ),
                    "key": key_guess,
                    "player_history_saved": True,
                    "next_action": "retry",
                }

    # --- オッズのみで終了 ---
    if not register_result:
        return {
            "status": "ok",
            "phase": "completed_odds_only" if fetch_odds else "completed_prediction_only",
            "message": key_guess + hist_msg + pred_msg + odds_msg + " / 結果登録スキップ",
            "key": key_guess,
            "player_history_saved": True,
        }

    # --- 5) 結果登録（登録済みスキップは払戻補完のみ） ---
    if exists and skip_existing and not replace:
        try:
            raw_pay = _v319_fetch_oddspark_result(ymd, venue, race_no)
            _v319_upsert_payouts_from_text(db_path, key_guess, raw_pay)
        except Exception as exc:
            odds_msg += f" / 払戻補完失敗:{type(exc).__name__}"
        return {
            "status": "skip",
            "phase": "completed",
            "message": "登録済み" + hist_msg + pred_msg + odds_msg,
            "key": key_guess,
        }

    _step("結果登録")
    raw = str(void_peek_raw or "")
    if not raw:
        try:
            raw = _v319_fetch_oddspark_result(ymd, venue, race_no)
        except Exception as exc:
            return {
                "status": "error",
                "phase": "fetch_result",
                "message": (
                    f"{venue} {race_no}R：結果ページ取得に失敗しました。"
                    f" ({type(exc).__name__}: {exc})"
                    f"{hist_msg}{pred_msg}{odds_msg}"
                ),
                "key": key_guess,
                "next_action": "retry",
            }
    raw_s = str(raw or "")
    void_info = _v319_is_void_or_cancelled_result(raw_s)
    if void_info.get("void"):
        try:
            saved = _v319_register_void_result(
                db_path, raw_s, venue, ymd, race_no,
                reason=str(void_info.get("reason") or "レース中止"),
            )
        except Exception as exc:
            return {
                "status": "error",
                "phase": "save_result",
                "message": (
                    f"{venue} {race_no}R：中止・不成立の結果登録に失敗しました。"
                    f" ({type(exc).__name__}: {exc})"
                    f"{hist_msg}{pred_msg}{odds_msg}"
                ),
                "key": key_guess,
                "next_action": "retry",
            }
        return {
            "status": "ok",
            "phase": "completed_void",
            "message": (
                f"{key_guess} / {void_info.get('reason') or 'レース中止・全返還'}"
                f"{hist_msg}{pred_msg}{odds_msg}"
            ),
            "key": str((saved or {}).get("key") or key_guess),
            "void": True,
        }
    if "着" not in raw_s and "払戻" not in raw_s:
        return {
            "status": "skip",
            "phase": "fetch_result",
            "message": "結果なし" + hist_msg + pred_msg + odds_msg,
            "key": key_guess,
        }
    try:
        saved = _v319_register_fetched_result(db_path, raw, venue, replace=bool(exists and replace), race_no_hint=int(race_no))
    except Exception as exc:
        emsg = f"{type(exc).__name__}: {exc}"
        # 予測と結果の台数/車番不一致 → 反妨補完 or 再予測 or 予測クリア後の強制登録
        if ("出走数が一致しない" in emsg) or ("結果にない車番" in emsg) or ("予測にない車番" in emsg) or ("予測=" in emsg and "結果=" in emsg):
            try:
                _inc_try = _v227_detect_poststart_incidents(str(raw or ""), {})
                inc_list = _inc_try[1] if isinstance(_inc_try, tuple) and len(_inc_try) > 1 else []
                missing_m = re.search(r"結果にない車番=([0-9,\s]+)", emsg)
                extra_m = re.search(r"予測にない車番=([0-9,\s]+)", emsg)
                missing_cars = [int(x) for x in re.findall(r"\d+", missing_m.group(1))] if missing_m else []
                extra_cars = [int(x) for x in re.findall(r"\d+", extra_m.group(1))] if extra_m else []
                inc_cars = []
                for it in (inc_list or []):
                    try:
                        _ = inc_cars.append(int(it.get("車番")))
                    except Exception:
                        pass

                def _force_register_without_prediction(reason: str):
                    """照合不能な古い予測を消して結果だけ保存する。"""
                    nonlocal pred_msg
                    _step("台数不一致→予測クリアして結果保存")
                    try:
                        _v319_clear_prediction(db_path, key_guess)
                    except Exception:
                        pass
                    pred_msg += f" / {reason}"
                    return _v319_register_fetched_result(db_path, raw, venue, replace=True, race_no_hint=int(race_no))

                if missing_cars and inc_cars and set(missing_cars).issubset(set(inc_cars)):
                    _step("反妨台数→結果補完")
                    pred_msg += " / 反妨車を結果に補完"
                    saved = _v319_register_fetched_result(db_path, raw, venue, replace=True, race_no_hint=int(race_no))
                else:
                    _step("台数不一致→再予測")
                    if not str(card_text or "").strip():
                        card_text = _v319_build_prediction_text_from_sprace(sp_html, venue, race_no, ymd)
                    excl = [c for c in (kessha_cars or []) if int(c) not in set(extra_cars or [])]
                    try:
                        _v319_clear_prediction(db_path, key_guess)
                    except Exception:
                        pass
                    pred = _v319_run_prerace_prediction(
                        db_path, key_guess, venue,
                        trials=int(trials), seed=int(seed),
                        raw_text=card_text, manual_excluded=excl,
                    )
                    if pred.get("ok"):
                        pred_msg += " / 結果前に再予測"
                        try:
                            saved = _v319_register_fetched_result(db_path, raw, venue, replace=True, race_no_hint=int(race_no))
                        except Exception as exc_retry:
                            saved = _force_register_without_prediction(
                                f"再予測後も不一致のため予測削除して結果保存({type(exc_retry).__name__})"
                            )
                    else:
                        saved = _force_register_without_prediction(
                            f"再予測失敗のため予測削除して結果保存({pred.get('reason') or '不明'})"
                        )
            except Exception as exc2:
                try:
                    _v319_clear_prediction(db_path, key_guess)
                    saved = _v319_register_fetched_result(db_path, raw, venue, replace=True, race_no_hint=int(race_no))
                    pred_msg += f" / 例外後に予測削除して結果保存({type(exc2).__name__})"
                except Exception as exc3:
                    return {
                        "status": "error",
                        "phase": "save_result",
                        "message": (
                            f"{venue} {race_no}R：結果登録に失敗しました。"
                            f" ({emsg}｜再予測後:{type(exc2).__name__}: {exc2}｜強制:{type(exc3).__name__}: {exc3})"
                            f"{hist_msg}{pred_msg}{odds_msg}"
                        ),
                        "key": key_guess,
                        "next_action": "retry",
                    }
        else:
            return {
                "status": "error",
                "phase": "save_result",
                "message": (
                    f"{venue} {race_no}R：結果登録に失敗しました。"
                    f" ({emsg})"
                    f"{hist_msg}{pred_msg}{odds_msg}"
                ),
                "key": key_guess,
                "next_action": "retry",
            }
    key = str(saved.get("key") or key_guess)
    if not _v319_result_exists(db_path, ymd, venue, race_no):
        return {
            "status": "error",
            "phase": "verify_complete",
            "message": (
                f"{venue} {race_no}R：結果保存後に確認できません。"
                f"{hist_msg}{pred_msg}{odds_msg}"
            ),
            "key": key,
            "next_action": "retry",
        }
    # Ver324: 取込完了時にも対象選手の race_no を補完（register側の保険）
    try:
        _names_fix = [
            str(p.get("name") or "").strip()
            for p in (players or [])
            if str(p.get("name") or "").strip()
        ]
        for _pn in dict.fromkeys(_names_fix):
            _v320_backfill_race_no_for_player(db_path, _pn)
    except Exception:
        pass
    return {
        "status": "ok",
        "phase": "completed",
        "message": key + hist_msg + pred_msg + odds_msg,
        "key": key,
    }



def _v319_bg_import_worker(db_path: str, job_id: int, req: dict) -> None:
    details = []
    ok = skip = err = 0
    try:
        try:
            _v278_bg_update(
                db_path, job_id,
                result_blob=zlib.compress(pickle.dumps({"req": req, "details": []}, protocol=4), 6),
            )
        except Exception:
            pass
        _v278_bg_update(
            db_path, job_id, status="running",
            started_at=_v228_now_jst_iso(),
            current_label="開催確認",
            message="対象レースを数えています",
        )
        try:
            _v319_ensure_perf_indexes(db_path)
        except Exception:
            pass
        _V287_IMPORT_STATE_RESET.clear()
        _V287_IMPORT_STATE_RESET.update(_v287_calibration_state(db_path))
        _V287_AUTO_IMPORT_STATE.clear()
        _V287_AUTO_IMPORT_STATE.update(_V287_IMPORT_STATE_RESET)
        ymd = str(req.get("ymd") or "")
        venues = list(req.get("venues") or [])
        _only_races = [int(x) for x in (req.get("race_nos") or []) if str(x).isdigit() and 1 <= int(x) <= 12]
        targets = []
        seen = set()
        for vn in venues:
            _rns = _only_races if _only_races else _v319_ordered_race_nos(ymd, vn, int(req.get("max_races") or 12))
            for n in _rns:
                item = (str(vn), int(n))
                if item in seen:
                    continue
                seen.add(item)
                _ = targets.append(item)
        total = len(targets)
        _v319_wx_reset_budget()
        _v278_bg_update(db_path, job_id, total_count=total, current_label=f"{total}R 見つかりました")
        for i, (vn, n) in enumerate(targets, 1):
            _v278_bg_pause_loop(db_path, job_id)
            if _v278_bg_cancel_requested(db_path, job_id):
                blob = zlib.compress(pickle.dumps({
                    "ok": ok, "skip": skip, "error": err, "details": details,
                    "cancelled": True,
                    "summary": f"中止｜完了{ok} / スキップ{skip} / 失敗{err}（{i-1}/{total}まで）",
                }, protocol=4), 6)
                try:
                    _v278_cancel_flag_clear(job_id)
                except Exception:
                    pass
                _v278_bg_update(
                    db_path, job_id, status="cancelled",
                    finished_at=_v228_now_jst_iso(),
                    done_count=max(0, i - 1),
                    current_label="中止",
                    message=f"今：中止｜{i-1}/{total}まで処理して中止｜登録{ok} スキップ{skip} エラー{err}",
                    result_blob=blob,
                )
                return
            _v278_bg_update(
                db_path, job_id,
                current_label=f"{vn} {n}R",
                message=f"{i-1}/{total} 完了｜今は取得と登録",
                done_count=i - 1,
            )
            item = {"venue": vn, "R": n, "status": "", "message": ""}
            try:
                one = _v319_import_one_race(
                    db_path, ymd, vn, n,
                    skip_existing=bool(req.get("skip_existing")),
                    replace=bool(req.get("replace")),
                    predict_if_missing=bool(req.get("predict_if_missing")),
                    trials=int(req.get("trials") or 20000),
                    seed=int(req.get("seed") or 20260719),
                    fetch_odds=bool(req.get("fetch_odds", True)),
                    register_result=bool(req.get("register_result", True)),
                    cancel_cb=lambda: _v278_bg_cancel_requested(db_path, job_id),
                    on_step=lambda msg, vn=vn, n=n, i=i, total=total: _v278_bg_update(
                        db_path, job_id,
                        current_label=f"{vn} {n}R",
                        message=f"{i-1}/{total} 完了｜今は{msg}",
                        done_count=i - 1,
                    ),
                )
                if str(one.get("status") or "") == "cancelled":
                    details.append({
                        "venue": vn, "R": n, "status": "cancelled",
                        "message": one.get("message") or "中止",
                        "phase": one.get("phase") or "",
                    })
                    blob = zlib.compress(pickle.dumps({
                        "ok": ok, "skip": skip, "error": err, "details": details,
                        "cancelled": True,
                        "summary": f"中止｜完了{ok} / スキップ{skip} / 失敗{err}（{i-1}/{total}まで）",
                    }, protocol=4), 6)
                    try:
                        _v278_cancel_flag_clear(job_id)
                    except Exception:
                        pass
                    _v278_bg_update(
                        db_path, job_id, status="cancelled",
                        finished_at=_v228_now_jst_iso(),
                        done_count=max(0, i - 1),
                        current_label="中止",
                        message=f"今：中止｜{i-1}/{total}まで処理して中止｜登録{ok} スキップ{skip} エラー{err}",
                        result_blob=blob,
                    )
                    return
                item["status"] = one.get("status") or "ok"
                item["message"] = one.get("message") or ""
                item["phase"] = one.get("phase") or ""
                if one.get("notify_message"):
                    item["notify_message"] = one.get("notify_message")
                st_one = str(item["status"] or "")
                if st_one == "skip":
                    skip += 1
                elif st_one in ("error", "failed"):
                    err += 1
                else:
                    ok += 1
            except Exception as exc:
                item["status"] = "error"
                item["phase"] = "exception"
                item["message"] = f"{type(exc).__name__}: {exc}"
                err += 1
            _ = details.append(item)
            fail_hint = ""
            if str(item.get("status") or "") in ("error", "failed"):
                fail_hint = f"｜失敗:{vn}{n}R"
            # 1レース完了ごとに途中結果を保存（中止・途中でもUIから見られる）
            mid_blob = zlib.compress(pickle.dumps({
                "ok": ok, "skip": skip, "error": err, "details": list(details),
                "partial": True,
                "summary": f"途中経過 {i}/{total}｜登録{ok} スキップ{skip} エラー{err}",
            }, protocol=4), 6)
            _v278_bg_update(
                db_path, job_id,
                done_count=i,
                current_label=f"{vn} {n}R {item['status']}",
                message=f"{i}/{total}｜登録{ok} スキップ{skip} エラー{err}{fail_hint}",
                result_blob=mid_blob,
            )
            time_module.sleep(0.2)
        _v287_recalc_result = {}
        try:
            _v287_recalc_result = _v287_recalculate_global_transition_calibration(
                db_path, force_full=bool(_v287_calibration_needs_full(db_path))
            ) or {}
        except Exception as _v287_exc:
            _v287_recalc_result = {"ok": False, "mode": "?", "calibrations": 0,
                                   "reason": "%s: %s" % (type(_v287_exc).__name__, _v287_exc)}
        _recalc_suffix = ""
        try:
            _recalc_suffix = "｜全体補正" + ("更新" if _v287_recalc_result.get("ok") else "失敗") \
                + "(%s,%s件)" % (str(_v287_recalc_result.get("mode") or "?"),
                                 int(_v287_recalc_result.get("calibrations") or 0))
            if not _v287_recalc_result.get("ok") and _v287_recalc_result.get("reason"):
                _recalc_suffix += "(%s)" % str(_v287_recalc_result.get("reason"))[:60]
        except Exception:
            _recalc_suffix = ""
        failed_keys = [
            f"{d.get('venue','')}{d.get('R','')}R"
            for d in details
            if str(d.get("status") or "") in ("error", "failed")
        ]
        fail_summary = ("｜失敗: " + ", ".join(failed_keys[:8])) if failed_keys else ""
        blob = zlib.compress(pickle.dumps({
            "ok": ok, "skip": skip, "error": err, "details": details,
            "failed_keys": failed_keys,
            "summary": f"自動取得が完了しました。完了：{ok}R / スキップ：{skip}R / 失敗：{err}R",
        }, protocol=4), 6)
        # 完了時: 先に通知、GitHubは軽量保存（リモート全取得なし）
        # 重い統合保存はメモリ不足でアプリ落ちの原因になるため自動取込では使わない
        gh_msg = ""
        try:
            topic = str(__import__("os").environ.get("AUTORACE_NTFY_TOPIC", "notify") or "notify").strip()
            body = (
                f"自動取得完了 {ymd}\n"
                f"完了{ok} / スキップ{skip} / 失敗{err}{fail_summary}\n"
                f"GitHub軽量保存を開始します"
            )
            payload = {
                "topic": topic,
                "title": "AutoRaceAI 自動取得完了",
                "message": body,
                "priority": 4,
                "tags": ["white_check_mark"],
            }
            req = urllib.request.Request(
                "https://ntfy.sh",
                data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
                method="POST",
                headers={"Content-Type": "application/json; charset=utf-8"},
            )
            with urllib.request.urlopen(req, timeout=8) as resp:
                resp.read()
        except Exception:
            pass
        try:
            db_sz = 0
            try:
                db_sz = int(Path(str(db_path)).stat().st_size)
            except Exception:
                db_sz = 0
            # Ver324: 自動取得完了後のGitHub保存はしない（落ちやすい・手動へ）
            gh_msg = "｜GitHubは手動保存へ"
            try:
                _v278_bg_update(
                    db_path, job_id,
                    current_label="完了",
                    message=f"自動取得完了｜GitHubはサイドバーから手動保存｜完了{ok}/失敗{err}",
                )
            except Exception:
                pass
        except Exception as _gh_exc:
            gh_msg = f"｜GitHub例外:{type(_gh_exc).__name__}（手動保存してください）"
        _v278_bg_update(
            db_path, job_id,
            status="completed",
            finished_at=_v228_now_jst_iso(),
            done_count=total,
            current_label="完了",
            message=f"自動取得完了｜完了{ok} / スキップ{skip} / 失敗{err}{fail_summary}{gh_msg}{_recalc_suffix}",
            result_blob=blob,
        )
    except Exception as exc:
        _v278_bg_update(
            db_path, job_id,
            status="failed",
            finished_at=_v228_now_jst_iso(),
            error_text=f"{type(exc).__name__}: {exc}",
            message=f"失敗: {exc}",
        )
    finally:
        try:
            with _V278_BG_LOCK:
                _V278_BG_THREADS.pop(int(job_id), None)
        except Exception:
            pass


def _v319_bg_import_start(
    db_path: str, ymd: str, venues: list[str],
    skip_existing: bool, replace: bool, predict_if_missing: bool,
    trials: int, seed: int,
    race_nos: list | None = None,
    fetch_odds: bool = True,
    register_result: bool = True,
) -> dict:
    _v278_bg_ensure_table(db_path)
    if _v279_bg_prediction_any_active(db_path):
        return {"ok": False, "reason": "別の予測・再シミュレーション・取込が動いています。完了後に開始してください。"}
    if not venues:
        return {"ok": False, "reason": "開催場がありません。"}
    now = _v228_now_jst_iso()
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        cur = con.execute("""
            INSERT INTO v278_background_jobs(
                job_type,app_version,status,created_at,updated_at,limit_count,force_current,
                done_count,total_count,current_label,message
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?)
        """, (
            "official_import", str(_V231_APP_VERSION), "queued", now, now, len(venues), 0,
            0, 0, "準備中", f"{ymd} {','.join(venues)} をバックグラウンド取込します",
        ))
        con.commit()
        job_id = int(cur.lastrowid or 0)
    req = {
        "ymd": ymd, "venues": list(venues),
        "skip_existing": bool(skip_existing), "replace": bool(replace),
        "predict_if_missing": bool(predict_if_missing),
        "trials": int(trials), "seed": int(seed), "max_races": 12,
        "race_nos": [int(x) for x in (race_nos or []) if str(x).isdigit() and 1 <= int(x) <= 12],
        "fetch_odds": bool(fetch_odds),
        "register_result": bool(register_result),
    }
    th = threading.Thread(
        target=_v319_bg_import_worker, args=(str(db_path), job_id, req),
        daemon=True, name=f"autorace-bg-import-{job_id}",
    )
    with _V278_BG_LOCK:
        _V278_BG_THREADS[job_id] = th
    th.start()
    return {"ok": True, "job_id": job_id}


def _v319_bg_history_worker(db_path: str, job_id: int, req: dict) -> None:
    """選手履歴のみのバックグラウンド取込。予測・オッズ・結果登録は行わない。"""
    details = []
    ok = skip = err = added = 0
    try:
        try:
            _v278_bg_update(
                db_path, job_id,
                result_blob=zlib.compress(pickle.dumps({"req": req, "details": []}, protocol=4), 6),
            )
        except Exception:
            pass
        _v278_bg_update(
            db_path, job_id, status="running",
            started_at=_v228_now_jst_iso(),
            current_label="開催確認",
            message="対象レースを数えています（選手履歴のみ）",
        )
        try:
            _v319_ensure_perf_indexes(db_path)
        except Exception:
            pass
        _V287_IMPORT_STATE_RESET.clear()
        _V287_IMPORT_STATE_RESET.update(_v287_calibration_state(db_path))
        _V287_AUTO_IMPORT_STATE.clear()
        _V287_AUTO_IMPORT_STATE.update(_V287_IMPORT_STATE_RESET)
        ymd = str(req.get("ymd") or "")
        venues = list(req.get("venues") or [])
        min_rows = int(req.get("min_rows") or 30)
        targets = []
        seen = set()
        for vn in venues:
            for n in _v319_ordered_race_nos(ymd, vn, int(req.get("max_races") or 12)):
                item = (str(vn), int(n))
                if item in seen:
                    continue
                seen.add(item)
                _ = targets.append(item)
        total = len(targets)
        _v319_wx_reset_budget()
        _v278_bg_update(db_path, job_id, total_count=total, current_label=f"{total}R 見つかりました")
        for i, (vn, n) in enumerate(targets, 1):
            _v278_bg_pause_loop(db_path, job_id)
            if _v278_bg_cancel_requested(db_path, job_id):
                blob = zlib.compress(pickle.dumps({
                    "ok": ok, "skip": skip, "error": err, "added": added, "details": details,
                    "cancelled": True,
                    "summary": (
                        f"中止｜履歴登録{ok}R / 変化なし{skip}R / 失敗{err}R"
                        f" / 履歴+{added}件（{i-1}/{total}まで）"
                    ),
                }, protocol=4), 6)
                try:
                    _v278_cancel_flag_clear(job_id)
                except Exception:
                    pass
                _v278_bg_update(
                    db_path, job_id, status="cancelled",
                    finished_at=_v228_now_jst_iso(),
                    done_count=max(0, i - 1),
                    current_label="中止",
                    message=f"今：中止｜{i-1}/{total}まで処理して中止｜登録{ok} スキップ{skip} エラー{err}",
                    result_blob=blob,
                )
                return
            _v278_bg_update(
                db_path, job_id,
                current_label=f"{vn} {n}R",
                message=f"{i-1}/{total} 完了｜今は選手履歴を取得中",
                done_count=i - 1,
            )
            item = {"venue": vn, "R": n, "status": "", "message": "", "added": 0}
            try:
                one = _v319_import_player_history_one_race(
                    db_path, ymd, vn, n, min_rows=min_rows,
                    on_step=lambda msg, vn=vn, n=n, i=i, total=total: _v278_bg_update(
                        db_path, job_id,
                        current_label=f"{vn} {n}R",
                        message=f"{i-1}/{total} 完了｜今は{msg}",
                        done_count=i - 1,
                    ),
                )
                item["status"] = one.get("status") or "ok"
                item["message"] = one.get("message") or ""
                item["phase"] = one.get("phase") or ""
                item["added"] = int(one.get("added") or 0)
                added += item["added"]
                if one.get("notify_message"):
                    item["notify_message"] = one.get("notify_message")
                st_one = str(item["status"] or "")
                if st_one == "skip":
                    skip += 1
                elif st_one in ("error", "failed"):
                    err += 1
                else:
                    ok += 1
            except Exception as exc:
                item["status"] = "error"
                item["phase"] = "exception"
                item["message"] = f"{type(exc).__name__}: {exc}"
                err += 1
            _ = details.append(item)
            fail_hint = ""
            if str(item.get("status") or "") in ("error", "failed"):
                fail_hint = f"｜失敗:{vn}{n}R"
            mid_blob = zlib.compress(pickle.dumps({
                "ok": ok, "skip": skip, "error": err, "added": added, "details": list(details),
                "partial": True,
                "summary": (
                    f"途中経過 {i}/{total}｜履歴登録{ok}R スキップ{skip}R エラー{err}R"
                    f"（履歴+{added}件）"
                ),
            }, protocol=4), 6)
            _v278_bg_update(
                db_path, job_id,
                done_count=i,
                current_label=f"{vn} {n}R {item['status']}",
                message=f"{i}/{total}｜履歴登録{ok} スキップ{skip} エラー{err}（履歴+{added}）{fail_hint}",
                result_blob=mid_blob,
            )
            time_module.sleep(0.2)
        failed_keys = [
            f"{d.get('venue','')}{d.get('R','')}R"
            for d in details
            if str(d.get("status") or "") in ("error", "failed")
        ]
        fail_summary = ("｜失敗: " + ", ".join(failed_keys[:8])) if failed_keys else ""
        blob = zlib.compress(pickle.dumps({
            "ok": ok, "skip": skip, "error": err, "added": added, "details": details,
            "failed_keys": failed_keys,
            "summary": (
                f"選手履歴の登録が完了しました。履歴登録：{ok}R / 変化なし：{skip}R"
                f" / 失敗：{err}R / 履歴+{added}件"
            ),
        }, protocol=4), 6)
        # 完了通知（ntfy）。送信失敗は無視する。
        try:
            topic = str(__import__("os").environ.get("AUTORACE_NTFY_TOPIC", "notify") or "notify").strip()
            body = (
                f"選手履歴のみ取込 完了 {ymd}\n"
                f"履歴登録{ok}R / 変化なし{skip}R / 失敗{err}R / 履歴+{added}件{fail_summary}"
            )
            payload = {
                "topic": topic,
                "title": "AutoRaceAI 選手履歴取込完了",
                "message": body,
                "priority": 4,
                "tags": ["bust_in_silhouette"],
            }
            req_ntfy = urllib.request.Request(
                "https://ntfy.sh",
                data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
                method="POST",
                headers={"Content-Type": "application/json; charset=utf-8"},
            )
            with urllib.request.urlopen(req_ntfy, timeout=8) as resp:
                resp.read()
        except Exception:
            pass
        _v278_bg_update(
            db_path, job_id,
            status="completed",
            finished_at=_v228_now_jst_iso(),
            done_count=total,
            current_label="完了",
            message=(
                f"選手履歴の登録が完了しました｜履歴登録{ok}R / 変化なし{skip}R"
                f" / 失敗{err}R / 履歴+{added}件{fail_summary}"
            ),
            result_blob=blob,
        )
    except Exception as exc:
        _v278_bg_update(
            db_path, job_id,
            status="failed",
            finished_at=_v228_now_jst_iso(),
            error_text=f"{type(exc).__name__}: {exc}",
            message=f"失敗: {exc}",
        )
    finally:
        try:
            with _V278_BG_LOCK:
                _V278_BG_THREADS.pop(int(job_id), None)
        except Exception:
            pass


def _v319_bg_history_start(
    db_path: str, ymd: str, venues: list[str],
    min_rows: int = 30, max_races: int = 12,
) -> dict:
    """選手履歴のみ取込をバックグラウンドで開始する。"""
    _v278_bg_ensure_table(db_path)
    if _v279_bg_prediction_any_active(db_path):
        return {"ok": False, "reason": "別の予測・再シミュレーション・取込が動いています。完了後に開始してください。"}
    if _v319_bg_history_any_active(db_path):
        return {"ok": False, "reason": "選手履歴の取込が既に動いています。完了後に開始してください。"}
    if not venues:
        return {"ok": False, "reason": "開催場がありません。"}
    now = _v228_now_jst_iso()
    with sqlite3.connect(str(db_path), timeout=30.0) as con:
        con.execute("PRAGMA busy_timeout=30000")
        cur = con.execute("""
            INSERT INTO v278_background_jobs(
                job_type,app_version,status,created_at,updated_at,limit_count,force_current,
                done_count,total_count,current_label,message
            ) VALUES (?,?,?,?,?,?,?,?,?,?,?)
        """, (
            "player_history_import", str(_V231_APP_VERSION), "queued", now, now, len(venues), 0,
            0, 0, "準備中", f"{ymd} {','.join(venues)} の選手履歴のみ取り込みます",
        ))
        con.commit()
        job_id = int(cur.lastrowid or 0)
    req = {
        "ymd": ymd, "venues": list(venues),
        "min_rows": int(min_rows), "max_races": int(max_races),
    }
    th = threading.Thread(
        target=_v319_bg_history_worker, args=(str(db_path), job_id, req),
        daemon=True, name=f"autorace-bg-history-{job_id}",
    )
    with _V278_BG_LOCK:
        _V278_BG_THREADS[job_id] = th
    th.start()
    return {"ok": True, "job_id": job_id}


RESULT_VENUES = ["飯塚", "山陽", "浜松", "川口", "伊勢崎"]
PREDICTION_VENUES = ["川口", "伊勢崎", "浜松", "山陽", "飯塚"]
_V315_EVENT_VENUE_MAP = (
    ("プレミアムカップ", "伊勢崎"),
    ("共同通信社杯", "伊勢崎"),
    ("浜松記念", "浜松"),
    ("Ｇ２浜松記念", "浜松"),
    ("G2浜松記念", "浜松"),
    ("川口記念", "川口"),
    ("飯塚記念", "飯塚"),
)


def _v315_header_before_entries(text: str) -> str:
    source = str(text or "")
    parts = re.split(
        r"(?:選手名\(LG\)|予想印はログイン|予想印\s*車|出走表オッズ結果|着順\s*車番)",
        source,
        maxsplit=1,
    )
    return parts[0] if parts else source


def _v315_detect_prediction_venue(text: str) -> tuple[str, str]:
    """出走表ヘッダーと開催名から開催場を推定する。選手所属LGは使わない。"""
    header = _v315_header_before_entries(text)
    normalized = re.sub(r"[\s　]+", "", header)
    for token, venue in _V315_EVENT_VENUE_MAP:
        if token in normalized or token in str(text or ""):
            return venue, "開催名"
    venue_patterns = [
        ("川口", ["川口市営", "川口ナイトレース", "川口ナイター", "川口開催"]),
        ("伊勢崎", ["伊勢崎市営", "伊勢崎ナイトレース", "伊勢崎ナイター", "伊勢崎開催"]),
        ("浜松", ["浜松市営", "浜松記念", "浜松開催"]),
        ("山陽", ["山陽小野田市営", "山陽市営", "山陽ミッドナイト", "山陽開催"]),
        ("飯塚", ["飯塚市営", "飯塚ミッドナイト", "飯塚開催"]),
    ]
    for venue, patterns in venue_patterns:
        if any(p in normalized for p in patterns):
            return venue, "タイトル"
    header_hits = [v for v in PREDICTION_VENUES if v in normalized]
    if len(header_hits) == 1:
        return header_hits[0], "タイトル"
    return "", ""

def _detect_result_venue_from_title(text: str) -> str:
    """結果ページの開催タイトル部分だけから開催場を判定する。

    選手名・所属LGが並ぶ「着順」以降は対象外。タイトルで確定できない場合は
    空文字を返し、画面側で手動選択させる。
    """
    header = str(text or "").split("着順", 1)[0]
    normalized = re.sub(r"[\s　]+", "", header)
    venue_patterns = [
        ("山陽", ["山陽小野田市営", "山陽市営", "山陽ミッドナイト", "山陽オーバーミッドナイト"]),
        ("飯塚", ["飯塚市営", "飯塚ミッドナイト", "飯塚オーバーミッドナイト"]),
        ("浜松", ["浜松市営", "浜松記念", "Ｇ２浜松記念", "G2浜松記念"]),
        ("川口", ["川口市営", "川口ナイター"]),
        ("伊勢崎", ["伊勢崎市営", "伊勢崎ナイター"]),
    ]
    for venue, patterns in venue_patterns:
        if any(pattern in normalized for pattern in patterns):
            return venue

    # 「開催名＋場名」がタイトルに明記されている場合だけ補助判定する。
    title_words = ("記念", "市営", "開催", "ミッドナイト", "ナイター", "普通開催", "オーバーミッドナイト")
    candidates = [venue for venue in RESULT_VENUES if venue in normalized]
    if len(candidates) == 1 and any(word in normalized for word in title_words):
        return candidates[0]
    return ""

def _format_jst(value) -> str:
    if value is None or str(value).strip() in {"", "None", "NaT"}:
        return ""
    try:
        ts = pd.to_datetime(value, errors="coerce")
        if pd.isna(ts):
            return str(value)
        if getattr(ts, "tzinfo", None) is None:
            ts = ts.tz_localize("UTC")
        return ts.tz_convert("Asia/Tokyo").strftime("%Y-%m-%d %H:%M:%S")
    except Exception:
        return str(value)

def _jst_datetime_columns(frame: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(frame, pd.DataFrame):
        return frame
    out = frame.copy()
    for col in out.columns:
        if any(token in str(col) for token in ["登録日時", "保存日時", "更新日時", "作成日時", "分析日時", "started_at", "finished_at"]):
            out[col] = out[col].map(_format_jst)
    return out
GENERAL_REMINDER_NTFY_BASE = "https://ntfy.sh"


def v123_parse_general_schedule_text(text_value: str) -> tuple[date | None, time | None, str | None]:
    """貼り付け文から日付・締切時刻・短い予定名を抽出する。"""
    source = str(text_value or "")

    parsed_date = None
    date_match = re.search(r"(20\d{2})年\s*(\d{1,2})月\s*(\d{1,2})日", source)
    if date_match:
        try:
            parsed_date = date(int(date_match.group(1)), int(date_match.group(2)), int(date_match.group(3)))
        except ValueError:
            parsed_date = None

    # 出走時刻より締切時刻を優先する。公式ページでは「19:51 締切」などの形が多い。
    parsed_time = None
    deadline_patterns = [
        r"(\d{1,2}):(\d{2})\s*(?:投票)?締切(?:時刻)?",
        r"(?:投票)?締切(?:予定|時刻)?\s*[:：]?\s*(\d{1,2}):(\d{2})",
        r"締切まで[^\n]*?(\d{1,2}):(\d{2})",
    ]
    for pattern in deadline_patterns:
        match = re.search(pattern, source)
        if not match:
            continue
        hour, minute = int(match.group(1)), int(match.group(2))
        if 0 <= hour <= 23 and 0 <= minute <= 59:
            parsed_time = time(hour=hour, minute=minute)
            break

    # 通知タイトルは出走表ヘッダーの開催名とレース番号から「川口3R」の形にする。
    # 選手欄の所属LGを開催場として誤使用しないよう、「予想印」「着順」より前だけを見る。
    schedule_header = re.split(r"(?:予想印|着順\s*車番|選手名\(LG\))", source, maxsplit=1)[0]
    normalized_header = re.sub(r"[\s　]+", "", schedule_header)
    venue_patterns = [
        ("川口", ["川口市営", "川口ナイトレース", "川口ナイター", "川口開催"]),
        ("伊勢崎", ["伊勢崎市営", "伊勢崎ナイトレース", "伊勢崎ナイター", "伊勢崎開催"]),
        ("浜松", ["浜松市営", "浜松記念", "浜松開催"]),
        ("山陽", ["山陽小野田市営", "山陽市営", "山陽ミッドナイト", "山陽開催"]),
        ("飯塚", ["飯塚市営", "飯塚ミッドナイト", "飯塚開催"]),
    ]
    parsed_venue = ""
    for venue, patterns in venue_patterns:
        if any(pattern in normalized_header for pattern in patterns):
            parsed_venue = venue
            break
    if not parsed_venue:
        header_candidates = [venue for venue in RESULT_VENUES if venue in normalized_header]
        if len(header_candidates) == 1:
            parsed_venue = header_candidates[0]

    race_match = re.search(r"(?m)^\s*(\d{1,2})\s*[RＲ]\s*$", schedule_header)
    if race_match is None:
        race_match = re.search(r"(?:^|[^0-9])(\d{1,2})\s*[RＲ](?:[^0-9]|$)", schedule_header)

    parsed_title = None
    if parsed_venue and race_match:
        parsed_title = f"{parsed_venue}{int(race_match.group(1))}R"
    else:
        for raw_line in source.splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if re.search(r"20\d{2}年|\d{1,2}:\d{2}|発走|開始|締切", line):
                continue
            if len(line) <= 60:
                parsed_title = line
                break

    return parsed_date, parsed_time, parsed_title


def v123_schedule_ntfy_reminder(title: str, event_date: date, event_time: time, topic: str) -> tuple[datetime, datetime]:
    """締切10分前通知をntfyへ予約する。"""
    clean_title = str(title or "").strip()
    clean_topic = str(topic or "").strip()
    if not clean_title:
        raise ValueError("予定名を入力してください。")
    if not clean_topic:
        raise ValueError("ntfyトピック名を入力してください。")
    if any(ch in clean_topic for ch in "/?# "):
        raise ValueError("トピック名には空白や / ? # を使わないでください。")

    event_dt = datetime.combine(event_date, event_time, tzinfo=GENERAL_REMINDER_JST)
    notify_dt = event_dt - timedelta(minutes=10)
    now = datetime.now(GENERAL_REMINDER_JST)
    if notify_dt <= now:
        raise ValueError("通知予定時刻が過ぎています。締切時刻を10分以上先にしてください。")
    if notify_dt - now > timedelta(days=3):
        raise ValueError("ntfy.shの予約通知は最大3日先です。3日以内の予定を指定してください。")

    endpoint = f"{GENERAL_REMINDER_NTFY_BASE}/{urllib.parse.quote(clean_topic, safe='')}"
    message = f"{clean_title}\n締切時刻: {event_dt.strftime('%Y/%m/%d %H:%M')}"
    # HTTPヘッダーはASCIIのみ。日本語タイトルはURLエンコードして送る。
    # 本文はUTF-8バイト列にすることでUnicodeEncodeErrorを防ぐ。
    headers = {
        "At": str(int(notify_dt.timestamp())),
        "Title": urllib.parse.quote("締切の10分前です", safe=""),
        "Priority": "high",
        "Tags": "bell",
        "Content-Type": "text/plain; charset=utf-8",
    }
    request = urllib.request.Request(
        endpoint,
        data=message.encode("utf-8", errors="strict"),
        method="POST",
        headers=headers,
    )
    try:
        with urllib.request.urlopen(request, timeout=15) as response:
            if int(getattr(response, "status", 200)) >= 400:
                raise RuntimeError(f"ntfy応答エラー: {response.status}")
    except UnicodeEncodeError as exc:
        raise RuntimeError(
            "通知送信時の文字コード変換に失敗しました。日本語はUTF-8本文として送信する必要があります。"
        ) from exc
    return event_dt, notify_dt


def _v139_ntfy_request(
    topic: str,
    message: str,
    *,
    title: str = "一般予定通知",
    notify_at: datetime | None = None,
) -> dict:
    """ntfyへサーバー側から送信する。ブラウザCORSやiOS WebViewの影響を受けない。"""
    clean_topic = str(topic or "").strip()
    if not clean_topic:
        raise ValueError("ntfyトピック名を入力してください。")
    if any(ch in clean_topic for ch in "/?# "):
        raise ValueError("トピック名には空白や / ? # を使わないでください。")

    # 日本語タイトルをHTTPヘッダーへ入れると、環境によってLatin-1変換や
    # URLエンコード文字列の表示が起きるため、UTF-8のJSON本文で送信する。
    endpoint = GENERAL_REMINDER_NTFY_BASE
    payload = {
        "topic": clean_topic,
        "title": str(title or "一般予定通知").strip() or "一般予定通知",
        "message": str(message),
        "priority": 4,
        "tags": ["bell"],
    }
    if notify_at is not None:
        # ntfyのJSON Publish APIでは予約指定は `delay` を使用する。
        # `at` はJSON項目として解釈されず即時配信になる環境があるため使用しない。
        scheduled_unix = int(notify_at.astimezone(timezone.utc).timestamp())
        payload["delay"] = str(scheduled_unix)

    request = urllib.request.Request(
        endpoint,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8", errors="strict"),
        method="POST",
        headers={"Content-Type": "application/json; charset=utf-8"},
    )
    try:
        with urllib.request.urlopen(request, timeout=8) as response:
            raw = response.read().decode("utf-8", errors="replace")
            if int(getattr(response, "status", 200)) >= 400:
                raise RuntimeError(f"ntfy応答エラー: {response.status} {raw[:160]}")
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"ntfy HTTP {exc.code}: {body[:180]}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"ntfyへ接続できませんでした: {exc.reason}") from exc

    try:
        return json.loads(raw) if raw else {}
    except Exception:
        return {"raw": raw[:200]}


def _v139_general_reminder_defaults() -> None:
    base = datetime.now(GENERAL_REMINDER_JST) + timedelta(minutes=30)
    st.session_state.setdefault("v139_reminder_source", "")
    st.session_state.setdefault("v139_reminder_title", "")
    st.session_state.setdefault("v139_reminder_date", base.date())
    st.session_state.setdefault("v139_reminder_time", base.time().replace(second=0, microsecond=0))
    # 初期トピックはユーザー指定の notify。既存セッションが空欄でも補完する。
    if not str(st.session_state.get("v139_reminder_topic", "")).strip():
        st.session_state["v139_reminder_topic"] = "notify"
    st.session_state.setdefault("v150_reminder_timing", "10分前")


def v123_render_general_reminder_tab() -> None:
    """Streamlit標準UIで一般予定通知を表示する。ダイアログ内だけ再実行される。"""
    _v139_general_reminder_defaults()

    st.caption("貼り付け文の締切時刻を読み取り、締切30分前・10分前・5分前、または組み合わせて通知します。")
    st.text_area(
        "予定情報を貼り付け（任意）",
        key="v139_reminder_source",
        height=115,
        placeholder="例：19:51 締切\n2026年8月1日(土)\n一般戦 3100m",
    )
    if st.button("日付・締切時刻を自動入力", use_container_width=True, key="v139_parse_reminder"):
        parsed_date, parsed_time, parsed_title = v123_parse_general_schedule_text(
            st.session_state.get("v139_reminder_source", "")
        )
        if parsed_date:
            st.session_state["v139_reminder_date"] = parsed_date
        if parsed_time:
            st.session_state["v139_reminder_time"] = parsed_time
        if parsed_title:
            # 開催場＋レース番号を読めた場合は、古い予定名が残っていても更新する。
            st.session_state["v139_reminder_title"] = parsed_title
        if parsed_date or parsed_time:
            st.session_state["v139_reminder_message"] = ("success", "日付・締切時刻を自動入力しました。")
        else:
            st.session_state["v139_reminder_message"] = ("warning", "日付または締切時刻を読み取れませんでした。")
        st.rerun(scope="fragment")

    st.text_input("予定名", key="v139_reminder_title", placeholder="例：オンライン面談")
    col1, col2 = st.columns(2)
    with col1:
        st.date_input("予定日", key="v139_reminder_date")
    with col2:
        st.time_input("締切時刻", key="v139_reminder_time", step=60)
    st.text_input(
        "ntfyトピック名",
        key="v139_reminder_topic",
        placeholder="推測されにくい長い文字列",
        help="iPhoneのntfyアプリで同じトピックを購読してください。",
    )
    st.segmented_control(
        "通知タイミング",
        options=["30分前", "10分前", "5分前", "30分前と10分前", "10分前と5分前", "30分前・10分前・5分前"],
        key="v150_reminder_timing",
        selection_mode="single",
    )

    test_col, reserve_col = st.columns(2)
    with test_col:
        if st.button("今すぐテスト", use_container_width=True, key="v139_test_ntfy"):
            try:
                with st.spinner("テスト通知を送信中…"):
                    test_title = str(st.session_state.get("v139_reminder_title", "")).strip() or "通知テスト"
                    reply = _v139_ntfy_request(
                        st.session_state.get("v139_reminder_topic", ""),
                        "一般予定通知の接続テストです。",
                        title=test_title,
                    )
                receipt = f" 受付ID: {reply.get('id')}" if reply.get("id") else ""
                st.session_state["v139_reminder_message"] = ("success", f"テスト通知を送信しました。{receipt}")
            except Exception as exc:
                st.session_state["v139_reminder_message"] = ("error", str(exc))
            st.rerun(scope="fragment")

    with reserve_col:
        timing_label = st.session_state.get("v150_reminder_timing", "10分前") or "10分前"
        if st.button("通知を予約", type="primary", use_container_width=True, key="v139_reserve_ntfy"):
            try:
                title = str(st.session_state.get("v139_reminder_title", "")).strip()
                if not title:
                    raise ValueError("予定名を入力してください。")
                event_dt = datetime.combine(
                    st.session_state["v139_reminder_date"],
                    st.session_state["v139_reminder_time"],
                    tzinfo=GENERAL_REMINDER_JST,
                )
                selected = st.session_state.get("v150_reminder_timing", "10分前") or "10分前"
                lead_minutes = {
                    "30分前": [30],
                    "10分前": [10],
                    "5分前": [5],
                    "30分前と10分前": [30, 10],
                    "10分前と5分前": [10, 5],
                    "30分前・10分前・5分前": [30, 10, 5],
                }.get(selected, [10])
                now = datetime.now(GENERAL_REMINDER_JST)
                notify_times = [(minutes, event_dt - timedelta(minutes=minutes)) for minutes in lead_minutes]
                expired = [minutes for minutes, dt in notify_times if dt <= now]
                if expired:
                    minimum = max(lead_minutes)
                    raise ValueError(f"通知時刻が過ぎています。締切時刻を{minimum}分以上先にしてください。")
                if any(dt - now > timedelta(days=3) for _, dt in notify_times):
                    raise ValueError("ntfy.shの予約通知は最大3日先です。")

                receipts = []
                with st.spinner("通知を予約中…"):
                    for minutes, notify_dt in notify_times:
                        message = (
                            f"締切{minutes}分前です。\n"
                            f"締切時刻: {event_dt.strftime('%Y/%m/%d %H:%M')}"
                        )
                        reply = _v139_ntfy_request(
                            st.session_state.get("v139_reminder_topic", ""),
                            message,
                            title=title,
                            notify_at=notify_dt,
                        )
                        receipt = f" / 受付ID: {reply.get('id')}" if reply.get("id") else ""
                        _ = receipts.append(f"{notify_dt.strftime('%Y/%m/%d %H:%M')}（{minutes}分前）{receipt}")
                st.session_state["v139_reminder_message"] = (
                    "success",
                    "通知を予約しました：" + " ／ ".join(receipts),
                )
            except Exception as exc:
                st.session_state["v139_reminder_message"] = ("error", str(exc))
            st.rerun(scope="fragment")

    message = st.session_state.pop("v139_reminder_message", None)
    if message:
        kind, text = message
        getattr(st, kind)(text)

    st.caption("通知が届かない場合は、ntfyアプリの購読トピックとiPhoneの通知許可を確認してください。")

def qident(name: str) -> str:
    return '"' + str(name).replace('"', '""') + '"'


def db_summary(db_path: str) -> dict:
    path = Path(db_path)
    info = {"exists": path.exists(), "size": path.stat().st_size if path.exists() else 0, "tables": []}
    if not path.exists():
        return info
    with sqlite3.connect(path) as con:
        info["tables"] = [r[0] for r in con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        ).fetchall()]
        if "players" in info["tables"]:
            info["players"] = int(con.execute("SELECT COUNT(*) FROM players").fetchone()[0])
        if "race_history" in info["tables"]:
            info["history"] = int(con.execute("SELECT COUNT(*) FROM race_history").fetchone()[0])
        if "v15_player_history_imports" in info["tables"]:
            info["import_players"] = int(con.execute(
                "SELECT COUNT(DISTINCT player_name) FROM v15_player_history_imports WHERE player_name IS NOT NULL AND player_name <> ''"
            ).fetchone()[0])
            info["import_history"] = int(con.execute("SELECT COUNT(*) FROM v15_player_history_imports").fetchone()[0])
    return info





def _v138_db_token(db_path: str) -> tuple[str, int, int]:
    """DB内容が変わった時だけキャッシュを更新する軽量キー。"""
    path = Path(db_path)
    if not path.exists():
        return (str(path), 0, 0)
    stat = path.stat()
    return (str(path), int(stat.st_mtime_ns), int(stat.st_size))


@st.cache_data(show_spinner=False, max_entries=16)
def _v138_cached_db_summary(db_path: str, token: tuple) -> dict:
    del token
    return db_summary(db_path)


